INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91669, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "库", "is_correct": true, "explanation": "库：放很多东西的大房子，是本题的目标词。"}, {"text": "客", "is_correct": false, "explanation": "kè 与 kù 韵母不同（e 与 u），意思是“客人”。"}, {"text": "故", "is_correct": false, "explanation": "gù 与 kù 声母不同（g 与 k，不送气与送气相对），意思是“缘故”，如故事中的“故”。"}, {"text": "户", "is_correct": false, "explanation": "hù 与 kù 声母不同（h 与 k），意思是“门户、住户”。"}, {"text": "枯", "is_correct": false, "explanation": "kū（第一声）与 kù（第四声）声调不同，意思是“干枯、枯萎”。"}], "explanations": {"库": "库：放很多东西的大房子，是本题的目标词。", "客": "kè 与 kù 韵母不同（e 与 u），意思是“客人”。", "故": "gù 与 kù 声母不同（g 与 k，不送气与送气相对），意思是“缘故”，如故事中的“故”。", "户": "hù 与 kù 声母不同（h 与 k），意思是“门户、住户”。", "枯": "kū（第一声）与 kù（第四声）声调不同，意思是“干枯、枯萎”。"}, "sentence_index": null, "correct_answer": "库"}, "level_3": {"options": [{"text": "库", "is_correct": true, "explanation": "正确：库是放东西的大房子，“库里黑黑的，我们带着手电筒进去”符合语境。"}, {"text": "字", "is_correct": false, "explanation": "语义：字是文字，没有空间可以走进去，与“带着手电筒进去”不符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是能走进去的空间，与“进去”的动作矛盾。"}, {"text": "皮包", "is_correct": false, "explanation": "搭配：“进去”的对象一般是房间、洞穴等空间，不说走进皮包里。"}], "explanations": {"库": "正确：库是放东西的大房子，“库里黑黑的，我们带着手电筒进去”符合语境。", "字": "语义：字是文字，没有空间可以走进去，与“带着手电筒进去”不符。", "天空": "语义：天空不是能走进去的空间，与“进去”的动作矛盾。", "皮包": "搭配：“进去”的对象一般是房间、洞穴等空间，不说走进皮包里。"}, "sentence_index": 6, "correct_answer": "库"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "库里的老师很多，学生们都很喜欢。", "explanation": "这里应该用〈学校〉。库是放东西的房子，不是教书育人的地方。"}, {"text": "库里的孩子们在玩滑梯，大家都很开心。", "explanation": "这里应该用〈游乐场〉。库是放东西的房子，没有滑梯，也不是孩子们玩耍的地方。"}, {"text": "库里的病人很多，医生们都很忙。", "explanation": "这里应该用〈医院〉。库是放东西的房子，不是给病人看病的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村口那台旧库已经空了很久。", "corrected_sentence": "村口那座旧库已经空了很久。", "error_description": "量词错误：库是房子，应用「座」；「台」用于机器、设备，不能用于库。应改为「那座旧库」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "后院那辆旧库已经拆掉了，只剩一块空地。", "corrected_sentence": "后院那座旧库已经拆掉了，只剩一块空地。", "error_description": "量词错误：「辆」用于车辆，不能用于库。库是建筑，应用「座」，应改为「后院那座旧库」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91670, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91670, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91670, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "储存大量物资的建筑；仓库。", "primary_collocate": null, "pronunciation": "kù", "ipa": "kʰu˥˩", "syllable_count": 1, "sentences": [{"text": "粮食都放在库里，下雨也不怕。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个库很大，能放一万吨米。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把新到的货搬进库里。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "库里堆满了苹果，门口有人看着。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货太多了，库里已经放不下了。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上都去库里看一看，门锁好了没有。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "库的门是铁做的，很结实。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天来以前，农民把玉米送到库里。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个库离火车站很近，运货很方便。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新库建好了，旧库就不用了。", "target_word": "库", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "仓库", "label": "复合"}, {"form": "车库", "label": "复合"}, {"form": "座", "label": "量词"}, {"form": "庫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "存放粮食、货物等大量物资的建筑，即仓库", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33653423-e2ed-4a50-b920-a2c54289c879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91670, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "库", "is_correct": true, "explanation": "库：储存粮食、货物等大量物资的建筑，即仓库，是本题的目标词。"}, {"text": "苦", "is_correct": false, "explanation": "kǔ（第三声）与 kù（第四声）声调不同，意思是“苦”，指味道或生活艰难。"}, {"text": "哭", "is_correct": false, "explanation": "kū（第一声）与 kù（第四声）声调不同，意思是“哭”，指流眼泪。"}, {"text": "去", "is_correct": false, "explanation": "qù 与 kù 声母不同（q 与 k），意思是“去”，表示到某处。"}, {"text": "课", "is_correct": false, "explanation": "kè 与 kù 韵母不同（e 与 u），意思是“课”，如上课、课本。"}], "explanations": {"库": "库：储存粮食、货物等大量物资的建筑，即仓库，是本题的目标词。", "苦": "kǔ（第三声）与 kù（第四声）声调不同，意思是“苦”，指味道或生活艰难。", "哭": "kū（第一声）与 kù（第四声）声调不同，意思是“哭”，指流眼泪。", "去": "qù 与 kù 声母不同（q 与 k），意思是“去”，表示到某处。", "课": "kè 与 kù 韵母不同（e 与 u），意思是“课”，如上课、课本。"}, "sentence_index": null, "correct_answer": "库"}, "level_3": {"options": [{"text": "库", "is_correct": true, "explanation": "正确：库是储存物资的建筑，“粮食放在库里”符合语境。"}, {"text": "杯", "is_correct": false, "explanation": "语义：杯子容量太小，装不下大量粮食，与“都放在”的语境矛盾。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是露天场所，粮食放在里面下雨会被淋湿，与后半句“下雨也不怕”矛盾。"}, {"text": "院子", "is_correct": false, "explanation": "语义：院子是露天场所，粮食放在里面下雨会被淋湿，与后半句“下雨也不怕”矛盾。"}], "explanations": {"库": "正确：库是储存物资的建筑，“粮食放在库里”符合语境。", "杯": "语义：杯子容量太小，装不下大量粮食，与“都放在”的语境矛盾。", "花园": "语义：花园是露天场所，粮食放在里面下雨会被淋湿，与后半句“下雨也不怕”矛盾。", "院子": "语义：院子是露天场所，粮食放在里面下雨会被淋湿，与后半句“下雨也不怕”矛盾。"}, "sentence_index": 0, "correct_answer": "库"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个库每天能生产一千台机器。", "explanation": "这里应该用〈厂〉。库是储存物资的建筑，不能用来生产；生产机器的是工厂。"}, {"text": "我家的库有三间卧室，全家都住在里面。", "explanation": "这里应该用〈房子〉。库专指存放物资的建筑，不用来住人，不能说库有卧室。"}, {"text": "这座库每天接待很多客人，办理存款和取款。", "explanation": "这里应该用〈银行〉。库是存放物资的建筑，不办理存款和取款；存取钱要去银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91670, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "库", "is_correct": true, "explanation": "库：储存粮食、货物等大量物资的建筑，即仓库，是本题的目标词。"}, {"text": "客", "is_correct": false, "explanation": "kè 与 kù 韵母不同（e 与 u），意思是“客人”。"}, {"text": "故", "is_correct": false, "explanation": "gù 与 kù 声母不同（g 与 k，不送气与送气相对），意思是“缘故”，如故事中的“故”。"}, {"text": "户", "is_correct": false, "explanation": "hù 与 kù 声母不同（h 与 k），意思是“门户、住户”。"}, {"text": "枯", "is_correct": false, "explanation": "kū（第一声）与 kù（第四声）声调不同，意思是“干枯、枯萎”。"}], "explanations": {"库": "库：储存粮食、货物等大量物资的建筑，即仓库，是本题的目标词。", "客": "kè 与 kù 韵母不同（e 与 u），意思是“客人”。", "故": "gù 与 kù 声母不同（g 与 k，不送气与送气相对），意思是“缘故”，如故事中的“故”。", "户": "hù 与 kù 声母不同（h 与 k），意思是“门户、住户”。", "枯": "kū（第一声）与 kù（第四声）声调不同，意思是“干枯、枯萎”。"}, "sentence_index": null, "correct_answer": "库"}, "level_3": {"options": [{"text": "库", "is_correct": true, "explanation": "正确：库是存放物资的建筑，“库的门是铁做的”指仓库的门。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不设门，“树的门”讲不通。"}, {"text": "字", "is_correct": false, "explanation": "语义：字是文字，没有门，与“铁做的，很结实”无法对应。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：书包的开口一般是拉链，不说“门”，也不用铁来做。"}], "explanations": {"库": "正确：库是存放物资的建筑，“库的门是铁做的”指仓库的门。", "树": "语义：树不设门，“树的门”讲不通。", "字": "语义：字是文字，没有门，与“铁做的，很结实”无法对应。", "书包": "搭配：书包的开口一般是拉链，不说“门”，也不用铁来做。"}, "sentence_index": 6, "correct_answer": "库"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "库里的医生很多，病人都很放心。", "explanation": "这里应该用〈医院〉。库是存放物资的建筑，不是给病人看病的地方。"}, {"text": "库里的学生很多，老师们都很认真。", "explanation": "这里应该用〈学校〉。库是存放物资的建筑，不是学生上课的地方。"}, {"text": "库一直开到门口。", "explanation": "这里应该用〈汽车〉。库是存放物资的建筑，不会开动；能开到门口的是汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那台库已经很旧了，需要修一修。", "corrected_sentence": "那座库已经很旧了，需要修一修。", "error_description": "量词错误：库是建筑，应用「座」；「台」用于机器、设备，不能用于库。应改为「那座库」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那把旧库要拆了，新库已经建好。", "corrected_sentence": "那座旧库要拆了，新库已经建好。", "error_description": "量词错误：「把」用于有把手的器具，不能用于库。库是建筑，应用「座」，应改为「那座旧库」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
