INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91671, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不管有没有危险，还是去做。", "primary_collocate": null, "pronunciation": "bù gù", "ipa": "pu˥˩ ku˥˩", "syllable_count": 2, "sentences": [{"text": "消防员不顾危险，冲进了大火里。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不顾大雨，骑车去接朋友。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生不顾自己生病，还在工作。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不顾受伤的腿，跑完了比赛。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不顾下雪路滑，去学校接孩子。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察不顾生命危险，救出了孩子。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家不顾天气很冷，在外面等了三个小时。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人不顾河水很深，跳下去救小狗。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不顾发烧，坚持去参加考试。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位记者不顾危险，去了地震的地方。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "面对危险、困难或不利条件，仍然坚持去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed705e94-968e-41c7-a6e9-f6ef3ffbe67a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91671, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不顾", "is_correct": true, "explanation": "bù gù（第四声），意思是不管危险或困难仍去做。"}, {"text": "布谷", "is_correct": false, "explanation": "gǔ（第三声）与 gù（第四声）声调不同，意思是布谷鸟。"}, {"text": "不够", "is_correct": false, "explanation": "gòu 与 gù 韵母不同，意思是数量或程度不足。"}, {"text": "不过", "is_correct": false, "explanation": "guò 与 gù 韵母不同，意思是“但是”或“超过”。"}], "explanations": {"不顾": "bù gù（第四声），意思是不管危险或困难仍去做。", "布谷": "gǔ（第三声）与 gù（第四声）声调不同，意思是布谷鸟。", "不够": "gòu 与 gù 韵母不同，意思是数量或程度不足。", "不过": "guò 与 gù 韵母不同，意思是“但是”或“超过”。"}, "sentence_index": null, "correct_answer": "不顾"}, "level_3": {"options": [{"text": "不顾", "is_correct": true, "explanation": "“不顾”表示不管危险仍去做，与“冲进了大火里”的救人行动相符。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：“躲避”表示躲开，与“冲进了大火里”正好相反。"}, {"text": "害怕", "is_correct": false, "explanation": "语义：“害怕”表示畏惧，与“冲进了大火里”的行动相矛盾。"}, {"text": "忌惮", "is_correct": false, "explanation": "语义：“忌惮”表示顾虑、畏惧，与“冲进了大火里”的行动相矛盾。"}], "explanations": {"不顾": "“不顾”表示不管危险仍去做，与“冲进了大火里”的救人行动相符。", "躲避": "语义：“躲避”表示躲开，与“冲进了大火里”正好相反。", "害怕": "语义：“害怕”表示畏惧，与“冲进了大火里”的行动相矛盾。", "忌惮": "语义：“忌惮”表示顾虑、畏惧，与“冲进了大火里”的行动相矛盾。"}, "sentence_index": 0, "correct_answer": "不顾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不顾同学的感受，只想先把自己的事做完。", "explanation": "这是“不顾”的另一个义项“不考虑、不顾及”，表示不理会他人的感受，与“不管有没有危险，还是去做”的意思不同。不需要换词。"}, {"text": "我今天不顾天晴，一直在家里写报告。", "explanation": "这里不能用“不顾”。“不顾”后面要接需要克服的困难或不利条件，“天晴”并不构成困难，与“在家里写报告”之间没有冲突，应直接说“我今天一直在家里写报告”。"}, {"text": "他不顾下雨，在家里看书。", "explanation": "这里不能用“不顾”。“不顾”后面的行为要克服危险或困难，“在家里看书”没有需要克服的困难，应直接说“他在家里看书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91671, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不顾", "is_correct": true, "explanation": "“不顾”表示不管天气寒冷仍坚持，与“在外面等了三个小时”相符。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”表示躲开，与“在外面等了三个小时”的停留相矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”多搭配美好的事物，不能与“天气很冷”搭配，句子不通。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象一般是人或帮助，不能接“天气很冷”作宾语。"}], "explanations": {"不顾": "“不顾”表示不管天气寒冷仍坚持，与“在外面等了三个小时”相符。", "逃避": "语义：“逃避”表示躲开，与“在外面等了三个小时”的停留相矛盾。", "享受": "搭配：“享受”多搭配美好的事物，不能与“天气很冷”搭配，句子不通。", "感谢": "搭配：“感谢”的对象一般是人或帮助，不能接“天气很冷”作宾语。"}, "sentence_index": 6, "correct_answer": "不顾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不顾同事的感受，只想把工作快点交给领导。", "explanation": "这是“不顾”的另一个义项“不考虑、不顾及”，表示不理会他人的感受，与“不管有没有危险，还是去做”的意思不同。不需要换词。"}, {"text": "妈妈不顾生病的孩子，去了公司。", "explanation": "这是“不顾”的另一个义项“不考虑、不顾及”，表示不理会生病的孩子，与“不管有没有危险，还是去做”的意思不同。句子本身通顺，只是义项不同。"}, {"text": "他不顾天冷，在家里喝茶看报了一整天。", "explanation": "这里不能用“不顾”。“不顾”后面要接需要克服的困难或不利条件，“天冷”与“在家里喝茶看报”之间没有冲突，应直接说“天冷，他在家里喝茶看报了一整天。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不顾着伤痛，坚持完成了任务。", "corrected_sentence": "他不顾伤痛，坚持完成了任务。", "error_description": "错误：“不顾”后面加了“着”。正确：应说“不顾伤痛”。“不顾”是动词，表示一个动作本身，不能加“着”表示持续状态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位记者不顾的寒冷，在雪地里拍了一整天。", "corrected_sentence": "那位记者不顾寒冷，在雪地里拍了一整天。", "error_description": "错误：“不顾”后面多加了“的”。正确：应说“不顾寒冷”，“不顾”是动词，直接带宾语，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91672, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顾及", "is_correct": true, "explanation": "“顾及”表示考虑到、照顾到，与“不顾”意思相反，是其反义词。"}, {"text": "同意", "is_correct": false, "explanation": "“同意”与“不顾”没有反义关系，它的反义词是“反对”。"}, {"text": "完成", "is_correct": false, "explanation": "“完成”与“不顾”没有反义关系，它的反义词是“未完成”。"}, {"text": "节约", "is_correct": false, "explanation": "“节约”与“不顾”没有反义关系，它的反义词是“浪费”。"}], "correct_answer": "顾及", "explanations": {"顾及": "“顾及”表示考虑到、照顾到，与“不顾”意思相反，是其反义词。", "同意": "“同意”与“不顾”没有反义关系，它的反义词是“反对”。", "完成": "“完成”与“不顾”没有反义关系，它的反义词是“未完成”。", "节约": "“节约”与“不顾”没有反义关系，它的反义词是“浪费”。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91672, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顾及", "is_correct": true, "explanation": "“顾及”表示考虑到、照顾到，与“不顾”意思相反，是其反义词。"}, {"text": "结束", "is_correct": false, "explanation": "“结束”与“不顾”没有反义关系，它的反义词是“开始”。"}, {"text": "批准", "is_correct": false, "explanation": "“批准”与“不顾”没有反义关系，它的反义词是“驳回”。"}, {"text": "确定", "is_correct": false, "explanation": "“确定”与“不顾”没有反义关系，它的反义词是“不确定”。"}], "correct_answer": "顾及", "explanations": {"顾及": "“顾及”表示考虑到、照顾到，与“不顾”意思相反，是其反义词。", "结束": "“结束”与“不顾”没有反义关系，它的反义词是“开始”。", "批准": "“批准”与“不顾”没有反义关系，它的反义词是“驳回”。", "确定": "“确定”与“不顾”没有反义关系，它的反义词是“不确定”。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91672, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不考虑；不顾及。", "primary_collocate": null, "pronunciation": "bù gù", "ipa": "pu˥˩ ku˥˩", "syllable_count": 2, "sentences": [{"text": "他只想赚钱，不顾别人的感受。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能不顾家人，一个人做决定。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人为了方便，不顾环境，乱扔垃圾。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不顾孩子的学习，每天只知道玩。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不顾朋友的劝告，把钱都花光了。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做不顾后果，会出大问题的。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司只想多赚钱，不顾员工的健康。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不顾面子，向邻居道了歉。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不顾大家的意见，决定关门。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别只顾工作，不顾自己的身体。", "target_word": "不顾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "做事时不考虑他人感受、意见、后果等应当顾及的方面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed705e94-968e-41c7-a6e9-f6ef3ffbe67a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91672, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不顾", "is_correct": true, "explanation": "bù gù（第四声），意思是不考虑、不顾及。"}, {"text": "布谷", "is_correct": false, "explanation": "gǔ（第三声）与 gù（第四声）声调不同，意思是布谷鸟。"}, {"text": "不够", "is_correct": false, "explanation": "gòu 与 gù 韵母不同，意思是数量或程度不足。"}, {"text": "不过", "is_correct": false, "explanation": "guò 与 gù 韵母不同，意思是“但是”或“超过”。"}], "explanations": {"不顾": "bù gù（第四声），意思是不考虑、不顾及。", "布谷": "gǔ（第三声）与 gù（第四声）声调不同，意思是布谷鸟。", "不够": "gòu 与 gù 韵母不同，意思是数量或程度不足。", "不过": "guò 与 gù 韵母不同，意思是“但是”或“超过”。"}, "sentence_index": null, "correct_answer": "不顾"}, "level_3": {"options": [{"text": "不顾", "is_correct": true, "explanation": "“不顾”表示不考虑、不顾及，与“只想赚钱”的语境相符。"}, {"text": "尊重", "is_correct": false, "explanation": "语义：“尊重”表示重视，与“只想赚钱”的语境相矛盾。"}, {"text": "珍惜", "is_correct": false, "explanation": "搭配：“珍惜”多搭配时间、机会，与“别人的感受”搭配不自然。"}, {"text": "体会", "is_correct": false, "explanation": "语义：“体会”表示认真感受，与“只想赚钱”的态度相矛盾。"}], "explanations": {"不顾": "“不顾”表示不考虑、不顾及，与“只想赚钱”的语境相符。", "尊重": "语义：“尊重”表示重视，与“只想赚钱”的语境相矛盾。", "珍惜": "搭配：“珍惜”多搭配时间、机会，与“别人的感受”搭配不自然。", "体会": "语义：“体会”表示认真感受，与“只想赚钱”的态度相矛盾。"}, "sentence_index": 0, "correct_answer": "不顾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不顾浓烟，冲进了大火里救人。", "explanation": "这是“不顾”的另一个义项“不管有没有危险，还是去做”，强调面对危险仍坚持，不是“不考虑他人感受”的意思。不需要换词。"}, {"text": "他不顾风大，在海边跑了一个小时。", "explanation": "这是“不顾”的另一个义项“不管有没有危险，还是去做”，强调克服风大等困难，与本义项“不考虑、不顾及”不同。"}, {"text": "他不顾天黑，在家里睡觉。", "explanation": "这里不能用“不顾”。“不顾”后面要接与之相冲突的事情，“天黑”与“在家里睡觉”之间没有冲突，应直接说“天黑了，他在家里睡觉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不顾", "is_correct": true, "explanation": "“不顾”表示不考虑、不顾及，与“只想多赚钱”的语境相符。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”表示爱护，与“只想多赚钱”的语境相矛盾。"}, {"text": "照料", "is_correct": false, "explanation": "搭配：“照料”多指照顾生活起居，与“员工的健康”搭配不自然，且与“只想赚钱”相矛盾。"}, {"text": "重视", "is_correct": false, "explanation": "语义：“重视”表示看重，与“只想多赚钱”的语境相矛盾。"}], "explanations": {"不顾": "“不顾”表示不考虑、不顾及，与“只想多赚钱”的语境相符。", "保护": "语义：“保护”表示爱护，与“只想多赚钱”的语境相矛盾。", "照料": "搭配：“照料”多指照顾生活起居，与“员工的健康”搭配不自然，且与“只想赚钱”相矛盾。", "重视": "语义：“重视”表示看重，与“只想多赚钱”的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "不顾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不顾高烧，还是来上了班。", "explanation": "这是“不顾”的另一个义项“不管有没有危险，还是去做”，强调克服高烧等困难，与本义项“不考虑、不顾及”不同。"}, {"text": "他不顾寒风，在门口站了两个小时。", "explanation": "这是“不顾”的另一个义项“不管有没有危险，还是去做”，强调克服寒风等困难，与本义项“不考虑、不顾及”不同。"}, {"text": "他不顾腿疼，爬完了整座山。", "explanation": "这是“不顾”的另一个义项“不管有没有危险，还是去做”，强调克服腿疼等困难，与本义项“不考虑、不顾及”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把不顾我的反对，一个人去了北京。", "corrected_sentence": "他不顾我的反对，一个人去了北京。", "error_description": "错误：“不顾”前面多加了“把”。正确：应说“他不顾我的反对”，“不顾”前不能直接加“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子不懂事，不顾得父母的劝告，离家出走了。", "corrected_sentence": "孩子不懂事，不顾父母的劝告，离家出走了。", "error_description": "错误：“不顾得”。“不顾”是及物动词，直接带宾语；“得”只出现在“顾得／顾不得”这类可能补语形式中，“不顾”后不能接“得”。正确：应说“不顾父母的劝告”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
