INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91673, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91673, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "重申是把说过的话再讲一遍，让大家记住。", "primary_collocate": null, "pronunciation": "chóng shēn", "ipa": "ʈʂʰʊŋ˧˥ ʂən˥˥", "syllable_count": 2, "sentences": [{"text": "老师重申了考试的时间。", "target_word": "重申", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长在会上重申了学校的规定。", "target_word": "重申", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会前，经理重申了安全要求。", "target_word": "重申", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长重申：晚上十点前必须回宿舍。", "target_word": "重申", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他重申自己没有说过那句话。", "target_word": "重申", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，教练重申了三条规矩。", "target_word": "重申", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板在会上重申，迟到要扣钱。", "target_word": "重申", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想重申一下我们的原则。", "target_word": "重申", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生重申，吃药后不能喝酒。", "target_word": "重申", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司重申了对客人的承诺。", "target_word": "重申", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "重申了", "label": "体标（了）"}, {"form": "重申过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "重申|把说过的要求规定再讲一遍以便记住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eee8ab4b-9732-4bb5-bd7e-a6513a3e7225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91673, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重申", "is_correct": true, "explanation": "正确：“重申”是再讲一遍，与“考试的时间”这种需要告知的内容相合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能与“考试的时间”搭配。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”一般搭配衣物、物品，不能搭配“时间”。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”是用鼻子感知气味，与“考试的时间”的意思不合。"}], "explanations": {"重申": "正确：“重申”是再讲一遍，与“考试的时间”这种需要告知的内容相合。", "唱": "语义：“唱”的对象是歌曲，不能与“考试的时间”搭配。", "洗": "搭配：“洗”一般搭配衣物、物品，不能搭配“时间”。", "闻": "语义：“闻”是用鼻子感知气味，与“考试的时间”的意思不合。"}, "sentence_index": 0, "correct_answer": "重申"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈重申了弟弟的行为。", "explanation": "这里应该用〈批评〉。重申用于郑重再说一遍规定或要求，不用于指责人的行为。"}, {"text": "他重申了大家的帮助。", "explanation": "这里应该用〈感谢〉。重申的内容是规定、要求或立场，不能是帮助这类动作。"}, {"text": "我们重申了教室。", "explanation": "这里应该用〈打扫〉。重申要再讲的是规定或要求，教室这类场所不能被重申。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重申", "is_correct": true, "explanation": "正确：“重申”表示再次说明规定，与“在会上”以及“迟到要扣钱”的规定相合。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：会上不宜吃饭，与“重申规定”的语境不合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与“迟到要扣钱”的规定无关，句意说不通。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：会议室里不能游泳，“游泳”与“在会上”搭配不当。"}], "explanations": {"重申": "正确：“重申”表示再次说明规定，与“在会上”以及“迟到要扣钱”的规定相合。", "吃饭": "语义：会上不宜吃饭，与“重申规定”的语境不合。", "唱": "语义：“唱”与“迟到要扣钱”的规定无关，句意说不通。", "游泳": "搭配：会议室里不能游泳，“游泳”与“在会上”搭配不当。"}, "sentence_index": 6, "correct_answer": "重申"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子重申了上课的时间。", "explanation": "这里应该用〈通知〉。重申需要由人或机构郑重再讲一遍规定，桌子不能作主语；发布上课时间应用“通知”。"}, {"text": "工人重申了楼梯。", "explanation": "这里应该用〈修理〉。重申针对的是要求、规定、立场等内容，不能用于楼梯这类实物。"}, {"text": "他重申了一个苹果。", "explanation": "这里应该用〈吃〉。重申针对的是要再次声明的内容，不能用于苹果这类可以吃的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校方想重申一下一下这条规定。", "corrected_sentence": "校方想重申一下这条规定。", "error_description": "重复：“一下”只能出现一次，“重申一下一下”多写了一个“一下”。应说“重申一下这条规定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理在会上重申了了迟到的处罚规定。", "corrected_sentence": "经理在会上重申了迟到的处罚规定。", "error_description": "体标错误：“重申”后多写了一个“了”，“重申了了”只应用一个“了”。应说“重申了迟到的处罚规定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
