INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91675, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从未是到现在，一次也没有。", "primary_collocate": null, "pronunciation": "cóng wèi", "ipa": "tsʰʊŋ˧˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "我从未去过北京。", "target_word": "从未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从未迟到过。", "target_word": "从未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子从未见过大海。", "target_word": "从未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从未吃过辣的菜。", "target_word": "从未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从未听说过这个人。", "target_word": "从未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷从未坐过飞机。", "target_word": "从未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到现在为止，我从未生过病。", "target_word": "从未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这里住了十年，从未回过家。", "target_word": "从未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师从未对学生发过脾气。", "target_word": "从未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们从未见过面，只在网上聊天。", "target_word": "从未", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "從未", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从未：到现在为止一次也没有，常与“过”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b04d6d01-112c-4ea5-821a-a4681d4a9772') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91675, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中的动作，与表示经历的“去过”矛盾，句子不通。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指即时发生，与“去过北京”这种既往经历相矛盾。"}, {"text": "从未", "is_correct": true, "explanation": "从未表示到现在一次也没有，与“去过”搭配，说明没有去过北京。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”指马上行动，不能用来描述已经发生或未发生的过去经历。"}], "explanations": {"正在": "体貌：“正在”表示进行中的动作，与表示经历的“去过”矛盾，句子不通。", "马上": "语义：“马上”指即时发生，与“去过北京”这种既往经历相矛盾。", "从未": "从未表示到现在一次也没有，与“去过”搭配，说明没有去过北京。", "立刻": "语义：“立刻”指马上行动，不能用来描述已经发生或未发生的过去经历。"}, "sentence_index": 0, "correct_answer": "从未"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明年从未去北京。", "explanation": "这里应该用〈不会〉。从未只指到现在为止一次也没有，不能用于明年这样的将来；说将来不去要用“不会”。"}, {"text": "我每周从未去健身房。", "explanation": "这里应该用〈经常〉。从未表示一次也没有，与“每周”表示反复的意思矛盾。"}, {"text": "他明天从未生病。", "explanation": "这里应该用〈不会〉。从未只指到现在为止一次也没有，不能用于明天这样的将来；说将来不会发生要用“不会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91675, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”指突然发生的一次事件，与“到现在为止”所说的累计经历不符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中的动作，与表示经历的“生过病”矛盾，句子不通。"}, {"text": "总是", "is_correct": false, "explanation": "搭配：“总是”描述习惯性的反复，与表示经历的“生过病”不搭。"}, {"text": "从未", "is_correct": true, "explanation": "从未表示到现在一次也没有，与“到现在为止”和“生过病”的经历意义一致。"}], "explanations": {"忽然": "语义：“忽然”指突然发生的一次事件，与“到现在为止”所说的累计经历不符。", "正在": "体貌：“正在”表示进行中的动作，与表示经历的“生过病”矛盾，句子不通。", "总是": "搭配：“总是”描述习惯性的反复，与表示经历的“生过病”不搭。", "从未": "从未表示到现在一次也没有，与“到现在为止”和“生过病”的经历意义一致。"}, "sentence_index": 6, "correct_answer": "从未"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明年冬天从未下雪。", "explanation": "这里应该用〈不会〉。从未只指到现在为止一次也没有，不能用于明年冬天这样的将来；说将来不会下雪要用“不会”。"}, {"text": "我每天从未运动。", "explanation": "这里应该用〈常常〉。从未表示一次也没有，与“每天”表示反复的意思矛盾。"}, {"text": "他下了课，从未回家。", "explanation": "这里应该用〈然后〉。从未表示一次也没有，不能表示动作的先后顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91675, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从未没去过上海。", "corrected_sentence": "我从未去过上海。", "error_description": "错误：“从未”已表示否定，后面不能再加“没”，造成双重否定。正确说法是“我从未去过上海。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91675, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从未向我借钱过。", "corrected_sentence": "他从未向我借过钱。", "error_description": "错误：“过”是动词的体标记，应紧跟动词，说“借过钱”，不能说“借钱过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
