INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91676, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，从来没有。", "primary_collocate": null, "pronunciation": "cóng wèi", "ipa": "tsʰʊŋ˧˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "他从未放弃自己的梦想。", "target_word": "从未", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里的天气从未这么冷过。", "target_word": "从未", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我从未想到他会来。", "target_word": "从未", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样的事从未发生在我们学校。", "target_word": "从未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年来，她的笑容从未改变。", "target_word": "从未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从未怀疑过他的诚实。", "target_word": "从未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从未对我说过谎。", "target_word": "从未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我从未看完过。", "target_word": "从未", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的店从未关过门。", "target_word": "从未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥从未忘记妈妈的话。", "target_word": "从未", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "從未", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从未：副词，从来没有，后接动词或形容词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b04d6d01-112c-4ea5-821a-a4681d4a9772') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再也", "is_correct": false, "explanation": "搭配：“再也”必须与否定词连用，“再也放弃”不成立。"}, {"text": "很", "is_correct": false, "explanation": "程度副词：“很”不能直接修饰“放弃”这类动作动词，句子不通。"}, {"text": "非常", "is_correct": false, "explanation": "程度副词：“非常”不能直接修饰“放弃”这类动作动词，句子不通。"}, {"text": "从未", "is_correct": true, "explanation": "从未表示从来没有，与“放弃自己的梦想”搭配，说明他一直坚持。"}], "explanations": {"再也": "搭配：“再也”必须与否定词连用，“再也放弃”不成立。", "很": "程度副词：“很”不能直接修饰“放弃”这类动作动词，句子不通。", "非常": "程度副词：“非常”不能直接修饰“放弃”这类动作动词，句子不通。", "从未": "从未表示从来没有，与“放弃自己的梦想”搭配，说明他一直坚持。"}, "sentence_index": 0, "correct_answer": "从未"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下个月从未回国。", "explanation": "这里应该用〈不会〉。从未只表示从来到现在一次也没有，不能用于下个月这样的将来；说将来不做某事要用“不会”。"}, {"text": "她每天从未吃早饭。", "explanation": "这里应该用〈通常〉。从未表示从来没有，与“每天”的常规习惯矛盾。"}, {"text": "这条路明天从未很安静。", "explanation": "这里应该用〈不会〉。从未只表示从来到现在一次也没有，不能用于明天这样的将来；说将来不会怎样要用“不会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中的动作，与表示既往经历的“说过谎”不符。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”指突然发生的一次事件，与“从未”所表达的一贯经历矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”指马上行动，不能用来描述既往经历。"}, {"text": "从未", "is_correct": true, "explanation": "从未表示从来没有，与“说过谎”搭配，说明他从没对我说过谎。"}], "explanations": {"正在": "体貌：“正在”表示进行中的动作，与表示既往经历的“说过谎”不符。", "忽然": "语义：“忽然”指突然发生的一次事件，与“从未”所表达的一贯经历矛盾。", "立刻": "语义：“立刻”指马上行动，不能用来描述既往经历。", "从未": "从未表示从来没有，与“说过谎”搭配，说明他从没对我说过谎。"}, "sentence_index": 6, "correct_answer": "从未"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明年冬天从未下雪。", "explanation": "这里应该用〈不会〉。从未只表示从来到现在一次也没有，不能用于明年冬天这样的将来；说将来不会下雪要用“不会”。"}, {"text": "他每周从未洗车。", "explanation": "这里应该用〈定期〉。从未表示从来没有，与“每周”的规律性安排相矛盾。"}, {"text": "他下了课，从未回家。", "explanation": "这里应该用〈然后〉。从未表示从来没有，不能表示动作的先后顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从未没坐过火车。", "corrected_sentence": "我从未坐过火车。", "error_description": "错误：“从未”已表示否定，后面不能再加“没”，造成双重否定。正确说法是“我从未坐过火车。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从未向别人求助了。", "corrected_sentence": "她从未向别人求助过。", "error_description": "错误：“从未”表示从来没有过的经历，应与“过”搭配。“了”表示完成，与“从未”的经历义矛盾。正确说法是“她从未向别人求助过。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91677, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91677, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91677, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "坐上车、船去别的地方。", "primary_collocate": null, "pronunciation": "chéng", "ipa": "ʈʂʰɤŋ˧˥", "syllable_count": 1, "sentences": [{"text": "我们乘飞机去北京。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他乘船去了那个小岛。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天乘班车上班。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷乘火车回老家。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我想乘地铁去市中心。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们乘出租车去机场。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客乘着小船看风景。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我乘高铁去了上海。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们乘大巴去山里玩。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她乘夜里的火车离开了城市。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "乘了", "label": "体标"}, {"form": "乘过", "label": "体标"}, {"form": "乘着", "label": "体标"}], "register": "通用", "sense_fingerprint": "坐上车、船、飞机等交通工具前往别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed705e94-968e-41c7-a6e9-f6ef3ffbe67a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91677, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "乘", "is_correct": true, "explanation": "正确：乘（chéng）指坐上车、船、飞机等前往别处。"}, {"text": "陈", "is_correct": false, "explanation": "陈（chén）与乘（chéng）韵母不同，en 与 eng 相混，意思是陈旧。"}, {"text": "称", "is_correct": false, "explanation": "称（chēng）与乘（chéng）声调不同，第一声与第二声相混，意思是称呼或称重。"}, {"text": "秤", "is_correct": false, "explanation": "秤（chèng）与乘（chéng）声调不同，第四声与第二声相混，意思是秤。"}, {"text": "撑", "is_correct": false, "explanation": "撑（chēng）与乘（chéng）声调不同，第一声与第二声相混，意思是支撑。"}], "explanations": {"乘": "正确：乘（chéng）指坐上车、船、飞机等前往别处。", "陈": "陈（chén）与乘（chéng）韵母不同，en 与 eng 相混，意思是陈旧。", "称": "称（chēng）与乘（chéng）声调不同，第一声与第二声相混，意思是称呼或称重。", "秤": "秤（chèng）与乘（chéng）声调不同，第四声与第二声相混，意思是秤。", "撑": "撑（chēng）与乘（chéng）声调不同，第一声与第二声相混，意思是支撑。"}, "sentence_index": null, "correct_answer": "乘"}, "level_3": {"options": [{"text": "乘", "is_correct": true, "explanation": "正确：「乘飞机」是搭坐飞机去某地的固定说法，句中只有它能填入空格。"}, {"text": "修", "is_correct": false, "explanation": "语义：「修」指修理，句子会变成修理飞机去北京，与搭坐无关。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：「跑」与「飞机」不构成搭乘义的搭配，「跑飞机」不成立，句子语义不通。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：「踢」是用脚击打，不能与交通工具搭配，「踢飞机」不通。"}], "explanations": {"乘": "正确：「乘飞机」是搭坐飞机去某地的固定说法，句中只有它能填入空格。", "修": "语义：「修」指修理，句子会变成修理飞机去北京，与搭坐无关。", "跑": "搭配：「跑」与「飞机」不构成搭乘义的搭配，「跑飞机」不成立，句子语义不通。", "踢": "搭配：「踢」是用脚击打，不能与交通工具搭配，「踢飞机」不通。"}, "sentence_index": 0, "correct_answer": "乘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天乘自行车去上班。", "explanation": "这里应该用〈骑〉。乘指坐在交通工具里当乘客，骑自行车要用「骑」。"}, {"text": "他乘在靠窗的座位上看书。", "explanation": "这里应该用〈坐〉。乘只用于搭坐交通工具，坐在座位上看书要用「坐」。"}, {"text": "工人们乘了一座小木桥。", "explanation": "这里应该用〈搭〉。搭指搭建、架设；乘只表示搭坐交通工具，不能用来说建造桥梁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91677, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "乘", "is_correct": true, "explanation": "正确：乘（chéng）指坐上车、船、飞机等前往别处。"}, {"text": "层", "is_correct": false, "explanation": "层（céng）与乘（chéng）声母不同，c 与 ch 相混，意思是楼层。"}, {"text": "尘", "is_correct": false, "explanation": "尘（chén）与乘（chéng）韵母不同，en 与 eng 相混，意思是灰尘。"}, {"text": "逞", "is_correct": false, "explanation": "逞（chěng）与乘（chéng）声调不同，第三声与第二声相混，意思是逞强。"}, {"text": "虫", "is_correct": false, "explanation": "虫（chóng）与乘（chéng）韵母不同，ong 与 eng 相混，意思是昆虫。"}], "explanations": {"乘": "正确：乘（chéng）指坐上车、船、飞机等前往别处。", "层": "层（céng）与乘（chéng）声母不同，c 与 ch 相混，意思是楼层。", "尘": "尘（chén）与乘（chéng）韵母不同，en 与 eng 相混，意思是灰尘。", "逞": "逞（chěng）与乘（chéng）声调不同，第三声与第二声相混，意思是逞强。", "虫": "虫（chóng）与乘（chéng）韵母不同，ong 与 eng 相混，意思是昆虫。"}, "sentence_index": null, "correct_answer": "乘"}, "level_3": {"options": [{"text": "乘", "is_correct": true, "explanation": "正确：「乘着小船」表示坐在船上，句中只有它能填入空格。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能与小船搭配，「吃着小船」不通。"}, {"text": "扔", "is_correct": false, "explanation": "语义：「扔」表示丢弃，句子会变成扔掉小船看风景，与乘船无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」表示清洗，「洗着小船」与乘船的意思不符。"}], "explanations": {"乘": "正确：「乘着小船」表示坐在船上，句中只有它能填入空格。", "吃": "搭配：「吃」不能与小船搭配，「吃着小船」不通。", "扔": "语义：「扔」表示丢弃，句子会变成扔掉小船看风景，与乘船无关。", "洗": "搭配：「洗」表示清洗，「洗着小船」与乘船的意思不符。"}, "sentence_index": 6, "correct_answer": "乘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他乘在草地上晒太阳。", "explanation": "这里应该用〈躺〉。乘只表示搭坐交通工具，躺在草地上晒太阳不能用乘。"}, {"text": "他乘在台上发言。", "explanation": "这里应该用〈站〉。乘只表示搭坐交通工具，站在台上发言不能用乘。"}, {"text": "他昨晚乘在沙发上。", "explanation": "这里应该用〈睡〉或〈躺〉。乘只表示搭坐交通工具，睡或躺在沙发上不能用乘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前没乘了地铁。", "corrected_sentence": "我以前没乘过地铁。", "error_description": "错误形式：没乘了；正确形式：没乘过。否定过去的经历要用「没…过」，「没…了」不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91677, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每天乘在公交上班。", "corrected_sentence": "我们每天乘公交上班。", "error_description": "错误形式：乘在公交上班；正确形式：乘公交上班。乘是动词，后面直接接交通工具作宾语，中间不能加「在」，加了「在」语法不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
