INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91678, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "搭坐交通工具。", "primary_collocate": null, "pronunciation": "chéng", "ipa": "ʈʂʰɤŋ˧˥", "syllable_count": 1, "sentences": [{"text": "请乘电梯上三楼。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢乘飞机，总是坐火车。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子第一次乘地铁，很兴奋。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们乘缆车上了山顶。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从机场到酒店，可以乘这路公交车。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘这趟车去那里要两个小时。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以乘三号线，在中山路下车。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没乘过游轮。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他乘快车去上海，不到一小时就到了。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下雨，我乘公共汽车回家。", "target_word": "乘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "乘了", "label": "体标"}, {"form": "乘过", "label": "体标"}, {"form": "乘着", "label": "体标"}], "register": "通用", "sense_fingerprint": "搭坐电梯、公交、缆车等交通工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed705e94-968e-41c7-a6e9-f6ef3ffbe67a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91678, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "乘", "is_correct": true, "explanation": "正确：乘（chéng）指搭坐电梯、公交、缆车等交通工具。"}, {"text": "陈", "is_correct": false, "explanation": "陈（chén）与乘（chéng）韵母不同，en 与 eng 相混，意思是陈旧。"}, {"text": "称", "is_correct": false, "explanation": "称（chēng）与乘（chéng）声调不同，第一声与第二声相混，意思是称呼或称重。"}, {"text": "秤", "is_correct": false, "explanation": "秤（chèng）与乘（chéng）声调不同，第四声与第二声相混，意思是秤。"}, {"text": "层", "is_correct": false, "explanation": "层（céng）与乘（chéng）声母不同，c 与 ch 相混，意思是楼层。"}], "explanations": {"乘": "正确：乘（chéng）指搭坐电梯、公交、缆车等交通工具。", "陈": "陈（chén）与乘（chéng）韵母不同，en 与 eng 相混，意思是陈旧。", "称": "称（chēng）与乘（chéng）声调不同，第一声与第二声相混，意思是称呼或称重。", "秤": "秤（chèng）与乘（chéng）声调不同，第四声与第二声相混，意思是秤。", "层": "层（céng）与乘（chéng）声母不同，c 与 ch 相混，意思是楼层。"}, "sentence_index": null, "correct_answer": "乘"}, "level_3": {"options": [{"text": "乘", "is_correct": true, "explanation": "正确：「乘电梯」是搭坐电梯的固定说法，句中只有它能填入空格。"}, {"text": "买", "is_correct": false, "explanation": "语义：「买」指购买，句子会变成买电梯上三楼，与搭乘无关。"}, {"text": "踢", "is_correct": false, "explanation": "语义：「踢」指用脚击打，句子会变成踢电梯上三楼，与搭坐无关。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：「跑」与「电梯」不搭配，「跑电梯上三楼」不成立，句子语义不通。"}], "explanations": {"乘": "正确：「乘电梯」是搭坐电梯的固定说法，句中只有它能填入空格。", "买": "语义：「买」指购买，句子会变成买电梯上三楼，与搭乘无关。", "踢": "语义：「踢」指用脚击打，句子会变成踢电梯上三楼，与搭坐无关。", "跑": "搭配：「跑」与「电梯」不搭配，「跑电梯上三楼」不成立，句子语义不通。"}, "sentence_index": 0, "correct_answer": "乘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天乘自行车去学校。", "explanation": "这里应该用〈骑〉。乘指坐在交通工具里当乘客，骑自行车要用「骑」。"}, {"text": "他乘在椅子上看电视。", "explanation": "这里应该用〈坐〉。乘只表示搭坐交通工具，坐在椅子上看电视要用「坐」。"}, {"text": "孩子们乘了一座积木城堡。", "explanation": "这里应该用〈搭〉。搭指搭建、堆起；乘只表示搭坐交通工具，不能用来说建造城堡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91678, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "乘", "is_correct": true, "explanation": "正确：乘（chéng）指搭坐电梯、公交、缆车等交通工具。"}, {"text": "尘", "is_correct": false, "explanation": "尘（chén）与乘（chéng）韵母不同，en 与 eng 相混，意思是灰尘。"}, {"text": "虫", "is_correct": false, "explanation": "虫（chóng）与乘（chéng）韵母不同，ong 与 eng 相混，意思是昆虫。"}, {"text": "逞", "is_correct": false, "explanation": "逞（chěng）与乘（chéng）声调不同，第三声与第二声相混，意思是逞强。"}, {"text": "撑", "is_correct": false, "explanation": "撑（chēng）与乘（chéng）声调不同，第一声与第二声相混，意思是支撑。"}], "explanations": {"乘": "正确：乘（chéng）指搭坐电梯、公交、缆车等交通工具。", "尘": "尘（chén）与乘（chéng）韵母不同，en 与 eng 相混，意思是灰尘。", "虫": "虫（chóng）与乘（chéng）韵母不同，ong 与 eng 相混，意思是昆虫。", "逞": "逞（chěng）与乘（chéng）声调不同，第三声与第二声相混，意思是逞强。", "撑": "撑（chēng）与乘（chéng）声调不同，第一声与第二声相混，意思是支撑。"}, "sentence_index": null, "correct_answer": "乘"}, "level_3": {"options": [{"text": "乘", "is_correct": true, "explanation": "正确：「乘三号线」表示搭坐这条地铁线路，句中只有它能填入空格。"}, {"text": "踩", "is_correct": false, "explanation": "搭配：「踩」是用脚践踏，不能与线路搭配，「踩三号线」不通。"}, {"text": "停", "is_correct": false, "explanation": "语义：「停」指使车辆等停下，与搭乘线路的意思不符，「停三号线」不成立。"}, {"text": "扔", "is_correct": false, "explanation": "语义：「扔」表示丢弃，句子会变成扔掉三号线，与搭乘无关。"}], "explanations": {"乘": "正确：「乘三号线」表示搭坐这条地铁线路，句中只有它能填入空格。", "踩": "搭配：「踩」是用脚践踏，不能与线路搭配，「踩三号线」不通。", "停": "语义：「停」指使车辆等停下，与搭乘线路的意思不符，「停三号线」不成立。", "扔": "语义：「扔」表示丢弃，句子会变成扔掉三号线，与搭乘无关。"}, "sentence_index": 6, "correct_answer": "乘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他乘在桌上写作业。", "explanation": "这里应该用〈趴〉。乘只表示搭坐交通工具，趴在桌上写作业不能用乘。"}, {"text": "她乘在墙上休息。", "explanation": "这里应该用〈靠〉。乘只表示搭坐交通工具，靠在墙上休息不能用乘。"}, {"text": "他乘在门口等人。", "explanation": "这里应该用〈站〉、〈坐〉或〈蹲〉。乘只表示搭坐交通工具，在门口等人不能用乘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从来没乘了摆渡船。", "corrected_sentence": "他从来没乘过摆渡船。", "error_description": "错误形式：没乘了；正确形式：没乘过。表示从来没有过的经历要用「没…过」，「没…了」不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈乘在地铁去开会。", "corrected_sentence": "妈妈乘地铁去开会。", "error_description": "错误形式：乘在地铁去开会；正确形式：乘地铁去开会。乘是动词，后面直接接交通工具作宾语，中间不能加「在」，加了「在」语法不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
