INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91679, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "野是在山里、外面自己长大，没人管的。", "primary_collocate": null, "pronunciation": "yě", "ipa": "jɛ˨˩˦", "syllable_count": 1, "sentences": [{"text": "这只猫是野的，不是家里养的。", "target_word": "野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的茶是野的，味道特别好。", "target_word": "野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花是野的，没有人种过。", "target_word": "野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些蘑菇是野的，是在山上找到的。", "target_word": "野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的鸡是养的，山上的鸡是野的。", "target_word": "野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种菜是野的，没人浇水也能长。", "target_word": "野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只兔子是野的，不是买来的。", "target_word": "野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说这条鱼是野的，不是养的。", "target_word": "野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只鸟是野的，不吃家里的米。", "target_word": "野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的树都是野的，没有人种。", "target_word": "野", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "野花", "label": "复合"}, {"form": "野外", "label": "复合"}], "register": "口语", "sense_fingerprint": "形容词“野”：在山里或外面自己长大、没人照管的，与家养、人工种植相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e595aba8-a327-4dfa-933f-cb10e384922d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91679, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "野", "is_correct": true, "explanation": "正确答案。“野”读第三声，意思是在山里或外面自己长大、没人照管的。"}, {"text": "椅", "is_correct": false, "explanation": "韵母不同：“椅”读 yǐ，韵母是 i，与“野”的 e 不同，意思是椅子。"}, {"text": "业", "is_correct": false, "explanation": "声调不同：“业”读第四声，意思是事业或工作，与“野”（第三声）不同。"}, {"text": "页", "is_correct": false, "explanation": "声调不同：“页”读第四声，意思是书页，与“野”（第三声）不同。"}], "explanations": {"野": "正确答案。“野”读第三声，意思是在山里或外面自己长大、没人照管的。", "椅": "韵母不同：“椅”读 yǐ，韵母是 i，与“野”的 e 不同，意思是椅子。", "业": "声调不同：“业”读第四声，意思是事业或工作，与“野”（第三声）不同。", "页": "声调不同：“页”读第四声，意思是书页，与“野”（第三声）不同。"}, "sentence_index": null, "correct_answer": "野"}, "level_3": {"options": [{"text": "野", "is_correct": true, "explanation": "正确答案。“野”指没有人驯养，与“不是家里养的”相符。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”形容物体的厚度，不能用来修饰猫。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”说的是质地，不能修饰猫，与“不是家里养的”也说不通。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”形容高矮，猫的高矮与是否家养无关，说不通。"}], "explanations": {"野": "正确答案。“野”指没有人驯养，与“不是家里养的”相符。", "厚": "搭配：“厚”形容物体的厚度，不能用来修饰猫。", "硬": "搭配：“硬”说的是质地，不能修饰猫，与“不是家里养的”也说不通。", "高": "语义：“高”形容高矮，猫的高矮与是否家养无关，说不通。"}, "sentence_index": 0, "correct_answer": "野"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这头牛是野的，每天被农民牵去耕地。", "explanation": "这里应该用〈家养〉。“野”指未经人驯养，每天被牵去耕地的牛是家养的，不能说是野的。"}, {"text": "这盆花是野的，是妈妈从花店买回来的。", "explanation": "这里应该用〈人工种〉。“野”指自然生长，从花店买回来的花是人工种的，不能说是野的。"}, {"text": "我的宠物狗是野的，每天在家里睡觉。", "explanation": "这里应该用〈家养〉。“野”指没人照管，宠物狗在家里睡觉说明有人照管。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91679, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "野", "is_correct": true, "explanation": "正确答案。“野”读第三声，意思是在山里或外面自己长大、没人照管的。"}, {"text": "夜", "is_correct": false, "explanation": "声调不同：“夜”读第四声，意思是夜晚，与“野”（第三声）不同。"}, {"text": "爷", "is_correct": false, "explanation": "声调不同：“爷”读第二声，意思是爷爷，与“野”（第三声）不同。"}, {"text": "叶", "is_correct": false, "explanation": "声调不同：“叶”读第四声，意思是树叶，与“野”（第三声）不同。"}], "explanations": {"野": "正确答案。“野”读第三声，意思是在山里或外面自己长大、没人照管的。", "夜": "声调不同：“夜”读第四声，意思是夜晚，与“野”（第三声）不同。", "爷": "声调不同：“爷”读第二声，意思是爷爷，与“野”（第三声）不同。", "叶": "声调不同：“叶”读第四声，意思是树叶，与“野”（第三声）不同。"}, "sentence_index": null, "correct_answer": "野"}, "level_3": {"options": [{"text": "野", "is_correct": true, "explanation": "正确答案。“野”指没有人驯养、不是买来的，与“不是买来的”相符。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价钱高，与“不是买来的”的说法矛盾。"}, {"text": "烂", "is_correct": false, "explanation": "搭配：“烂”多用于食物或物品腐坏，不用来修饰兔子。"}, {"text": "脆", "is_correct": false, "explanation": "搭配：“脆”说的是食物的质地，不能修饰兔子。"}], "explanations": {"野": "正确答案。“野”指没有人驯养、不是买来的，与“不是买来的”相符。", "贵": "语义：“贵”说价钱高，与“不是买来的”的说法矛盾。", "烂": "搭配：“烂”多用于食物或物品腐坏，不用来修饰兔子。", "脆": "搭配：“脆”说的是食物的质地，不能修饰兔子。"}, "sentence_index": 6, "correct_answer": "野"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的树都是野的，每年都有园丁修剪。", "explanation": "这里应该用〈人工〉。“野”指没人照管，每年都有园丁修剪的树不能说是野的。"}, {"text": "这里的树都是野的，是从苗圃里运来的。", "explanation": "这里应该用〈移栽〉。“野”指自然生长，从苗圃运来的树是人工培育的。"}, {"text": "这里的树都是野的，每棵树上都挂着名牌。", "explanation": "这里应该用〈有人管理〉。挂着名牌说明有人管理，与“野”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只狗是野，没有主人。", "corrected_sentence": "那只狗是野的，没有主人。", "error_description": "错误形式：“是野”；正确形式：“是野的”。“野”说明事物的性质时用“是……的”结构，不能少“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山上的鸭子都野的，不是养的。", "corrected_sentence": "山上的鸭子都是野的，不是养的。", "error_description": "错误形式：“都野的”；正确形式：“都是野的”。“野的”前面要用“是”，构成“是……的”结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91681, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91681, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91681, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "性格是一个人的脾气，比如爱笑、胆小，或者很勇敢。", "primary_collocate": null, "pronunciation": "xìng gé", "ipa": "ɕiŋ˥˩ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "小李爱笑，性格特别好。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是他的性格，他不是故意的。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟胆子小，性格有点害羞。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的性格很勇敢，什么都不怕。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢性格开朗的朋友。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈性格温和，对谁都很客气。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双胞胎的长相一样，性格却不同。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的性格急，吃饭也很快。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我女儿的性格很活泼。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的性格都有好的一面。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "性格特点", "label": "复合"}, {"form": "性格内向", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "一个人的脾气，如爱笑、胆小、勇敢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33653423-e2ed-4a50-b920-a2c54289c879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91681, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性格", "is_correct": true, "explanation": "正确：性格指人的脾气、性情，“小李爱笑，性格特别好”符合语境。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高是数值，不能用“特别好”来评价。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：年龄不用“特别好”来评价，“爱笑，年龄特别好”搭配不当。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别只有男、女之分，不能用“特别好”来评价，与“爱笑”也无关。"}], "explanations": {"性格": "正确：性格指人的脾气、性情，“小李爱笑，性格特别好”符合语境。", "身高": "搭配：身高是数值，不能用“特别好”来评价。", "年龄": "搭配：年龄不用“特别好”来评价，“爱笑，年龄特别好”搭配不当。", "性别": "语义：性别只有男、女之分，不能用“特别好”来评价，与“爱笑”也无关。"}, "sentence_index": 0, "correct_answer": "性格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的性格是女，今年二十岁。", "explanation": "这里应该用〈性别〉。性格指性情特点，不能说“性格是女”。"}, {"text": "他的性格一米八，很壮实。", "explanation": "这里应该用〈身高〉。性格指性情特点，不能用来说明身体的高矮。"}, {"text": "她的性格五十公斤，很苗条。", "explanation": "这里应该用〈体重〉。性格指性情特点，不能用来说明体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91681, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性格", "is_correct": true, "explanation": "正确：性格指人的脾气、性情，“双胞胎的长相一样，性格却不同”符合语境。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是商品的属性，不能用来说双胞胎之间的差异。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是环境状况，不是人的特点，“长相一样，天气却不同”讲不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是双胞胎身上的特点，“长相一样，桌子却不同”讲不通。"}], "explanations": {"性格": "正确：性格指人的脾气、性情，“双胞胎的长相一样，性格却不同”符合语境。", "价格": "语义：价格是商品的属性，不能用来说双胞胎之间的差异。", "天气": "语义：天气是环境状况，不是人的特点，“长相一样，天气却不同”讲不通。", "桌子": "语义：桌子是家具，不是双胞胎身上的特点，“长相一样，桌子却不同”讲不通。"}, "sentence_index": 6, "correct_answer": "性格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的性格很好，适合出去玩。", "explanation": "这里应该用〈天气〉。性格只用于人的性情，不能用来形容天气。"}, {"text": "这件衣服的性格很好，穿着很舒服。", "explanation": "这里应该用〈质量〉。性格不用于形容衣服，衣服的好坏要用质量。"}, {"text": "这幅画的性格很鲜艳，很漂亮。", "explanation": "这里应该用〈颜色〉。性格不用于形容画的颜色，颜色要用颜色一词来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟的性格已经变很多，现在很少发脾气。", "corrected_sentence": "弟弟的性格已经变了很多，现在很少发脾气。", "error_description": "体标错误：“已经”表示变化已经发生，动词“变”后须用“了”，漏掉“了”，应说“已经变了很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块性格的人很少见，大家都喜欢他。", "corrected_sentence": "这种性格的人很少见，大家都喜欢他。", "error_description": "量词错误：性格是抽象名词，应用「种」；「块」用于片状或块状的东西，不能用于性格。应改为「这种性格」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
