INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91682, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91682, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人对现实的态度和行为方式中比较稳定的特点。", "primary_collocate": null, "pronunciation": "xìng gé", "ipa": "ɕiŋ˥˩ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他的性格很开朗，朋友特别多。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和哥哥的性格完全不一样。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她性格安静，不喜欢参加热闹的聚会。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的性格受家人影响很大。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得自己是什么性格的人？", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作不太适合性格内向的人。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的性格比好的成绩更重要。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐性格很好，从来不生气。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的性格像他父亲，做事很认真。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从小事上可以看出一个人的性格。", "target_word": "性格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "性格特点", "label": "复合"}, {"form": "性格内向", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "人在态度和行为方式上比较稳定的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33653423-e2ed-4a50-b920-a2c54289c879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性格", "is_correct": true, "explanation": "正确：性格指人在态度和行为方式上比较稳定的特点，“开朗”描述的正是性格。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指体形，不能说“很开朗”，开朗描述的是性情。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子没有性情，不能说“很开朗”，与“朋友特别多”也无关。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“开朗”形容性情，不修饰成绩，不说“成绩很开朗”。"}], "explanations": {"性格": "正确：性格指人在态度和行为方式上比较稳定的特点，“开朗”描述的正是性格。", "身材": "体貌：身材指体形，不能说“很开朗”，开朗描述的是性情。", "房子": "语义：房子没有性情，不能说“很开朗”，与“朋友特别多”也无关。", "成绩": "搭配：“开朗”形容性情，不修饰成绩，不说“成绩很开朗”。"}, "sentence_index": 0, "correct_answer": "性格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的性格很好，运行很快。", "explanation": "这里应该用〈性能〉。性格指人的性情特点，不用来形容电脑；电脑的功能表现要用性能。"}, {"text": "他每次考试的性格都是第一。", "explanation": "这里应该用〈成绩〉。性格指性情特点，不能用来说明考试的结果。"}, {"text": "他的性格很英俊，大家都喜欢他。", "explanation": "这里应该用〈外貌〉。性格指性情特点，不能用“英俊”来形容外表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性格", "is_correct": true, "explanation": "正确：性格是人的性情特点，“好的性格比好的成绩更重要”符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能与成绩比较哪个更重要，语义不成立。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是学习用具，不能拿来与成绩比较重要性。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间单位，没有好坏之分，不能与成绩比较哪个更重要。"}], "explanations": {"性格": "正确：性格是人的性情特点，“好的性格比好的成绩更重要”符合语境。", "桌子": "语义：桌子是家具，不能与成绩比较哪个更重要，语义不成立。", "书包": "语义：书包是学习用具，不能拿来与成绩比较重要性。", "星期": "语义：星期是时间单位，没有好坏之分，不能与成绩比较哪个更重要。"}, "sentence_index": 6, "correct_answer": "性格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药的性格很稳定，不容易变质。", "explanation": "这里应该用〈性质〉。性格只用于人的性情特点，药品的属性要用性质。"}, {"text": "他对工作的性格很认真，从不迟到。", "explanation": "这里应该用〈态度〉。性格指性情特点，对工作的看法和做法要用态度。"}, {"text": "这个桌子的性格很特别，很多人来看。", "explanation": "这里应该用〈形状〉。性格不用于形容家具的外形，外形要用形状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的性格已经变很多，大家都觉得很惊讶。", "corrected_sentence": "她的性格已经变了很多，大家都觉得很惊讶。", "error_description": "体标错误：“已经”表示变化已经发生，动词“变”后须用“了”，漏掉“了”，应说“已经变了很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一张很开朗的性格，大家都喜欢他。", "corrected_sentence": "他有一种很开朗的性格，大家都喜欢他。", "error_description": "量词错误：性格是抽象名词，应用「种」；「张」用于纸、桌子等平面的东西，不能用于性格。应改为「一种很开朗的性格」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91683, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91683, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91683, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "意思一样，换一种话再说一遍。", "primary_collocate": null, "pronunciation": "yě jiù shì shuō", "ipa": "jɛ˨˩˦ tɕjoʊ˥˩ ʂɻ̩˥˩ ʂwo˥", "syllable_count": 4, "sentences": [{"text": "他很有钱，也就是说，他很富有。", "target_word": "也就是说", "complexity_tier": "T3", "furigana": "tā hěn yǒu qián, yě jiù shì shuō, tā hěn fù yǒu.", "sentence_source": "generated"}, {"text": "这件事很难，也就是说，不容易做。", "target_word": "也就是说", "complexity_tier": "T3", "furigana": "zhè jiàn shì hěn nán, yě jiù shì shuō, bù róngyì zuò.", "sentence_source": "generated"}, {"text": "他很矮，也就是说，他个子不高。", "target_word": "也就是说", "complexity_tier": "T3", "furigana": "tā hěn ǎi, yě jiù shì shuō, tā gèzi bù gāo.", "sentence_source": "generated"}, {"text": "这个包很贵，也就是说，价格不便宜。", "target_word": "也就是说", "complexity_tier": "T3", "furigana": "zhè ge bāo hěn guì, yě jiù shì shuō, jiàgé bù piányi.", "sentence_source": "generated"}, {"text": "我们很穷，也就是说，我们没有钱。", "target_word": "也就是说", "complexity_tier": "T3", "furigana": "wǒmen hěn qióng, yě jiù shì shuō, wǒmen méiyǒu qián.", "sentence_source": "generated"}, {"text": "这个词很常见，也就是说，大家经常用。", "target_word": "也就是说", "complexity_tier": "T3", "furigana": "zhè ge cí hěn chángjiàn, yě jiù shì shuō, dàjiā jīngcháng yòng.", "sentence_source": "generated"}, {"text": "房间很暗，也就是说，光线不好。", "target_word": "也就是说", "complexity_tier": "T3", "furigana": "fángjiān hěn àn, yě jiù shì shuō, guāngxiàn bù hǎo.", "sentence_source": "generated"}, {"text": "这道题很简单，也就是说，不难。", "target_word": "也就是说", "complexity_tier": "T3", "furigana": "zhè dào tí hěn jiǎndān, yě jiù shì shuō, bù nán.", "sentence_source": "generated"}, {"text": "他说话很慢，也就是说，语速不快。", "target_word": "也就是说", "complexity_tier": "T3", "furigana": "tā shuōhuà hěn màn, yě jiù shì shuō, yǔsù bù kuài.", "sentence_source": "generated"}, {"text": "这个地方很远，也就是说，距离不近。", "target_word": "也就是说", "complexity_tier": "T3", "furigana": "zhè ge dìfang hěn yuǎn, yě jiù shì shuō, jùlí bù jìn.", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "连词；把前面的话换一种说法再说一遍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a326b33e-2943-4e82-b30a-8c790c137e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91683, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "也就是说", "is_correct": true, "explanation": "正确：“也就是说”引出换一种说法的重复，“很有钱”与“很富有”意思相同。"}, {"text": "但是", "is_correct": false, "explanation": "语义：但是表示转折，而“很有钱”与“很富有”意思相同，前后并不对立。"}, {"text": "然而", "is_correct": false, "explanation": "语域：然而是书面转折词，口语句子里不用；且前后同样没有对立关系。"}, {"text": "不过", "is_correct": false, "explanation": "语义：不过表示转折，这里前后是换一种说法，不是对立。"}], "explanations": {"也就是说": "正确：“也就是说”引出换一种说法的重复，“很有钱”与“很富有”意思相同。", "但是": "语义：但是表示转折，而“很有钱”与“很富有”意思相同，前后并不对立。", "然而": "语域：然而是书面转折词，口语句子里不用；且前后同样没有对立关系。", "不过": "语义：不过表示转折，这里前后是换一种说法，不是对立。"}, "sentence_index": 0, "correct_answer": "也就是说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个包很贵，也就是说，我没买。", "explanation": "这里应该用〈所以〉。也就是说只用来把前一句换个说法再讲一遍，不引出行为的结果。"}, {"text": "我很饿，也就是说，我吃了午饭。", "explanation": "这里应该用〈可是〉。也就是说只用于换说法，不表示转折；“很饿”与“吃了午饭”之间是转折关系，要用〈可是〉。"}, {"text": "我先去银行，也就是说，去超市。", "explanation": "这里应该用〈然后〉。也就是说只用于换说法，不表示动作的先后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91683, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "也就是说", "is_correct": true, "explanation": "正确：“也就是说”引出换一种说法，“房间很暗”与“光线不好”意思相同。"}, {"text": "否则", "is_correct": false, "explanation": "语域：否则是书面连词，表示“不然会……”，口语中多说“不然”；且“房间很暗”不是“光线不好”的条件。"}, {"text": "不然", "is_correct": false, "explanation": "语义：不然表示不利的假设后果，“房间很暗”与“光线不好”不构成条件关系。"}, {"text": "可是", "is_correct": false, "explanation": "语义：可是表示转折，而“很暗”与“光线不好”是同一个意思，没有对比。"}], "explanations": {"也就是说": "正确：“也就是说”引出换一种说法，“房间很暗”与“光线不好”意思相同。", "否则": "语域：否则是书面连词，表示“不然会……”，口语中多说“不然”；且“房间很暗”不是“光线不好”的条件。", "不然": "语义：不然表示不利的假设后果，“房间很暗”与“光线不好”不构成条件关系。", "可是": "语义：可是表示转折，而“很暗”与“光线不好”是同一个意思，没有对比。"}, "sentence_index": 6, "correct_answer": "也就是说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店很近，也就是说，东西很便宜。", "explanation": "这里应该用〈而且〉。也就是说用于换说法，不用于补充并列的另一个信息。"}, {"text": "我以为他很忙，也就是说，他很闲。", "explanation": "这里应该用〈其实〉。也就是说只用于换说法，不表示与预想相反的情况。"}, {"text": "他很聪明，也就是说，他很帅。", "explanation": "这里应该用〈另外〉。也就是说只用于换说法，不用于补充另一项并列的特点；“聪明”和“很帅”是两个不同的特点，要用〈另外〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间很小，也就是说着，空间不大。", "corrected_sentence": "这个房间很小，也就是说，空间不大。", "error_description": "错误：“着”不能接在固定连词“也就是说”后面。正确为“这个房间很小，也就是说，空间不大。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路很窄，也就是说了，车不好开。", "corrected_sentence": "这条路很窄，也就是说，车不好开。", "error_description": "错误：“也就是说”是固定的连词，后面不能加“了”。正确为“这条路很窄，也就是说，车不好开。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
