INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91684, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "用来引出对前面内容的解释，或由此推出的结论。", "primary_collocate": null, "pronunciation": "yě jiù shì shuō", "ipa": "jɛ˨˩˦ tɕjoʊ˥˩ ʂɻ̩˥˩ ʂwo˥", "syllable_count": 4, "sentences": [{"text": "这个月没有雨，也就是说，天气一直很干。", "target_word": "也就是说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们只有一小时，也就是说，不能慢慢吃饭。", "target_word": "也就是说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不同意，也就是说，你想换办法。", "target_word": "也就是说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天没有公交车，也就是说，我们只能走路去。", "target_word": "也就是说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行下午五点关门，也就是说，你要早点去。", "target_word": "也就是说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都晚睡，也就是说，早上总是很累。", "target_word": "也就是说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，也就是说，我现在联系不上他。", "target_word": "也就是说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路在修，也就是说，我们要走别的路。", "target_word": "也就是说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说再看看，也就是说，还不能决定。", "target_word": "也就是说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛要两个小时，也就是说，我们六点才能回家。", "target_word": "也就是说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "连词；引出对前文的解释或推论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a326b33e-2943-4e82-b30a-8c790c137e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91684, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "也就是说", "is_correct": true, "explanation": "正确：“也就是说”引出对前句的推论，“没有雨”推出“天气一直很干”。"}, {"text": "否则", "is_correct": false, "explanation": "语域：否则偏书面，口语推论句里不用；且“否则”表示不然会，与此句的推论关系不合。"}, {"text": "不然", "is_correct": false, "explanation": "语义：不然表示假设的不利结果，这里“没有雨”与“天气很干”是推论，不是假设。"}, {"text": "但是", "is_correct": false, "explanation": "语义：但是表示转折，这里“没有雨”与“天气很干”并不对立。"}], "explanations": {"也就是说": "正确：“也就是说”引出对前句的推论，“没有雨”推出“天气一直很干”。", "否则": "语域：否则偏书面，口语推论句里不用；且“否则”表示不然会，与此句的推论关系不合。", "不然": "语义：不然表示假设的不利结果，这里“没有雨”与“天气很干”是推论，不是假设。", "但是": "语义：但是表示转折，这里“没有雨”与“天气很干”并不对立。"}, "sentence_index": 0, "correct_answer": "也就是说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想去，也就是说，没时间。", "explanation": "这里应该用〈但是〉。也就是说用于解释或推论，不表示转折。"}, {"text": "我们去公园，也就是说，我们去超市。", "explanation": "这里应该用〈或者〉。也就是说用于解释或换说法，不用于列出可选的另一个地点；“去公园”与“去超市”是两件事，要用〈或者〉。"}, {"text": "我先吃饭，也就是说，去上班。", "explanation": "这里应该用〈然后〉。也就是说用于解释或推论，不表示动作的先后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "也就是说", "is_correct": true, "explanation": "正确：“也就是说”引出推论，“手机没电了”推出“现在联系不上他”。"}, {"text": "然而", "is_correct": false, "explanation": "语域：然而是书面转折词，口语里不这样用；且“没电”与“联系不上”没有对比关系。"}, {"text": "不过", "is_correct": false, "explanation": "语义：不过表示转折，这里前后不是相反的意思，而是推论。"}, {"text": "可是", "is_correct": false, "explanation": "语义：可是表示转折，这里前句是后句的原因，不构成对比。"}], "explanations": {"也就是说": "正确：“也就是说”引出推论，“手机没电了”推出“现在联系不上他”。", "然而": "语域：然而是书面转折词，口语里不这样用；且“没电”与“联系不上”没有对比关系。", "不过": "语义：不过表示转折，这里前后不是相反的意思，而是推论。", "可是": "语义：可是表示转折，这里前句是后句的原因，不构成对比。"}, "sentence_index": 6, "correct_answer": "也就是说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他会弹钢琴，也就是说，会唱歌。", "explanation": "这里应该用〈而且〉。也就是说用于解释或推论，不用于补充并列的另一项能力。"}, {"text": "我们先吃了午饭，也就是说，去了公园。", "explanation": "这里应该用〈后来〉。也就是说不表示时间先后，只用于解释或推论。"}, {"text": "我去银行，也就是说，买了菜。", "explanation": "这里应该用〈顺便〉。也就是说不表示顺带做另一件事，只用于解释或推论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没接电话，也就是说了，他可能在开会。", "corrected_sentence": "他没接电话，也就是说，他可能在开会。", "error_description": "错误：“也就是说”后面不能加“了”，它是固定的连词。正确为“他没接电话，也就是说，他可能在开会。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨下了一整天，也就是说着，路很滑。", "corrected_sentence": "雨下了一整天，也就是说，路很滑。", "error_description": "错误：“着”表示持续，不能接在固定连词“也就是说”后面。正确为“雨下了一整天，也就是说，路很滑。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
