INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91685, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "录制是把声音或画面存下来。", "primary_collocate": null, "pronunciation": "lù zhì", "ipa": "lu˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他在录音室里录制了一首新歌。", "target_word": "录制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师正在教室里录制明天的网课。", "target_word": "录制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把妈妈唱歌的样子录制下来。", "target_word": "录制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目是上个星期在北京录制的。", "target_word": "录制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们录制过很多有名的广告。", "target_word": "录制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台要录制一场新年晚会。", "target_word": "录制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们站在台上，老师用手机录制他们的表演。", "target_word": "录制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天晚上都录制一段英语朗读。", "target_word": "录制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请安静，我们正在录制节目。", "target_word": "录制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对着话筒录制着自己的声音。", "target_word": "录制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "录制了", "label": "完成体"}, {"form": "录制过", "label": "经历体"}, {"form": "录制着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "把声音或画面存下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85b2443-ac17-43fe-8739-349acbe3fea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91685, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "录制", "is_correct": true, "explanation": "正确。“录制”指把声音存下来，在录音室录一首新歌符合语境。"}, {"text": "录像", "is_correct": false, "explanation": "语义：“录像”录的是影像，与“录音室”和“新歌”的声音语境不符。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“批改”的对象是作业或文章，不能与“一首新歌”搭配。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的对象是文字或图片，不能与“一首新歌”搭配。"}], "explanations": {"录制": "正确。“录制”指把声音存下来，在录音室录一首新歌符合语境。", "录像": "语义：“录像”录的是影像，与“录音室”和“新歌”的声音语境不符。", "批改": "搭配：“批改”的对象是作业或文章，不能与“一首新歌”搭配。", "打印": "搭配：“打印”的对象是文字或图片，不能与“一首新歌”搭配。"}, "sentence_index": 0, "correct_answer": "录制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本词典录制了两万个词。", "explanation": "这里应该用〈收录〉。录制指把声音或画面存下来，词典收入词语要说“收录”。"}, {"text": "摄影师用相机录制了一张照片。", "explanation": "这里应该用〈拍摄〉。录制指存下声音或连续画面，照片要说“拍摄”。"}, {"text": "妈妈在厨房里录制了一碗面条。", "explanation": "这里应该用〈做〉。录制指把声音或画面存下来，面条要说“做”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91685, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "录制", "is_correct": true, "explanation": "正确。“录制”指用手机把声音或画面存下来，与“表演”搭配。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于植物或头发，不能用于表演。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”的对象是物件或身体，不能用于表演。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆开，与“表演”无关，句意不通。"}], "explanations": {"录制": "正确。“录制”指用手机把声音或画面存下来，与“表演”搭配。", "修剪": "搭配：“修剪”用于植物或头发，不能用于表演。", "清洗": "搭配：“清洗”的对象是物件或身体，不能用于表演。", "拆": "语义：“拆”是拆开，与“表演”无关，句意不通。"}, "sentence_index": 6, "correct_answer": "录制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司录制了三名新员工。", "explanation": "这里应该用〈录用〉。录制指把声音或画面存下来，招人要说“录用”。"}, {"text": "工厂每天录制一千个螺丝钉。", "explanation": "这里应该用〈制作〉。录制指存下声音或画面，螺丝钉要说“制作”。"}, {"text": "他录制了一张桌子。", "explanation": "这里应该用〈制作〉。录制的对象是声音或画面，桌子要说“制作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈正在录制了一段儿歌。", "corrected_sentence": "妈妈正在录制一段儿歌。", "error_description": "时体错误：“正在”表示进行，不能与“了”同用，应说“正在录制一段儿歌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把录制好了新歌。", "corrected_sentence": "他录制好了新歌。", "error_description": "“把”字误加：动词“录制”前不应加“把”，应说“他录制好了新歌”，不能说“他把录制好了新歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
