INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91686, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用设备把声音、图像记录下来。", "primary_collocate": null, "pronunciation": "lù zhì", "ipa": "lu˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "警察用摄像机录制了现场的画面。", "target_word": "录制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一台新相机，专门用来录制视频。", "target_word": "录制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器可以同时录制声音和图像。", "target_word": "录制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音乐会的现场是用专业设备录制的。", "target_word": "录制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开手机，开始录制孩子学走路的视频。", "target_word": "录制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把会议的内容录制下来，方便大家回看。", "target_word": "录制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在现场录制着采访的画面。", "target_word": "录制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能录制电脑屏幕上的内容。", "target_word": "录制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们录制过一段给奶奶的生日视频。", "target_word": "录制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员正在调试设备，准备录制。", "target_word": "录制", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "录制了", "label": "完成体"}, {"form": "录制过", "label": "经历体"}, {"form": "录制着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "用设备记录声音和图像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85b2443-ac17-43fe-8739-349acbe3fea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91686, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "录制", "is_correct": true, "explanation": "正确。“录制”指用设备把画面存下来，警察用摄像机录现场画面符合语境。"}, {"text": "录音", "is_correct": false, "explanation": "语义：“录音”只录声音，与“画面”不符。"}, {"text": "烘干", "is_correct": false, "explanation": "搭配：“烘干”的对象是湿的东西，不能用于画面。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”用于纸张文字，摄像机不能打印现场的画面。"}], "explanations": {"录制": "正确。“录制”指用设备把画面存下来，警察用摄像机录现场画面符合语境。", "录音": "语义：“录音”只录声音，与“画面”不符。", "烘干": "搭配：“烘干”的对象是湿的东西，不能用于画面。", "打印": "搭配：“打印”用于纸张文字，摄像机不能打印现场的画面。"}, "sentence_index": 0, "correct_answer": "录制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校今年录制了三十名新生。", "explanation": "这里应该用〈录取〉。录制指把声音或画面存下来，录取指招收入学。"}, {"text": "他用相机录制了一张合照。", "explanation": "这里应该用〈拍摄〉。录制指存下声音或连续画面，照片要说“拍摄”。"}, {"text": "他把数字录制成了文字。", "explanation": "这里应该用〈转换〉。录制指存下声音或画面，数字变成文字要说“转换”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "录制", "is_correct": true, "explanation": "正确。“录制”指用设备存下画面，记者在现场录采访的画面符合语境。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：“装订”用于书页或文件，不能用于“采访的画面”。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：“冷冻”是使东西变冷变硬，与“采访的画面”无关。"}, {"text": "蒸煮", "is_correct": false, "explanation": "搭配：“蒸煮”用于食物，不能用于采访的画面。"}], "explanations": {"录制": "正确。“录制”指用设备存下画面，记者在现场录采访的画面符合语境。", "装订": "搭配：“装订”用于书页或文件，不能用于“采访的画面”。", "冷冻": "语义：“冷冻”是使东西变冷变硬，与“采访的画面”无关。", "蒸煮": "搭配：“蒸煮”用于食物，不能用于采访的画面。"}, "sentence_index": 6, "correct_answer": "录制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套丛书录制了十本小说。", "explanation": "这里应该用〈收录〉。录制指存下声音或画面，丛书收入作品要说“收录”。"}, {"text": "工厂每天录制一千个零件。", "explanation": "这里应该用〈制作〉。录制指存下声音或画面，零件要说“制作”。"}, {"text": "他录制了一把椅子。", "explanation": "这里应该用〈制作〉。录制的对象是声音或画面，椅子要说“制作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在录制了一段朗读。", "corrected_sentence": "我们正在录制一段朗读。", "error_description": "时体错误：“正在”表示进行，不能与“了”同用，应说“正在录制一段朗读”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
