INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91688, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "知道；了解；明白。", "primary_collocate": null, "pronunciation": "dǒng de", "ipa": "tʊŋ˨˩ tə", "syllable_count": 2, "sentences": [{"text": "孩子慢慢懂得了爸爸的辛苦。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很懂得怎样和客人说话。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有懂得感谢，才会有真正的朋友。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不懂得照顾自己，常常生病。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长大以后，我才懂得父母的爱。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他懂得很多做菜的方法。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "懂得尊重别人的人，大家都喜欢。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要懂得，不是每件事都能成功。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王懂得珍惜时间，每天都学习。", "target_word": "懂得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在还不懂得这个道理吗？", "target_word": "懂得", "complexity_tier": "T3", "furigana": "nǐ xiàn zài hái bù dǒng de zhè ge dào lǐ ma", "sentence_source": "generated"}], "morphological_forms": [{"form": "不懂得", "label": "否定"}, {"form": "懂得了", "label": "体标"}], "register": "中性", "sense_fingerprint": "知道、了解并明白某个道理或做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33653423-e2ed-4a50-b920-a2c54289c879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91688, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "懂得", "is_correct": true, "explanation": "“懂得”表示明白、了解道理，与“慢慢……了爸爸的辛苦”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以“爸爸的辛苦”作宾语，“吃辛苦”的意思在这里不成立。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的对象是商品，“爸爸的辛苦”不能买。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造出新事物，爸爸的辛苦是已经存在的事实，不能被发明。"}], "explanations": {"懂得": "“懂得”表示明白、了解道理，与“慢慢……了爸爸的辛苦”相符。", "吃": "搭配：“吃”不能以“爸爸的辛苦”作宾语，“吃辛苦”的意思在这里不成立。", "买": "搭配：“买”的对象是商品，“爸爸的辛苦”不能买。", "发明": "语义：“发明”指创造出新事物，爸爸的辛苦是已经存在的事实，不能被发明。"}, "sentence_index": 0, "correct_answer": "懂得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在火车上懂得了一位老朋友。", "explanation": "这里应该用〈认识〉。“懂得”用于道理、做法等抽象内容，指人要用“认识”。"}, {"text": "我在路上懂得了一只小狗。", "explanation": "这里应该用〈看见〉。“懂得”表示明白道理，不能用于看到具体事物。"}, {"text": "我在屋里懂得了雷声。", "explanation": "这里应该用〈听见〉。“懂得”不能用于感知声音，听到声音要用“听见”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "懂得", "is_correct": true, "explanation": "“懂得”表示知道并明白道理，“懂得尊重别人”语义通顺。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：“嫉妒”是对他人的怨恨心理，与后半句“大家都喜欢”相矛盾。"}, {"text": "瞧不起", "is_correct": false, "explanation": "语义：“瞧不起”带有轻视的态度，与后半句“大家都喜欢”相矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“尊重别人的人”作宾语。"}], "explanations": {"懂得": "“懂得”表示知道并明白道理，“懂得尊重别人”语义通顺。", "嫉妒": "语义：“嫉妒”是对他人的怨恨心理，与后半句“大家都喜欢”相矛盾。", "瞧不起": "语义：“瞧不起”带有轻视的态度，与后半句“大家都喜欢”相矛盾。", "唱": "搭配：“唱”不能带“尊重别人的人”作宾语。"}, "sentence_index": 6, "correct_answer": "懂得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在人群里一眼懂得了妈妈。", "explanation": "这里应该用〈认得〉。“懂得”针对道理，不能用于辨认人，辨认人要用“认得”。"}, {"text": "我一进门就懂得了饭香。", "explanation": "这里应该用〈闻到〉。“懂得”指明白道理，闻气味要用“闻到”。"}, {"text": "我终于懂得了那把钥匙。", "explanation": "这里应该用〈找到〉。“懂得”不能用于具体物品，找到物品要用“找到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我慢慢懂得着生活的意义。", "corrected_sentence": "我慢慢懂得了生活的意义。", "error_description": "体标错误：“懂得”表示已经明白，应用“了”；“着”表示持续状态，“懂得着”不成立。应为“懂得了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们终于懂得得分享的快乐。", "corrected_sentence": "孩子们终于懂得了分享的快乐。", "error_description": "助词错误：“懂得”已含“得”，后面不能再接“得”；表示已经明白要用“了”。应为“懂得了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
