INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91689, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91689, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不一样的，不照平常规矩的那一个。", "primary_collocate": null, "pronunciation": "lì wài", "ipa": "li⁵¹ waɪ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "大家都准时到了，只有他是例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些学生都喜欢运动，小王是个例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别的猫都怕水，这只猫是个例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家人都爱吃辣，只有妈妈是例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店什么都贵，只有面条是例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班同学都有手机，只有小李是例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都住在北京，只有他是个例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的人都很忙，经理是个例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书都很厚，只有这一本是个例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数人都去了，他一个人是例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个例外", "label": "量词"}], "register": "中性", "sense_fingerprint": "例外：和大家不一样的那个人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baee0e88-f68e-4a39-b1f8-d15a57ebea04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91689, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "例外", "is_correct": true, "explanation": "例外：与大家不一样的那一个，“只有他是”指向它。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人，不能与“他”并列作为“只有他是”的对象，句子不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“是”后接的名词要能指人，“作业”不能指人，“只有他是作业”不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是人，与“大家都准时到了”的对比不合，句子不通。"}], "explanations": {"例外": "例外：与大家不一样的那一个，“只有他是”指向它。", "天气": "语义：天气不是人，不能与“他”并列作为“只有他是”的对象，句子不通。", "作业": "搭配：“是”后接的名词要能指人，“作业”不能指人，“只有他是作业”不通。", "河流": "语义：河流不是人，与“大家都准时到了”的对比不合，句子不通。"}, "sentence_index": 0, "correct_answer": "例外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都在例外里看书。", "explanation": "这里应该用〈房间〉。“在……里”要接表示场所的词，例外指与众不同的人或事物，不能作场所。"}, {"text": "这次聚会大家都很开心，他的例外却很糟糕。", "explanation": "这里应该用〈心情〉。“糟糕”形容心情或状况，例外指与众不同的人或事物，不能用来形容。"}, {"text": "他骑车时发生了例外，所幸没有大碍。", "explanation": "这里应该用〈意外〉。“所幸没有大碍”说的是事故，例外指与大家不同的人或事物，不指事故。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91689, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "例外", "is_correct": true, "explanation": "例外：与大家不一样的那一个，“只有他是个”指向它。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市是地方，不是人，“只有他是个城市”不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，不能与“他”并列作为“只有他是个”的对象，句子不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“是个”后接的名词要能指人或类别，“钥匙”不能用来指人。"}], "explanations": {"例外": "例外：与大家不一样的那一个，“只有他是个”指向它。", "城市": "语义：城市是地方，不是人，“只有他是个城市”不通。", "房子": "语义：房子是建筑，不能与“他”并列作为“只有他是个”的对象，句子不通。", "钥匙": "搭配：“是个”后接的名词要能指人或类别，“钥匙”不能用来指人。"}, "sentence_index": 6, "correct_answer": "例外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天例外很好，我们去公园散步。", "explanation": "这里应该用〈天气〉。形容天气要说“天气很好”，例外指与众不同的人或事物，不能形容天气。"}, {"text": "妈妈买了一个例外，大家都很高兴。", "explanation": "这里应该用〈蛋糕〉。买的是食物，例外指与众不同的人或事物，不能用来购买。"}, {"text": "句子末尾要加上一个例外。", "explanation": "这里应该用〈句号〉。句末要加的是句号，例外指与众不同的人或事物，不能加在句子末尾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班上的人都爱踢球，只有他是一只例外。", "corrected_sentence": "班上的人都爱踢球，只有他是一个例外。", "error_description": "量词错误：“例外”指人或事物，应用量词“个”，不能用“只”，应说“是一个例外”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在这群人里，只有他有例外。", "corrected_sentence": "在这群人里，只有他是例外。", "error_description": "动词错误：这里“例外”指和大家不一样的那个人，就是“他”本身。所以要说“他是例外”，不能说“他有例外”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
