INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91690, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91690, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不符合一般规律或规定的情况。", "primary_collocate": null, "pronunciation": "lì wài", "ipa": "li⁵¹ waɪ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "每个规则都会有例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个规定对谁都一样，不能有例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语的语法有很多例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这次是例外，下次不行。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律面前人人平等，没有例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一般不喝咖啡，今天是例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规则太多，例外也不少。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字的写法是一个例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校规定不能迟到，今天有例外。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一般的规律都有例外，我们要记住。", "target_word": "例外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个例外", "label": "量词"}], "register": "中性", "sense_fingerprint": "例外：不符合规律或规定的特殊情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baee0e88-f68e-4a39-b1f8-d15a57ebea04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "例外", "is_correct": true, "explanation": "例外：不符合一般规律或规定的情况，“每个规则都会有”指向它。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是规则的特殊情况，“每个规则都会有天空”不通。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，与规则无关，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“有”后接“颜色”只用于事物的外观，规则没有颜色，不搭配。"}], "explanations": {"例外": "例外：不符合一般规律或规定的情况，“每个规则都会有”指向它。", "天空": "语义：天空不是规则的特殊情况，“每个规则都会有天空”不通。", "饺子": "语义：饺子是食物，与规则无关，句子不通。", "颜色": "搭配：“有”后接“颜色”只用于事物的外观，规则没有颜色，不搭配。"}, "sentence_index": 0, "correct_answer": "例外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一年有十二个月，这是一般的例外。", "explanation": "这里应该用〈规律〉。十二个月是普遍情况，不是不符合规律的例外，应说“这是一般的规律”。"}, {"text": "他骑车时发生了例外，所幸没有大碍。", "explanation": "这里应该用〈意外〉。“所幸没有大碍”说的是事故，例外指不符合一般规律的情况，不指事故。"}, {"text": "他的例外是老师，这一点大家都知道。", "explanation": "这里应该用〈身份〉。“是老师”说的是身份，例外指不符合规律或规定的情况，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "例外", "is_correct": true, "explanation": "例外：不符合规律的情况，“规则太多”后半句指向它。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是食物，与“规则太多”不是同类，句子不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“也不少”要接与“规则”同类的抽象事项，窗户不搭配。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是抽象事项，“河流也不少”与前句不合。"}], "explanations": {"例外": "例外：不符合规律的情况，“规则太多”后半句指向它。", "苹果": "语义：苹果是食物，与“规则太多”不是同类，句子不通。", "窗户": "搭配：“也不少”要接与“规则”同类的抽象事项，窗户不搭配。", "河流": "语义：河流不是抽象事项，“河流也不少”与前句不合。"}, "sentence_index": 6, "correct_answer": "例外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都喝一杯例外。", "explanation": "这里应该用〈牛奶〉。喝的是饮品，例外指不符合规律或规定的情况，不能喝。"}, {"text": "老师唱了一个例外，大家都很开心。", "explanation": "这里应该用〈歌〉。唱的是歌曲，例外指不符合规律或规定的情况，不能唱。"}, {"text": "他每天给例外浇水。", "explanation": "这里应该用〈花〉。浇水的是植物，例外指不符合规律或规定的情况，不能浇水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个规定实行了很久，一直不有例外。", "corrected_sentence": "这个规定实行了很久，一直没有例外。", "error_description": "否定词错误：表示“没有例外”时要用“没有”，不能用“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师说，今天有一只例外。", "corrected_sentence": "老师说，今天有一个例外。", "error_description": "量词错误：“例外”不用“只”来计量，应用“个”，说“有一个例外”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
