INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91691, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "错时是把时间错开，大家不挤在一起。", "primary_collocate": null, "pronunciation": "cuò shí", "ipa": "tsʰwo˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "学校实行错时放学。", "target_word": "错时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司让大家错时上班。", "target_word": "错时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "错时上下班可以少堵车。", "target_word": "错时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了少排队，食堂采用错时吃饭。", "target_word": "错时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们错时去超市，人就少多了。", "target_word": "错时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市里很多公司都错时上班。", "target_word": "错时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "错时出行能让路上更顺畅。", "target_word": "错时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院请病人错时来看病，不用排长队。", "target_word": "错时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们错时下课，楼梯不再拥挤。", "target_word": "错时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师建议同学们错时去操场。", "target_word": "错时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "错时|把上下班上课等时间错开避免拥挤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eee8ab4b-9732-4bb5-bd7e-a6513a3e7225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91691, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "错时", "is_correct": true, "explanation": "正确答案。错时：把时间错开，大家不在同一时间。"}, {"text": "错事", "is_correct": false, "explanation": "cuòshì（第四声）与 cuòshí（第二声）末字声调不同，意思是做错的事。"}, {"text": "措施", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）末字声调不同，意思是办法、举措。"}, {"text": "错失", "is_correct": false, "explanation": "末字 shī（第一声）与 shí（第二声）声调不同，意思是错过、失去。"}], "explanations": {"错时": "正确答案。错时：把时间错开，大家不在同一时间。", "错事": "cuòshì（第四声）与 cuòshí（第二声）末字声调不同，意思是做错的事。", "措施": "shī（第一声）与 shí（第二声）末字声调不同，意思是办法、举措。", "错失": "末字 shī（第一声）与 shí（第二声）声调不同，意思是错过、失去。"}, "sentence_index": null, "correct_answer": "错时"}, "level_3": {"options": [{"text": "错时", "is_correct": true, "explanation": "正确。错时指把放学时间错开，与句子语境相符。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”指没有声音，与放学时学生聚集、热闹的情境相反。"}, {"text": "豪华", "is_correct": false, "explanation": "搭配：“豪华”修饰物品或场所，不能修饰放学这种活动。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的外形，不能用来说明放学的方式。"}], "explanations": {"错时": "正确。错时指把放学时间错开，与句子语境相符。", "寂静": "语义：“寂静”指没有声音，与放学时学生聚集、热闹的情境相反。", "豪华": "搭配：“豪华”修饰物品或场所，不能修饰放学这种活动。", "高大": "体貌：“高大”形容人或物的外形，不能用来说明放学的方式。"}, "sentence_index": 0, "correct_answer": "错时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试时，全年级错时开始，所有人同一时刻动笔。", "explanation": "这里应该用〈统一〉。错时是把时间错开，“所有人同一时刻动笔”是统一时间，与错时矛盾。"}, {"text": "全班同学错时放学，校门口挤得水泄不通。", "explanation": "这里应该用〈集中〉。错时是把时间错开，不让人扎堆；“校门口挤得水泄不通”是大家集中到同一时段的情形，与此矛盾。"}, {"text": "大家错时去食堂，却都在十二点一起排队。", "explanation": "这里应该用〈同时〉。错时是把就餐时间错开，“都在十二点一起排队”是同一时段扎堆的情形，与此矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91691, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "错时", "is_correct": true, "explanation": "正确。错时出行指错开高峰出行，能让路上更顺畅。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：“拥挤”与“路上更顺畅”的意思相反。"}, {"text": "贵重", "is_correct": false, "explanation": "搭配：“贵重”修饰物品，不能修饰“出行”。"}, {"text": "惊险", "is_correct": false, "explanation": "语义：“惊险”形容处境有危险，与让路上顺畅的结果不相符。"}], "explanations": {"错时": "正确。错时出行指错开高峰出行，能让路上更顺畅。", "拥挤": "语义：“拥挤”与“路上更顺畅”的意思相反。", "贵重": "搭配：“贵重”修饰物品，不能修饰“出行”。", "惊险": "语义：“惊险”形容处境有危险，与让路上顺畅的结果不相符。"}, "sentence_index": 6, "correct_answer": "错时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个班错时上课，声音很整齐。", "explanation": "这里应该用〈同步〉。错时是把时间错开，不能用于描述一起发出的声音，与“很整齐”矛盾。"}, {"text": "全体同学在错时到校，早读课很整齐。", "explanation": "这里应该用〈同一时间〉。错时指错开时间，早读课要求大家在同一时间到齐，与此矛盾。"}, {"text": "游客们错时涌入景区，入口处挤得水泄不通。", "explanation": "这里应该用〈扎堆〉。错时是把进场时间错开，不会在入口扎堆；“涌入”后“挤得水泄不通”正是扎堆的情形，与错时矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司下个月开始错时了上班。", "corrected_sentence": "我们公司下个月开始错时上班。", "error_description": "“错时”后面不能加“了”：“错时”是状语，修饰动词“上班”，应说“错时上班”，不能说“错时了上班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每天错时了出门，路上不挤。", "corrected_sentence": "他们每天错时出门，路上不挤。", "error_description": "“错时”后面不能直接加“了”；“错时”是状语，修饰“出门”，应说“每天错时出门”，不能说“错时了出门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
