INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91692, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "错开时间的；不在同一时间的。", "primary_collocate": null, "pronunciation": "cuò shí", "ipa": "tsʰwo˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "错时安排让路上不再拥挤。", "target_word": "错时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个错时方案很好。", "target_word": "错时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司推出了错时制度。", "target_word": "错时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "食堂推出了错时安排，用餐就不那么挤了。", "target_word": "错时", "complexity_tier": "T3", "furigana": "Shítáng tuīchū le cuòshí ānpái, yòngcān jiù bú nàme jǐ le.", "sentence_source": "generated"}, {"text": "我们小区推行错时管理，车就不那么挤了。", "target_word": "错时", "complexity_tier": "T3", "furigana": "Wǒmen xiǎoqū tuīxíng cuòshí guǎnlǐ, chē jiù bú nàme jǐ le.", "sentence_source": "generated"}, {"text": "错时的做法让地铁不太挤。", "target_word": "错时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢错时的工作时间。", "target_word": "错时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "商场的错时服务让顾客不用排队。", "target_word": "错时", "complexity_tier": "T3", "furigana": "Shāngchǎng de cuòshí fúwù ràng gùkè bú yòng páiduì.", "sentence_source": "generated"}, {"text": "医院的错时门诊很方便。", "target_word": "错时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "家长们都支持错时的接送安排。", "target_word": "错时", "complexity_tier": "T3", "furigana": "Jiāzhǎng men dōu zhīchí cuòshí de jiēsòng ānpái.", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "错时|修饰制度办法安排，指时间错开的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eee8ab4b-9732-4bb5-bd7e-a6513a3e7225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91692, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "错时", "is_correct": true, "explanation": "正确答案。错时：错开时间的。"}, {"text": "错事", "is_correct": false, "explanation": "cuòshì（第四声）与 cuòshí（第二声）末字声调不同，意思是做错的事。"}, {"text": "措施", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）末字声调不同，意思是办法、举措。"}, {"text": "错失", "is_correct": false, "explanation": "末字 shī（第一声）与 shí（第二声）声调不同，意思是错过、失去。"}], "explanations": {"错时": "正确答案。错时：错开时间的。", "错事": "cuòshì（第四声）与 cuòshí（第二声）末字声调不同，意思是做错的事。", "措施": "shī（第一声）与 shí（第二声）末字声调不同，意思是办法、举措。", "错失": "末字 shī（第一声）与 shí（第二声）声调不同，意思是错过、失去。"}, "sentence_index": null, "correct_answer": "错时"}, "level_3": {"options": [{"text": "错时", "is_correct": true, "explanation": "正确。错时安排指错开时间的安排，能让路上不再拥挤。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”形容质地不光滑，与安排时间无关。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”形容颜色和外表，不用来形容安排。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指人少、不热闹，与“让路上不再拥挤”的意思矛盾。"}], "explanations": {"错时": "正确。错时安排指错开时间的安排，能让路上不再拥挤。", "粗糙": "语义：“粗糙”形容质地不光滑，与安排时间无关。", "雪白": "体貌：“雪白”形容颜色和外表，不用来形容安排。", "冷清": "语义：“冷清”指人少、不热闹，与“让路上不再拥挤”的意思矛盾。"}, "sentence_index": 0, "correct_answer": "错时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全校同学错时上楼，楼梯上挤得水泄不通。", "explanation": "这里应该用〈同时〉。错时是把时间错开，不让人在同一时段扎堆；“楼梯上挤得水泄不通”是同时拥挤的情形，与此矛盾。"}, {"text": "下课铃一响，全班同学错时冲出教室，门口一下子挤满了人。", "explanation": "这里应该用〈同时〉。错时是把时间错开，不让人扎堆；“门口一下子挤满了人”是大家同时出来的情形，与此矛盾。"}, {"text": "比赛开始时，所有运动员错时起跑。", "explanation": "这里应该用〈同时〉。比赛起跑要求大家在同一时间出发，用“错时”与比赛规则矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "错时", "is_correct": true, "explanation": "正确。错时修饰工作时间，指错开的工作时段。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能修饰工作时间。"}, {"text": "辉煌", "is_correct": false, "explanation": "搭配：“辉煌”多修饰成就、场面，不修饰工作时间。"}, {"text": "凄凉", "is_correct": false, "explanation": "语义：“凄凉”带有悲伤的感情色彩，与“他喜欢”的语境矛盾。"}], "explanations": {"错时": "正确。错时修饰工作时间，指错开的工作时段。", "清脆": "语义：“清脆”形容声音，不能修饰工作时间。", "辉煌": "搭配：“辉煌”多修饰成就、场面，不修饰工作时间。", "凄凉": "语义：“凄凉”带有悲伤的感情色彩，与“他喜欢”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "错时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "放学铃一响，家长们错时涌到校门口，门口一下子挤满了人。", "explanation": "这里应该用〈同时〉。错时是把时间错开，不让人扎堆；“一下子挤满了人”是同时到达的情形，与此矛盾。"}, {"text": "家长们错时到场，把校门口挤得水泄不通。", "explanation": "这里应该用〈齐聚〉。错时是把到场时间错开，不会让家长在校门口齐聚；“挤得水泄不通”是齐聚的情形，与此矛盾。"}, {"text": "学校推出了错时接送，家长们都堵在校门口。", "explanation": "这里应该用〈集中〉。错时是把接送时间错开，不会让家长们集中堵在校门口，与此矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校推出了一套错时了制度，老师们都支持。", "corrected_sentence": "学校推出了一套错时制度，老师们都支持。", "error_description": "“错时”作定语修饰“制度”，后面不能加“了”，应说“错时制度”，不能说“错时了制度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校实行错时了接送，家长们都很满意。", "corrected_sentence": "这所学校实行错时接送，家长们都很满意。", "error_description": "“错时”后面不能直接加“了”；“错时”作定语修饰“接送”，应说“实行错时接送”，不能说“错时了接送”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91693, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
