INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91693, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "接下来是现在这件事以后，要做的下一件事。", "primary_collocate": null, "pronunciation": "jiē xià lái", "ipa": "tɕjɛ˥ ɕjɑ˥˩ laɪ˧˥", "syllable_count": 3, "sentences": [{"text": "接下来是你的节目。", "target_word": "接下来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "接下来我们做什么？", "target_word": "接下来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在先吃饭，接下来去看电影。", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我先看书，接下来写作业。", "target_word": "接下来", "complexity_tier": "T3", "furigana": "wǒ xiān kàn shū, jiē xià lái xiě zuò yè", "sentence_source": "generated"}, {"text": "你知道接下来该怎么办吗？", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业写完了，接下来可以玩了。", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请听好，接下来是最重要的一部分。", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢大家，接下来请王老师讲话。", "target_word": "接下来", "complexity_tier": "T3", "furigana": "xiè xie dà jiā, jiē xià lái qǐng wáng lǎo shī jiǎng huà", "sentence_source": "generated"}, {"text": "会议结束了，接下来大家做什么？", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试结束了，你接下来有什么打算？", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "接下来：指现在这件事之后的下一件事或下一段时间，常用来引出后面的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33653423-e2ed-4a50-b920-a2c54289c879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91693, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接下来", "is_correct": true, "explanation": "“接下来”表示现在这件事之后的下一件事，与“是你的节目”相符。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词，不能直接修饰“是你的节目”这类名词谓语。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示出乎意料，与按顺序安排节目的语境不符。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”修饰形容词，不能接“是你的节目”。"}], "explanations": {"接下来": "“接下来”表示现在这件事之后的下一件事，与“是你的节目”相符。", "很": "搭配：“很”修饰形容词，不能直接修饰“是你的节目”这类名词谓语。", "突然": "语义：“突然”表示出乎意料，与按顺序安排节目的语境不符。", "太": "搭配：“太”修饰形容词，不能接“是你的节目”。"}, "sentence_index": 0, "correct_answer": "接下来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一边做饭，接下来看电视。", "explanation": "这里应该用〈同时〉。“接下来”表示先后相承，不能用于两件同时进行的事。"}, {"text": "我先吃饭，接下来已经吃完了。", "explanation": "这里不能用“接下来”：“接下来”只能引出之后要做的事，不能用于已经完成的动作。"}, {"text": "我接下来很胖。", "explanation": "这里应该用〈过去〉。“接下来”指之后的事，描述过去的状态要用“过去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91693, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接下来", "is_correct": true, "explanation": "“接下来”表示现在这件事之后的下一件事，与“最重要的一部分”的提示相符。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词，不能直接修饰“是最重要的一部分”这类名词性谓语。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“最重要的一部分”的强调相矛盾。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：“幸好”表示庆幸，与“请听好”的提示语境不符。"}], "explanations": {"接下来": "“接下来”表示现在这件事之后的下一件事，与“最重要的一部分”的提示相符。", "非常": "搭配：“非常”修饰形容词，不能直接修饰“是最重要的一部分”这类名词性谓语。", "偶尔": "语义：“偶尔”表示不常发生，与“最重要的一部分”的强调相矛盾。", "幸好": "语义：“幸好”表示庆幸，与“请听好”的提示语境不符。"}, "sentence_index": 6, "correct_answer": "接下来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三年接下来我回国了。", "explanation": "这里应该用〈之后〉。“接下来”不能接在一段时间之后，表示时间段之后要用“之后”。"}, {"text": "他很努力，接下来却考砸了。", "explanation": "这里应该用〈然而〉。“接下来”只表示先后承接，不表示转折。"}, {"text": "那天我先吃饭，接下来昨天睡觉了。", "explanation": "这里不能用“接下来”：“接下来”只能引出之后的事，不能指向“昨天”这样更早的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先喝口水，接下来了我们开始讨论。", "corrected_sentence": "先喝口水，接下来我们开始讨论。", "error_description": "“接下来”是副词，后面不能加“了”，应直接作状语，写作“接下来我们开始讨论”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们先讨论方案，接下来了分工合作。", "corrected_sentence": "我们先讨论方案，接下来分工合作。", "error_description": "“接下来”是副词，后面不能直接加“了”，应写作“接下来分工合作”，“了”应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
