INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91694, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91694, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "紧接着；随后。", "primary_collocate": null, "pronunciation": "jiē xià lái", "ipa": "tɕjɛ˥ ɕjɑ˥˩ laɪ˧˥", "syllable_count": 3, "sentences": [{"text": "他先唱歌，接下来跳舞。", "target_word": "接下来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师讲完，接下来学生开始练习。", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她先洗了手，接下来吃饭。", "target_word": "接下来", "complexity_tier": "T3", "furigana": "tā xiān xǐ le shǒu, jiē xià lái chī fàn", "sentence_source": "generated"}, {"text": "他说完这句话，接下来大家都笑了。", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先打开书，接下来看第五页。", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我先去银行，接下来去超市买菜。", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第一个人走了，接下来轮到我。", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们先吃饭，接下来一起去公园散步。", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理先介绍公司，接下来介绍新产品。", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯突然灭了，接下来什么也看不见。", "target_word": "接下来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "接下来：作副词，表示前一个动作或事情之后紧接着发生另一个动作或事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33653423-e2ed-4a50-b920-a2c54289c879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接下来", "is_correct": true, "explanation": "“接下来”表示紧接着，与前面的“先唱歌”前后相承。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词，不能修饰“跳舞”这类动作。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”修饰形容词，不能与“跳舞”搭配。"}, {"text": "首先", "is_correct": false, "explanation": "语义：“首先”表示开头，与前面的“先”重复，不能接在“先唱歌”之后。"}], "explanations": {"接下来": "“接下来”表示紧接着，与前面的“先唱歌”前后相承。", "很": "搭配：“很”修饰形容词，不能修饰“跳舞”这类动作。", "太": "搭配：“太”修饰形容词，不能与“跳舞”搭配。", "首先": "语义：“首先”表示开头，与前面的“先”重复，不能接在“先唱歌”之后。"}, "sentence_index": 0, "correct_answer": "接下来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一边唱歌，接下来跳舞。", "explanation": "这里应该用〈同时〉。“接下来”表示先后相承，不能用于两件同时进行的事。"}, {"text": "他先唱了歌，过了三年接下来跳舞。", "explanation": "这里应该用〈后来〉。“接下来”强调紧接着发生，中间隔了三年要用“后来”。"}, {"text": "他先唱歌，接下来是昨天的跳舞。", "explanation": "这里不能用“接下来”：“接下来”表示随后发生的事，不能指向“昨天”这样更早的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接下来", "is_correct": true, "explanation": "“接下来”表示紧接着，与“第一个人走了”之后轮到我的先后关系相符。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词，不能直接修饰“轮到我”这类动词性谓语。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续，与“第一个人走了”之后轮到我的先后关系不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与轮流排队的先后关系不符。"}], "explanations": {"接下来": "“接下来”表示紧接着，与“第一个人走了”之后轮到我的先后关系相符。", "非常": "搭配：“非常”修饰形容词，不能直接修饰“轮到我”这类动词性谓语。", "一直": "语义：“一直”表示持续，与“第一个人走了”之后轮到我的先后关系不符。", "偶尔": "语义：“偶尔”表示不常发生，与轮流排队的先后关系不符。"}, "sentence_index": 6, "correct_answer": "接下来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先唱歌，接下来已经跳过舞了。", "explanation": "这里不能用“接下来”：“已经跳过舞了”是更早发生的事，“接下来”只能引出随后的事。"}, {"text": "他很努力，接下来却考砸了。", "explanation": "这里应该用〈然而〉。“接下来”只表示先后承接，不表示转折。"}, {"text": "我们先开会，接下来作业已经交了。", "explanation": "这里不能用“接下来”：“接下来”指随后要做的事，不能引出“作业已经交了”这样已经完成的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她先关灯，接下来的锁门。", "corrected_sentence": "她先关灯，接下来锁门。", "error_description": "“接下来”作副词，后面不能加“的”构成名词短语；去掉“的”，直接作状语，写作“接下来锁门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他先读完报告，接下来了回答问题。", "corrected_sentence": "他先读完报告，接下来回答问题。", "error_description": "“接下来”是副词，后面不能直接加“了”，应写作“接下来回答问题”，“了”应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91697, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91697, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91697, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开线是缝衣服的线断开了。", "primary_collocate": null, "pronunciation": "kāi xiàn", "ipa": "kʰai˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我的裤子开线了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服的袖子开线了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的裙子开线了，要缝一下。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的外套开线了，我帮他缝好。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衬衫的扣子旁边开线了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条裙子才穿两次就开线了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我发现毛衣的袖口开线了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "裤脚开线了，你看见了吗？", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开线的地方，奶奶用针缝好了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的校服在肩膀那里开线了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开线了", "label": "体标"}], "register": "口语", "sense_fingerprint": "衣服的缝线断开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6e59a67-b373-4e65-8aa0-e2aa10bbe482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91697, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开线", "is_correct": true, "explanation": "开线指缝线断开，与“裤子”搭配，符合句意。"}, {"text": "断", "is_correct": false, "explanation": "搭配：“断”多用于线、绳，不说裤子断了。"}, {"text": "哭", "is_correct": false, "explanation": "语义：裤子不会哭，这里说的是缝线脱开。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：衣物不会生病，感冒只用于人。"}], "explanations": {"开线": "开线指缝线断开，与“裤子”搭配，符合句意。", "断": "搭配：“断”多用于线、绳，不说裤子断了。", "哭": "语义：裤子不会哭，这里说的是缝线脱开。", "感冒": "语义：衣物不会生病，感冒只用于人。"}, "sentence_index": 0, "correct_answer": "开线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这面墙的墙皮开线了。", "explanation": "这里应该用〈裂开〉。开线只指衣物缝合处的线脱开，墙皮开裂要说裂开。"}, {"text": "我的手机屏幕开线了。", "explanation": "这里应该用〈碎了〉。开线只指衣物缝线断开，屏幕破碎要说碎了。"}, {"text": "我的孩子开线了。", "explanation": "这里应该用〈生病〉。开线只用于衣物，孩子身体不舒服要说生病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91697, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开线", "is_correct": true, "explanation": "开线指缝线断开，袖口是衣物的部位，符合句意。"}, {"text": "笑", "is_correct": false, "explanation": "语义：袖口不会笑，这里说的是缝线脱开。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：衣物不会发烧，发烧只用于人或动物。"}, {"text": "唱", "is_correct": false, "explanation": "语义：袖口不会唱歌，这里说的是缝线脱开。"}], "explanations": {"开线": "开线指缝线断开，袖口是衣物的部位，符合句意。", "笑": "语义：袖口不会笑，这里说的是缝线脱开。", "发烧": "语义：衣物不会发烧，发烧只用于人或动物。", "唱": "语义：袖口不会唱歌，这里说的是缝线脱开。"}, "sentence_index": 6, "correct_answer": "开线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块玻璃开线了。", "explanation": "这里把开线误用成“破裂、碎开”的意思。开线只指衣物缝合处的线脱开，玻璃破裂不能说开线。"}, {"text": "这张桌子开线了。", "explanation": "这里把开线误用成“散架、松脱”的意思。开线只指衣物缝线脱开，桌子散架不能说开线。"}, {"text": "这扇窗户开线了。", "explanation": "这里把开线误用成“损坏、裂开”的意思。开线只指衣物的缝线，窗户损坏不能说开线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91697, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的牛仔裤很开线了，我得缝一下。", "corrected_sentence": "我的牛仔裤开线了，我得缝一下。", "error_description": "错误：“很”不能修饰动作动词“开线”。“很”一般修饰形容词或状态词；“开线”表示缝线断开这一变化，正确说法是“牛仔裤开线了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91697, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双袜子穿了一个月就被开线了。", "corrected_sentence": "这双袜子穿了一个月就开线了。", "error_description": "错误：多了“被”。开线是非施事的不及物动词，不能用被字句。正确说法是“袜子开线了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
