INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91698, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91698, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "衣物缝合处的线脱开。", "primary_collocate": null, "pronunciation": "kāi xiàn", "ipa": "kʰai˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这件大衣的口袋开线了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明跑得太快，裤子开线了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "袜子开线了，脚趾都露出来了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的衬衫后背开线了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条牛仔裤的膝盖开线了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的帽子开线了，只能再买一顶。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服洗了几次就开线了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服开线时，要马上缝好。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手套的手指那里开线了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的旧毛衣在领口开线了。", "target_word": "开线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开线了", "label": "体标"}], "register": "口语", "sense_fingerprint": "衣物缝合处线脱开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6e59a67-b373-4e65-8aa0-e2aa10bbe482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开线", "is_correct": true, "explanation": "开线指缝线脱开，口袋是衣物的部位，符合句意。"}, {"text": "断", "is_correct": false, "explanation": "搭配：“断”多用于线、绳，不说口袋断了。"}, {"text": "哭", "is_correct": false, "explanation": "语义：口袋不会哭，这里说的是缝线脱开。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：衣物不会生病，感冒只用于人。"}], "explanations": {"开线": "开线指缝线脱开，口袋是衣物的部位，符合句意。", "断": "搭配：“断”多用于线、绳，不说口袋断了。", "哭": "语义：口袋不会哭，这里说的是缝线脱开。", "感冒": "语义：衣物不会生病，感冒只用于人。"}, "sentence_index": 0, "correct_answer": "开线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块玻璃开线了。", "explanation": "这里应该用〈碎了〉。开线只指衣物缝线脱开，玻璃破碎要说碎了。"}, {"text": "这棵树的树皮开线了。", "explanation": "这里应该用〈裂开〉。开线只用于衣物缝线，树皮开裂要说裂开。"}, {"text": "我的爷爷开线了。", "explanation": "这里应该用〈生病〉。开线只用于衣物，人身体不舒服要说生病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开线", "is_correct": true, "explanation": "开线指缝线脱开，衣服洗了几次后缝线脱开，符合句意。"}, {"text": "笑", "is_correct": false, "explanation": "语义：衣服不会笑，这里说的是缝线脱开。"}, {"text": "喊", "is_correct": false, "explanation": "语义：衣服不会喊，这里说的是缝线脱开。"}, {"text": "唱", "is_correct": false, "explanation": "语义：衣服不会唱歌，这里说的是缝线脱开。"}], "explanations": {"开线": "开线指缝线脱开，衣服洗了几次后缝线脱开，符合句意。", "笑": "语义：衣服不会笑，这里说的是缝线脱开。", "喊": "语义：衣服不会喊，这里说的是缝线脱开。", "唱": "语义：衣服不会唱歌，这里说的是缝线脱开。"}, "sentence_index": 6, "correct_answer": "开线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱开线了。", "explanation": "这里把开线误用成“坏掉、故障”的意思。开线只指衣物缝线脱开，冰箱坏了不能说开线。"}, {"text": "这个水杯开线了。", "explanation": "这里把开线误用成“破裂、断开”的意思。开线只指衣物缝线脱开，水杯破裂不能说开线。"}, {"text": "这部手机开线了。", "explanation": "这里把开线误用成“屏幕或机器损坏”的意思。开线只用于衣物缝线，手机损坏不能说开线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件大衣的口袋很开线了，我得缝一下。", "corrected_sentence": "这件大衣的口袋开线了，我得缝一下。", "error_description": "错误：“很”不能修饰动作动词“开线”。正确说法是“口袋开线了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双袜子穿了半年就把开线了。", "corrected_sentence": "这双袜子穿了半年就开线了。", "error_description": "错误：多了“把”。开线是不及物动词，不能放在把字结构里。正确说法是“袜子开线了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
