INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91699, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时长是一件事从开始到结束用了多久。", "primary_collocate": null, "pronunciation": "shí cháng", "ipa": "ʂɨ˧˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这部电影的时长是两个小时。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频的时长只有三分钟。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这节课的时长吗？", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目的时长太长了，我没看完。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把会议的时长告诉大家。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的时长不到四分钟。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看一下比赛的时长。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说考试时长是九十分钟。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影时长太短，我还想再看。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个视频的时长是多少？", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "時長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电影、视频、会议等一件事从开始到结束的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f8102f3-2b9d-4b5e-9770-fb2903a345ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91699, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时长", "is_correct": true, "explanation": "正确答案：指事件从开始到结束所用的时间。"}, {"text": "市场", "is_correct": false, "explanation": "shì chǎng（第四声、第三声）与 shí cháng（第二声、第二声）声调不同，意思是市场。"}, {"text": "失常", "is_correct": false, "explanation": "shī cháng（第一声）与 shí cháng（第二声）第一个音节声调不同，意思是不正常。"}, {"text": "时程", "is_correct": false, "explanation": "shí chéng 与 shí cháng 韵母不同（eng 与 ang），意思是时间的进程安排。"}, {"text": "直肠", "is_correct": false, "explanation": "zhí cháng 与 shí cháng 声母不同（zh 与 sh），意思是消化道末端的肠子。"}], "explanations": {"时长": "正确答案：指事件从开始到结束所用的时间。", "市场": "shì chǎng（第四声、第三声）与 shí cháng（第二声、第二声）声调不同，意思是市场。", "失常": "shī cháng（第一声）与 shí cháng（第二声）第一个音节声调不同，意思是不正常。", "时程": "shí chéng 与 shí cháng 韵母不同（eng 与 ang），意思是时间的进程安排。", "直肠": "zhí cháng 与 shí cháng 声母不同（zh 与 sh），意思是消化道末端的肠子。"}, "sentence_index": null, "correct_answer": "时长"}, "level_3": {"options": [{"text": "时长", "is_correct": true, "explanation": "正确：“时长”指电影从开始到结束的时间，这里说的是两个小时的长度。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指钱数，不能用来说电影的时间长短。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者指创作的人，不能作为电影时间长短的主语。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的身体特征，不能用来描述电影的长短。"}], "explanations": {"时长": "正确：“时长”指电影从开始到结束的时间，这里说的是两个小时的长度。", "价格": "语义：价格指钱数，不能用来说电影的时间长短。", "作者": "语义：作者指创作的人，不能作为电影时间长短的主语。", "身高": "体貌：身高是人的身体特征，不能用来描述电影的长短。"}, "sentence_index": 0, "correct_answer": "时长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根绳子的时长是三米。", "explanation": "这里应该用〈长度〉。时长指时间的长短，绳子的长短要用长度。"}, {"text": "我们约定的时长是下午三点。", "explanation": "这里应该用〈时间〉。时长指持续多久，下午三点是某个时刻，要用时间。"}, {"text": "从学校到车站的时长是两公里。", "explanation": "这里应该用〈距离〉。时长指时间，两公里是空间距离，要用距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91699, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时长", "is_correct": true, "explanation": "正确：“时长”指比赛从开始到结束的时间，句中是要看的比赛时间长短。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人或动物的身体特征，不能用于比赛。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄说人或事物存在了多久，不能用来说比赛的时长。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数指文字的数量，比赛没有字数，不能这样说。"}], "explanations": {"时长": "正确：“时长”指比赛从开始到结束的时间，句中是要看的比赛时间长短。", "体重": "体貌：体重是人或动物的身体特征，不能用于比赛。", "年龄": "语义：年龄说人或事物存在了多久，不能用来说比赛的时长。", "字数": "语义：字数指文字的数量，比赛没有字数，不能这样说。"}, "sentence_index": 6, "correct_answer": "时长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的时长是三千米。", "explanation": "这里应该用〈高度〉。时长指时间，山的海拔高低要用高度。"}, {"text": "他的时长是十八岁。", "explanation": "这里应该用〈年龄〉。时长指持续的时间，人的岁数要用年龄。"}, {"text": "今天的时长是三十度。", "explanation": "这里应该用〈温度〉。时长指时间，三十度是温度，要用温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91699, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场演唱会的时长比预计的大一些。", "corrected_sentence": "这场演唱会的时长比预计的长一些。", "error_description": "“时长”描述时间的多少，形容词应为“长”；说“大”是错的，错在“时长”的谓语部分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91699, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试的时长比上次高半小时。", "corrected_sentence": "这次考试的时长比上次长半小时。", "error_description": "“时长”应与“长”搭配；“高”说的是高低，不能用来形容时间的多少。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
