INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91700, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "持续的时间长度。", "primary_collocate": null, "pronunciation": "shí cháng", "ipa": "ʂɨ˧˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "每次练习的时长不要太长。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天看书的时长大约是一小时。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩手机的时长要控制好。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的时长是一个星期。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡眠时长不够，人会很累。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把每天跑步的时长记在本子上。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的时长是每场九十分钟。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的直播时长是四个小时。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习时长固然有用，但方法更关键。", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你每天锻炼的时长够吗？", "target_word": "时长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "時長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某种活动或状态持续的时间有多长，如睡眠时长、练习时长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f8102f3-2b9d-4b5e-9770-fb2903a345ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91700, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时长", "is_correct": true, "explanation": "正确答案：指某种活动持续的时间有多长。"}, {"text": "市场", "is_correct": false, "explanation": "shì chǎng（第四声、第三声）与 shí cháng（第二声、第二声）声调不同，意思是市场。"}, {"text": "失常", "is_correct": false, "explanation": "shī cháng（第一声）与 shí cháng（第二声）第一个音节声调不同，意思是不正常。"}, {"text": "时程", "is_correct": false, "explanation": "shí chéng 与 shí cháng 韵母不同（eng 与 ang），意思是时间的进程安排。"}, {"text": "直肠", "is_correct": false, "explanation": "zhí cháng 与 shí cháng 声母不同（zh 与 sh），意思是消化道末端的肠子。"}], "explanations": {"时长": "正确答案：指某种活动持续的时间有多长。", "市场": "shì chǎng（第四声、第三声）与 shí cháng（第二声、第二声）声调不同，意思是市场。", "失常": "shī cháng（第一声）与 shí cháng（第二声）第一个音节声调不同，意思是不正常。", "时程": "shí chéng 与 shí cháng 韵母不同（eng 与 ang），意思是时间的进程安排。", "直肠": "zhí cháng 与 shí cháng 声母不同（zh 与 sh），意思是消化道末端的肠子。"}, "sentence_index": null, "correct_answer": "时长"}, "level_3": {"options": [{"text": "时长", "is_correct": true, "explanation": "正确：“时长”指练习持续的时间，句中说的是每次练习花的时间。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指钱数，不能用来说练习花的时间。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄说人的岁数，不能用来说练习的时间。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人的身体特征，不能用来描述练习的时间。"}], "explanations": {"时长": "正确：“时长”指练习持续的时间，句中说的是每次练习花的时间。", "价格": "语义：价格指钱数，不能用来说练习花的时间。", "年龄": "语义：年龄说人的岁数，不能用来说练习的时间。", "体重": "体貌：体重是人的身体特征，不能用来描述练习的时间。"}, "sentence_index": 0, "correct_answer": "时长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议的时长是下午三点。", "explanation": "这里应该用〈时间〉。时长指持续多久，下午三点是某个时刻，要用时间。"}, {"text": "这次旅行的时长是三百公里。", "explanation": "这里应该用〈距离〉。时长指时间，三百公里是路程，要用距离。"}, {"text": "我的时长是六十公斤。", "explanation": "这里应该用〈体重〉。时长指时间的长短，六十公斤是重量，要用体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时长", "is_correct": true, "explanation": "正确：“时长”指比赛从开始到结束的时间，句中说每场的时间。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者指创作的人，比赛没有作者，不能这样说。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的身体特征，不能用来描述比赛的时间。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色指事物的色彩，比赛没有颜色，不能用来说每场的时间。"}], "explanations": {"时长": "正确：“时长”指比赛从开始到结束的时间，句中说每场的时间。", "作者": "语义：作者指创作的人，比赛没有作者，不能这样说。", "身高": "体貌：身高是人的身体特征，不能用来描述比赛的时间。", "颜色": "语义：颜色指事物的色彩，比赛没有颜色，不能用来说每场的时间。"}, "sentence_index": 6, "correct_answer": "时长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的时长是三千米。", "explanation": "这里应该用〈高度〉。时长指时间，山的海拔要用高度。"}, {"text": "他的时长是十八岁。", "explanation": "这里应该用〈年龄〉。时长指持续的时间，人的岁数要用年龄。"}, {"text": "今天的时长是三十度。", "explanation": "这里应该用〈温度〉。时长指时间，三十度是温度，要用温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部剧的时长比原来小了一些。", "corrected_sentence": "这部剧的时长比原来短了一些。", "error_description": "错误：「比原来小了一些」；正确：「比原来短了一些」。「时长」说长短，应用「长 / 短」，不用「小」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首歌的时长比我想的长了多。", "corrected_sentence": "这首歌的时长比我想的长得多。", "error_description": "“长”后面引出程度要用“得”，说“长了多”是错的，错在“时长”的补语部分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91701, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出境", "is_correct": true, "explanation": "与“入境”相反，指离开本国国境，是“入境”的反义词。"}, {"text": "学习", "is_correct": false, "explanation": "与“入境”没有反义关系，学习与进入国境无关。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“入境”没有反义关系，睡觉与国境无关。"}, {"text": "散步", "is_correct": false, "explanation": "与“入境”没有反义关系，散步与国境无关。"}], "correct_answer": "出境", "explanations": {"出境": "与“入境”相反，指离开本国国境，是“入境”的反义词。", "学习": "与“入境”没有反义关系，学习与进入国境无关。", "睡觉": "与“入境”没有反义关系，睡觉与国境无关。", "散步": "与“入境”没有反义关系，散步与国境无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
