INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91701, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从别的国家走进来。", "primary_collocate": null, "pronunciation": "rù jìng", "ipa": "ɻu˥˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我昨天从日本入境了。", "target_word": "入境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐飞机，在上海入境。", "target_word": "入境", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多外国游客从这里入境。", "target_word": "入境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "入境以后，我先去买了手机卡。", "target_word": "入境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她第一次来中国，入境时有点紧张。", "target_word": "入境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你什么时候入境的？", "target_word": "入境", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我朋友上个月入境，现在住在北京。", "target_word": "入境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们坐火车入境，没有坐飞机。", "target_word": "入境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "入境前，我给家人打了电话。", "target_word": "入境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个小时前，他刚从韩国入境。", "target_word": "入境", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "入境了", "label": "完成体"}, {"form": "入境过", "label": "经历体"}, {"form": "入境签证", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人从外国来到本国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa83287-1e2b-4500-b69a-3fd58334cdca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91701, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "入境", "is_correct": true, "explanation": "rù jìng，意思是从外国进入本国国境。"}, {"text": "路径", "is_correct": false, "explanation": "lù（第四声）与 rù 声母不同（l 与 r），意思是道路、路线。"}, {"text": "素净", "is_correct": false, "explanation": "sù（第四声）与 rù 声母不同（s 与 r），意思是朴素干净。"}, {"text": "入京", "is_correct": false, "explanation": "jīng（第一声）与 jìng 声调不同，意思是进入首都。"}], "explanations": {"入境": "rù jìng，意思是从外国进入本国国境。", "路径": "lù（第四声）与 rù 声母不同（l 与 r），意思是道路、路线。", "素净": "sù（第四声）与 rù 声母不同（s 与 r），意思是朴素干净。", "入京": "jīng（第一声）与 jìng 声调不同，意思是进入首都。"}, "sentence_index": null, "correct_answer": "入境"}, "level_3": {"options": [{"text": "入境", "is_correct": true, "explanation": "正确：“入境”指从外国进入本国境内，与“从日本”的语境相符。"}, {"text": "入侵", "is_correct": false, "explanation": "语义：“入侵”指武力侵犯他国，与“从日本”入境的常规行为意思不符。"}, {"text": "入住", "is_correct": false, "explanation": "搭配：“入住”用于酒店、住所，不能与“从日本”搭配表示入境。"}, {"text": "入伍", "is_correct": false, "explanation": "语义：“入伍”指参军，与“从日本”无关，句子意思不通。"}], "explanations": {"入境": "正确：“入境”指从外国进入本国境内，与“从日本”的语境相符。", "入侵": "语义：“入侵”指武力侵犯他国，与“从日本”入境的常规行为意思不符。", "入住": "搭配：“入住”用于酒店、住所，不能与“从日本”搭配表示入境。", "入伍": "语义：“入伍”指参军，与“从日本”无关，句子意思不通。"}, "sentence_index": 0, "correct_answer": "入境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他慢慢入境了房间。", "explanation": "这里应该用〈进入〉。入境只指跨过国境进入一国或一个地区，房间不能作它的宾语。"}, {"text": "他离开中国时要办理入境手续。", "explanation": "这里应该用〈出境〉。入境指进入本国，离开中国要办的是出境手续。"}, {"text": "他在日本入境了三天。", "explanation": "这里应该用〈停留〉。入境是一次性的进入动作，不能表示持续三天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91701, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入境", "is_correct": true, "explanation": "正确：“入境”指进入国境，符合“上个月入境、现在住在北京”的语境。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指书刊印行，须有书刊作宾语或主语，“我朋友上个月出版”不成立，与语境不符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指婴儿来到世上，与成年朋友的情况不符。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：“莅临”是书面敬语，多用于尊贵来宾，不适合形容普通朋友。"}], "explanations": {"入境": "正确：“入境”指进入国境，符合“上个月入境、现在住在北京”的语境。", "出版": "语义：“出版”指书刊印行，须有书刊作宾语或主语，“我朋友上个月出版”不成立，与语境不符。", "出生": "语义：“出生”指婴儿来到世上，与成年朋友的情况不符。", "莅临": "语域：“莅临”是书面敬语，多用于尊贵来宾，不适合形容普通朋友。"}, "sentence_index": 6, "correct_answer": "入境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市一小时前刚入境。", "explanation": "这里应该用〈游客〉作主语。入境的主语通常是人、货物或交通工具，城市不能跨过国境入境。"}, {"text": "他在电影院里入境了。", "explanation": "这里应该用〈进入〉。入境指跨过国境，须经口岸办理，电影院不是口岸，不能在此入境。"}, {"text": "他一小时前刚入境了机场。", "explanation": "这里应该用〈到达〉。入境的宾语应是国家或地区，机场不能作入境的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91701, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他入境了前在国外买了手机卡。", "corrected_sentence": "他入境前在国外买了手机卡。", "error_description": "错误：“了”插在“入境”和“前”之间。表示“……之前”要说“入境前”，“入境”后面不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91701, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上周从泰国入境着。", "corrected_sentence": "他上周从泰国入境了。", "error_description": "错误：“着”用在瞬间动作“入境”后面。“入境”不表示持续状态，应改为“入境了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91702, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出境", "is_correct": true, "explanation": "与“入境”相反，指离开本国国境，是“入境”的反义词。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“入境”没有反义关系，唱歌与国境无关。"}, {"text": "写字", "is_correct": false, "explanation": "与“入境”没有反义关系，写字与国境无关。"}, {"text": "跑步", "is_correct": false, "explanation": "与“入境”没有反义关系，跑步与国境无关。"}], "correct_answer": "出境", "explanations": {"出境": "与“入境”相反，指离开本国国境，是“入境”的反义词。", "唱歌": "与“入境”没有反义关系，唱歌与国境无关。", "写字": "与“入境”没有反义关系，写字与国境无关。", "跑步": "与“入境”没有反义关系，跑步与国境无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
