INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91703, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "防空是防备天上飞来的敌人。", "primary_collocate": null, "pronunciation": "fáng kōng", "ipa": "fɑŋ˧˥ kʰʊŋ˥˥", "syllable_count": 2, "sentences": [{"text": "敌人的飞机来了，部队马上进入阵地防空。", "target_word": "防空", "complexity_tier": "T3", "furigana": "dí rén de fēi jī lái le, bù duì mǎ shàng jìn rù zhèn dì fáng kōng.", "sentence_source": "generated"}, {"text": "战争时期，部队要随时防空。", "target_word": "防空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在村子旁边架起高射炮来防空。", "target_word": "防空", "complexity_tier": "T3", "furigana": "tā men zài cūn zi páng biān jià qǐ gāo shè pào lái fáng kōng.", "sentence_source": "generated"}, {"text": "老人说，那时候天天都要防空。", "target_word": "防空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校在地下修了工事，专门用来防空。", "target_word": "防空", "complexity_tier": "T3", "furigana": "xué xiào zài dì xià xiū le gōng shì, zhuān mén yòng lái fáng kōng.", "sentence_source": "generated"}, {"text": "这个国家的军队正在练习防空。", "target_word": "防空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防空，他们天天看着天上。", "target_word": "防空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到飞机声，村里的人立刻开始防空。", "target_word": "防空", "complexity_tier": "T3", "furigana": "tīng dào fēi jī shēng, cūn lǐ de rén lì kè kāi shǐ fáng kōng.", "sentence_source": "generated"}, {"text": "那里的山很高，部队在山顶上防空。", "target_word": "防空", "complexity_tier": "T3", "furigana": "nà lǐ de shān hěn gāo, bù duì zài shān dǐng shàng fáng kōng.", "sentence_source": "generated"}, {"text": "敌人要来了，我们要马上防空。", "target_word": "防空", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防空洞", "label": "复合"}, {"form": "防空警报", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词“防空”：防备从天上飞来的敌人，如躲避飞机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e595aba8-a327-4dfa-933f-cb10e384922d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91703, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "防空", "is_correct": true, "explanation": "正确答案。“进入阵地防空”指部队进入阵地防备敌机，与“敌人的飞机来了”相合。"}, {"text": "投降", "is_correct": false, "explanation": "语义：“投降”是放弃抵抗，与“进入阵地”的备战行动相反。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”是躲开敌人，与“进入阵地”的行动方向相反。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：“庆祝”要有值得庆祝的事，“敌人的飞机来了”说不通。"}], "explanations": {"防空": "正确答案。“进入阵地防空”指部队进入阵地防备敌机，与“敌人的飞机来了”相合。", "投降": "语义：“投降”是放弃抵抗，与“进入阵地”的备战行动相反。", "逃跑": "语义：“逃跑”是躲开敌人，与“进入阵地”的行动方向相反。", "庆祝": "搭配：“庆祝”要有值得庆祝的事，“敌人的飞机来了”说不通。"}, "sentence_index": 0, "correct_answer": "防空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上很早起床防空，然后去上班。", "explanation": "这里应该用〈锻炼〉。“防空”只指防备空中袭击，不能用来指日常活动。"}, {"text": "我们每周都去超市防空一次。", "explanation": "这里应该用〈购物〉。“防空”只指防备空中袭击，不能用来指购物。"}, {"text": "妈妈下班后在厨房防空，做了很多菜。", "explanation": "这里应该用〈做饭〉。“防空”只指防备空中袭击，不能用来指做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91703, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防空", "is_correct": true, "explanation": "正确答案。“为了防空”指为防备空袭而天天观察天空，目的明确，语境相合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”的目的与“天天看着天上”矛盾，说不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与“天天看着天上”之间没有目的关系，说不通。"}, {"text": "洗碗", "is_correct": false, "explanation": "搭配：“洗碗”与“看着天上”没有关联，作目的说不通。"}], "explanations": {"防空": "正确答案。“为了防空”指为防备空袭而天天观察天空，目的明确，语境相合。", "睡觉": "语义：“睡觉”的目的与“天天看着天上”矛盾，说不通。", "游泳": "语义：“游泳”与“天天看着天上”之间没有目的关系，说不通。", "洗碗": "搭配：“洗碗”与“看着天上”没有关联，作目的说不通。"}, "sentence_index": 6, "correct_answer": "防空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校的运动会，同学们要马上防空。", "explanation": "这里应该用〈比赛〉。“防空”只指防备空中袭击，运动会不能用它。"}, {"text": "医生们正在医院里防空。", "explanation": "这里应该用〈救治〉。“防空”只指防备空中袭击，不能用来指救治病人。"}, {"text": "孩子们在操场上防空，玩得很开心。", "explanation": "这里应该用〈玩耍〉。“防空”只指防备空中袭击，不能用来指玩耍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "敌人来袭时，部队要马上把防空。", "corrected_sentence": "敌人来袭时，部队要马上防空。", "error_description": "错误形式：“把防空”；正确形式：“防空”。“把”字句的动词后要有结果或处置成分，“防空”不能单独放在“把”后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到飞机声，部队马上防空敌人的飞机。", "corrected_sentence": "听到飞机声，部队马上防备敌人的飞机。", "error_description": "错误形式：“防空敌人的飞机”；正确形式：“防备敌人的飞机”。“防空”本身已包含对象“空”，后面不能再带宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
