INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91709, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "阿拉是上海人说的“我们”。", "primary_collocate": null, "pronunciation": "ā lā", "ipa": "a˥ la˥", "syllable_count": 2, "sentences": [{"text": "阿拉是上海人，会说上海话。", "target_word": "阿拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上海爷叔笑着说：“阿拉一起走。”", "target_word": "阿拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阿拉学校就在苏州河边。", "target_word": "阿拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阿拉下班以后去看电影。", "target_word": "阿拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阿拉都喜欢吃上海菜。", "target_word": "阿拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阿拉的小区很安静。", "target_word": "阿拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上海朋友说：“阿拉请你吃饭。”", "target_word": "阿拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阿拉今天坐地铁回家。", "target_word": "阿拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阿拉三个人在外滩拍照。", "target_word": "阿拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阿拉周末去城隍庙玩。", "target_word": "阿拉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "方言", "sense_fingerprint": "代词；上海人说的“我们”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 隍 (Zipf 1.76)']::text[], 'a326b33e-2943-4e82-b30a-8c790c137e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91709, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阿拉", "is_correct": true, "explanation": "正确：“阿拉”是上海人说的“我们”，与“是上海人，会说上海话”的群体身份吻合。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指事物，不能是“上海人”，主语与句意冲突。"}, {"text": "它们", "is_correct": false, "explanation": "语义：“它们”指事物或动物，不能说“是上海人”。"}, {"text": "那里", "is_correct": false, "explanation": "语义：“那里”指地方，不能说“那里是上海人，会说上海话”。"}], "explanations": {"阿拉": "正确：“阿拉”是上海人说的“我们”，与“是上海人，会说上海话”的群体身份吻合。", "它": "语义：“它”指事物，不能是“上海人”，主语与句意冲突。", "它们": "语义：“它们”指事物或动物，不能说“是上海人”。", "那里": "语义：“那里”指地方，不能说“那里是上海人，会说上海话”。"}, "sentence_index": 0, "correct_answer": "阿拉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "阿拉昨天为什么不来接我？", "explanation": "这里是在质问对方，应该用〈你〉。阿拉包括说话人自己，“阿拉不来接我”前后矛盾。"}, {"text": "我不去，阿拉都去了。", "explanation": "这里说话人自己不去，却用〈阿拉〉把自己包括在内，前后矛盾，应该用〈他们〉。"}, {"text": "阿拉都下班了，只剩我一个人在办公室。", "explanation": "这里说话人留在办公室，却用〈阿拉〉把自己算进下班走了的人里，前后矛盾，应该用〈他们〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91709, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阿拉", "is_correct": true, "explanation": "正确：“阿拉”是上海人说的“我们”，与“请你吃饭”的语境相符。"}, {"text": "您", "is_correct": false, "explanation": "语义：“您”指对方，与“请你吃饭”同时出现，主客自相矛盾。"}, {"text": "你", "is_correct": false, "explanation": "语义：“你请你吃饭”的主语和宾语指同一人，句意不通。"}, {"text": "你们", "is_correct": false, "explanation": "语义：“你们”与后面“请你”的“你”指同一批人，“你们请你吃饭”自相矛盾。"}], "explanations": {"阿拉": "正确：“阿拉”是上海人说的“我们”，与“请你吃饭”的语境相符。", "您": "语义：“您”指对方，与“请你吃饭”同时出现，主客自相矛盾。", "你": "语义：“你请你吃饭”的主语和宾语指同一人，句意不通。", "你们": "语义：“你们”与后面“请你”的“你”指同一批人，“你们请你吃饭”自相矛盾。"}, "sentence_index": 6, "correct_answer": "阿拉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一个人在家，阿拉都出去玩了。", "explanation": "这里说话人自己一个人在家，却用〈阿拉〉把自己算进出去玩的人里，前后矛盾，应该用〈他们〉。"}, {"text": "阿拉周末为什么不回我的消息？", "explanation": "这里是在质问对方，应该用〈你〉。阿拉表示说话人一方，不能用来质问对方。"}, {"text": "阿拉都在家，就我一个人去了城隍庙。", "explanation": "这里说话人一个人去了城隍庙，却用〈阿拉〉把自己算进都在家的人里，前后矛盾，应该用〈他们〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91709, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阿拉们下班以后一起去吃饭吧。", "corrected_sentence": "阿拉下班以后一起去吃饭吧。", "error_description": "错误：“阿拉们”；正确：“阿拉”。“阿拉”本身已表示复数“我们”，后面不能再加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91709, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "阿拉的星期天一起去逛街吧。", "corrected_sentence": "阿拉星期天一起去逛街吧。", "error_description": "错误：“阿拉”后多出“的”，句子不通；正确：“阿拉星期天一起去逛街吧。”“阿拉”作主语时后面不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
