INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91711, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "无我是不总想着自己，只想着别人。", "primary_collocate": null, "pronunciation": "wú wǒ", "ipa": "u˧˥ wo˨˩˦", "syllable_count": 2, "sentences": [{"text": "他工作的无我精神让大家很佩服。", "target_word": "无我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们无我地照顾着每一个病人。", "target_word": "无我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲无我地爱着孩子，从不计较得失。", "target_word": "无我", "complexity_tier": "T3", "furigana": "mǔ qīn wú wǒ de ài zhe hái zi, cóng bú jì jiào dé shī.", "sentence_source": "generated"}, {"text": "这位老师处处为学生着想，是个无我的人。", "target_word": "无我", "complexity_tier": "T3", "furigana": "zhè wèi lǎo shī chù chù wèi xué shēng zhuó xiǎng, shì gè wú wǒ de rén.", "sentence_source": "generated"}, {"text": "她为大家忙了一天，却毫无怨言，无我的精神让人敬佩。", "target_word": "无我", "complexity_tier": "T3", "furigana": "tā wèi dà jiā máng le yì tiān, què háo wú yuàn yán, wú wǒ de jīng shén ràng rén jìng pèi.", "sentence_source": "generated"}, {"text": "无我的人遇到事，先想别人。", "target_word": "无我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无我地工作，让同事们都很感动。", "target_word": "无我", "complexity_tier": "T3", "furigana": "tā wú wǒ de gōng zuò, ràng tóng shì men dōu hěn gǎn dòng.", "sentence_source": "generated"}, {"text": "志愿者无我地帮助着山区的孩子。", "target_word": "无我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学习他无我的态度。", "target_word": "无我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡事无我地为别人着想，才会赢得大家的信任。", "target_word": "无我", "complexity_tier": "T3", "furigana": "fán shì wú wǒ de wèi bié rén zhuó xiǎng, cái huì yíng dé dà jiā de xìn rèn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "無我", "label": "繁体"}], "register": "书面", "sense_fingerprint": "无我：不想着自己、只想着别人的忘我精神", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1766c185-9168-436d-834a-7e1714ef858c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91711, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无我", "is_correct": true, "explanation": "正确。“无我精神”指不想着自己、只想着别人的精神，与“佩服”的褒义语境相符。"}, {"text": "私心", "is_correct": false, "explanation": "语义：“私心”指只为自己打算的念头，与“让大家很佩服”的褒义语境冲突。"}, {"text": "功利", "is_correct": false, "explanation": "语义：“功利”强调只看实际好处，与“让大家很佩服”的褒义语境冲突。"}, {"text": "闲情", "is_correct": false, "explanation": "搭配：“闲情”指闲适的心情，不能与“精神”搭配，不说“闲情精神”。"}], "explanations": {"无我": "正确。“无我精神”指不想着自己、只想着别人的精神，与“佩服”的褒义语境相符。", "私心": "语义：“私心”指只为自己打算的念头，与“让大家很佩服”的褒义语境冲突。", "功利": "语义：“功利”强调只看实际好处，与“让大家很佩服”的褒义语境冲突。", "闲情": "搭配：“闲情”指闲适的心情，不能与“精神”搭配，不说“闲情精神”。"}, "sentence_index": 0, "correct_answer": "无我"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的无我精神很自私，凡事只顾自己。", "explanation": "这里把“无我”说成了“自私”，与本词“不想着自己、只想着别人”的意思正好相反，把词义用反了。"}, {"text": "这台电脑很无我，从不计较得失。", "explanation": "这里把指人的品格义“无我”用在了电脑上，“不想着自己”只能用于人，电脑没有这种品格，是对象用错。"}, {"text": "他在比赛中很无我，只想为自己赢得荣誉。", "explanation": "这里把“无我”用成了“自私、只为自己争荣誉”的意思，与本词“不想着自己、只想着别人”的义项正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91711, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无我", "is_correct": true, "explanation": "正确。“无我地工作”指不想着自己、全心为别人工作，与“让同事们都很感动”相符。"}, {"text": "自私", "is_correct": false, "explanation": "语义：“自私”与“让同事们都很感动”的褒义语境冲突。"}, {"text": "敷衍", "is_correct": false, "explanation": "语义：“敷衍”指做事应付，与“让同事们都很感动”的语境冲突。"}, {"text": "强迫", "is_correct": false, "explanation": "语义：“强迫”表示被迫或逼人做事，“强迫地工作”不自然，也不会“让同事们都很感动”。"}], "explanations": {"无我": "正确。“无我地工作”指不想着自己、全心为别人工作，与“让同事们都很感动”相符。", "自私": "语义：“自私”与“让同事们都很感动”的褒义语境冲突。", "敷衍": "语义：“敷衍”指做事应付，与“让同事们都很感动”的语境冲突。", "强迫": "语义：“强迫”表示被迫或逼人做事，“强迫地工作”不自然，也不会“让同事们都很感动”。"}, "sentence_index": 6, "correct_answer": "无我"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个书架很无我，从不计较得失。", "explanation": "这里把指人的品格义“无我”用在了书架上，“不想着自己”只能用于人，书架没有这种品格，是对象用错。"}, {"text": "这只狗很无我，总是把骨头藏起来自己吃。", "explanation": "这里把“无我”用在了自私的行为上，狗只顾自己吃，与本词“不想着自己”的义项正好相反。"}, {"text": "他很无我地吃光了一整盘饺子，一个也不留给别人。", "explanation": "句子写他只顾自己，与“无我”的意思相反，这里把“无我”用在了自私的行为上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她总是无我的帮助身边的朋友。", "corrected_sentence": "她总是无我地帮助身边的朋友。", "error_description": "错误：“无我”修饰动词“帮助”时应用“地”，这里误用“的”。正确：“无我地帮助”。“无我”是状语，要用“地”连接动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他无我工作，常常忘了休息。", "corrected_sentence": "他无我地工作，常常忘了休息。", "error_description": "错误：「无我」作状语修饰动词「工作」时，中间漏掉「地」。正确：「无我地工作」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91712, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91712, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91712, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "佛教用语，指没有自我；也指忘我。", "primary_collocate": null, "pronunciation": "wú wǒ", "ipa": "u˧˥ wo˨˩˦", "syllable_count": 2, "sentences": [{"text": "佛教说人要学会无我。", "target_word": "无我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师父告诉我，无我就是放下自己。", "target_word": "无我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打球时进入了无我的状态。", "target_word": "无我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着音乐，她完全进入无我的世界。", "target_word": "无我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在那里，进入了无我的境界。", "target_word": "无我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画画的时候，他完全沉浸在无我的境界中。", "target_word": "无我", "complexity_tier": "T3", "furigana": "huà huà de shí hòu, tā wán quán chén jìn zài wú wǒ de jìng jiè zhōng.", "sentence_source": "generated"}, {"text": "无我是佛教里很重要的想法。", "target_word": "无我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在山上念经，让他体会到了无我。", "target_word": "无我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌唱得很投入，完全进入了无我的状态。", "target_word": "无我", "complexity_tier": "T3", "furigana": "tā chàng gē chàng de hěn tóu rù, wán quán jìn rù le wú wǒ de zhuàng tài.", "sentence_source": "generated"}, {"text": "书里讲的无我，我还不太懂。", "target_word": "无我", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無我", "label": "繁体"}], "register": "书面", "sense_fingerprint": "无我：佛教说的没有自我，也指忘我的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1766c185-9168-436d-834a-7e1714ef858c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91712, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无我", "is_correct": true, "explanation": "正确。佛教讲“无我”，即没有自我，“学会无我”符合教义。"}, {"text": "自我", "is_correct": false, "explanation": "语义：佛教主张破除自我，“学会自我”与佛教教义相反。"}, {"text": "私欲", "is_correct": false, "explanation": "语义：“私欲”是佛教要舍弃的东西，“学会私欲”与教义冲突。"}, {"text": "财富", "is_correct": false, "explanation": "搭配：“学会”后面不说“财富”，财富不是可以学会的态度或技能。"}], "explanations": {"无我": "正确。佛教讲“无我”，即没有自我，“学会无我”符合教义。", "自我": "语义：佛教主张破除自我，“学会自我”与佛教教义相反。", "私欲": "语义：“私欲”是佛教要舍弃的东西，“学会私欲”与教义冲突。", "财富": "搭配：“学会”后面不说“财富”，财富不是可以学会的态度或技能。"}, "sentence_index": 0, "correct_answer": "无我"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他念经时很无我，一心只想为自己求福。", "explanation": "这里说“很无我”却一心只为自己求福，“无我”指没有自我，与这种行为正好相反，把词义用反了。"}, {"text": "这台电脑进入了无我的状态。", "explanation": "“无我”指人的心境或境界，电脑不能进入这种状态，用于物品是用错了。"}, {"text": "他一边念经，一边很无我地算计着自己的利益。", "explanation": "这里说“很无我地算计自己的利益”，“无我”的“没有自我”与“算计自己”正好相反，把它用成了与本词相反的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无我", "is_correct": true, "explanation": "正确。“无我”是佛教的重要概念，“无我是佛教里很重要的想法”符合事实。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：“比赛”不是佛教的重要观念，说“比赛是佛教里很重要的想法”与事实不符。"}, {"text": "功利", "is_correct": false, "explanation": "语义：“功利”指只看实际好处，与佛教的超脱观念不符。"}, {"text": "面子", "is_correct": false, "explanation": "语义：“面子”指体面、名声，不是佛教里的重要观念，说“面子是佛教里很重要的想法”与事实不符。"}], "explanations": {"无我": "正确。“无我”是佛教的重要概念，“无我是佛教里很重要的想法”符合事实。", "比赛": "语义：“比赛”不是佛教的重要观念，说“比赛是佛教里很重要的想法”与事实不符。", "功利": "语义：“功利”指只看实际好处，与佛教的超脱观念不符。", "面子": "语义：“面子”指体面、名声，不是佛教里的重要观念，说“面子是佛教里很重要的想法”与事实不符。"}, "sentence_index": 6, "correct_answer": "无我"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我饿了，想吃一盘无我。", "explanation": "这里把“无我”当成了可以吃的东西，“无我”指没有自我的境界，不能用来吃，这是把词义理解错了。"}, {"text": "书里讲的无我，是指很多钱。", "explanation": "“无我”指没有自我的境界，不指钱财，这里把它解释成钱，词义用错了。"}, {"text": "他一直很无我，只顾自己，把蛋糕全吃光了，一块也不留。", "explanation": "这里的“无我”被用成了“自私”的意思，与“没有自我”和“忘我”的义项都相反，把词义用反了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在修行中达到了无我地境界。", "corrected_sentence": "他在修行中达到了无我的境界。", "error_description": "错误：“无我”修饰名词“境界”，应用“的”，这里误用“地”。正确：“无我的境界”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在山上修行，慢慢悟到了无我得境界。", "corrected_sentence": "他在山上修行，慢慢悟到了无我的境界。", "error_description": "错误：“无我”修饰名词“境界”，应用结构助词“的”，这里误用“得”（“得”多用于动词、形容词之后作补语）。正确：“无我的境界”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
