INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91714, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "单位或机关所有、供公务使用的车。", "primary_collocate": null, "pronunciation": "gōng chē", "ipa": "kʊŋ˥ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "公车是公家的车，不能用来办私事。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开着公车去接客人。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长坐公车去开会，司机在门口等着。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的公车今天要送客人去机场。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王把公车开回了单位。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能用公车送孩子上学。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校有两辆公车，老师可以用。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用公车办私事，领导批评了他。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导的公车不能随便借给别人。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆公车是单位的，不是他自己的。", "target_word": "公车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "单位、公家所有的车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89422d92-e8b7-408c-a79e-eb0b7d409ade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91714, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公车", "is_correct": true, "explanation": "正确：“公车”指公家的车，与“不能用来办私事”的语境相符。"}, {"text": "私车", "is_correct": false, "explanation": "语义：“私车”指个人的车，与“公家的车”正好相反。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”不是车辆，不能说“食堂是公家的车”。"}, {"text": "出租车", "is_correct": false, "explanation": "搭配：“出租车”属于营运车辆，一般不说“公家的车”，与语境不符。"}], "explanations": {"公车": "正确：“公车”指公家的车，与“不能用来办私事”的语境相符。", "私车": "语义：“私车”指个人的车，与“公家的车”正好相反。", "食堂": "语义：“食堂”不是车辆，不能说“食堂是公家的车”。", "出租车": "搭配：“出租车”属于营运车辆，一般不说“公家的车”，与语境不符。"}, "sentence_index": 0, "correct_answer": "公车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校的公车沿着铁轨开，很快就到了车站。", "explanation": "这里应该用〈火车〉。公车是在道路上行驶的车，不能沿着铁轨开。"}, {"text": "局长有一只公车，专门接送他。", "explanation": "量词用错：“公车”是车辆，应用〈辆〉，不能用“只”。"}, {"text": "他把自己的公车停在门口。", "explanation": "这里应该用〈私家车〉。“公车”是公家的车，不能说成“自己的公车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公车", "is_correct": true, "explanation": "正确：“两辆公车”是公家的车，老师可以用，与语境相符。"}, {"text": "垃圾车", "is_correct": false, "explanation": "语义：“垃圾车”是清运垃圾的车，老师不能随便用。"}, {"text": "出租车", "is_correct": false, "explanation": "语义：“出租车”是营运车辆，不属于学校，“学校有两辆出租车”说不通。"}, {"text": "消防车", "is_correct": false, "explanation": "语义：“消防车”是专门灭火的车辆，学校不会让老师随便用。"}], "explanations": {"公车": "正确：“两辆公车”是公家的车，老师可以用，与语境相符。", "垃圾车": "语义：“垃圾车”是清运垃圾的车，老师不能随便用。", "出租车": "语义：“出租车”是营运车辆，不属于学校，“学校有两辆出租车”说不通。", "消防车": "语义：“消防车”是专门灭火的车辆，学校不会让老师随便用。"}, "sentence_index": 6, "correct_answer": "公车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一辆公车从铁轨上驶过，车上坐满了乘客。", "explanation": "这里应该用〈有轨电车〉。公车是在道路上行驶的车，不在铁轨上运行。"}, {"text": "学校门口停着一条公车，等着接学生。", "explanation": "量词用错：“公车”是车辆，应用〈辆〉，不能用“条”。"}, {"text": "他打了一辆公车去机场。", "explanation": "这里应该用〈出租车〉。“打车”指乘坐出租车，公家的车不能说“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小李把公车去开了机场。", "corrected_sentence": "小李把公车开去了机场。", "error_description": "错误：趋向补语“去”的位置错了。应说“把公车开去了机场”，不能说“去开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公车已经停楼下了。", "corrected_sentence": "公车已经停在楼下了。", "error_description": "错误：介词“在”漏掉了。“停”后要用“在＋地点”表示停放的位置，应说“停在楼下”，不能说“停楼下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
