INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91717, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "杂是东西很多种，乱乱的，不一样。", "primary_collocate": null, "pronunciation": "zá", "ipa": "tsa˧˥", "syllable_count": 1, "sentences": [{"text": "桌子上的东西太杂了。", "target_word": "杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的书很杂，什么都有。", "target_word": "杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店卖的东西很杂。", "target_word": "杂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我包里的东西太杂，找不到钥匙。", "target_word": "杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些资料有点杂，要先整理。", "target_word": "杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看的书很杂，历史、科学都看。", "target_word": "杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的柜子里东西很杂，什么都有。", "target_word": "杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "抽屉里的东西杂得很。", "target_word": "杂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里人多东西杂，请小心。", "target_word": "杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我房间里的东西很杂，书和衣服堆在一起。", "target_word": "杂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "东西种类多而乱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6e59a67-b373-4e65-8aa0-e2aa10bbe482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91717, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杂", "is_correct": true, "explanation": "杂（第二声）指东西种类多而乱，正确答案。"}, {"text": "擦", "is_correct": false, "explanation": "cā 与 zá 声母送气不同、声调不同，意思是擦拭。"}, {"text": "扎", "is_correct": false, "explanation": "zā（第一声）与 zá（第二声）声调不同，意思是捆、束。"}, {"text": "咋", "is_correct": false, "explanation": "zǎ（第三声）与 zá（第二声）声调不同，意思是怎么。"}, {"text": "咱", "is_correct": false, "explanation": "zán 与 zá 韵母不同（多了 n），意思是我们。"}], "explanations": {"杂": "杂（第二声）指东西种类多而乱，正确答案。", "擦": "cā 与 zá 声母送气不同、声调不同，意思是擦拭。", "扎": "zā（第一声）与 zá（第二声）声调不同，意思是捆、束。", "咋": "zǎ（第三声）与 zá（第二声）声调不同，意思是怎么。", "咱": "zán 与 zá 韵母不同（多了 n），意思是我们。"}, "sentence_index": null, "correct_answer": "杂"}, "level_3": {"options": [{"text": "杂", "is_correct": true, "explanation": "杂指东西种类多而乱，“东西太杂了”符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：东西不会聪明，这里说的是东西乱。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描写人的体形，不用来形容东西。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：东西不会害羞，这里说的是东西种类多而乱。"}], "explanations": {"杂": "杂指东西种类多而乱，“东西太杂了”符合句意。", "聪明": "语义：东西不会聪明，这里说的是东西乱。", "胖": "体貌：“胖”描写人的体形，不用来形容东西。", "害羞": "语义：东西不会害羞，这里说的是东西种类多而乱。"}, "sentence_index": 0, "correct_answer": "杂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支笔很杂。", "explanation": "这里应该用〈短〉。杂说东西种类多而乱，一支笔谈不上杂。"}, {"text": "这双手很杂。", "explanation": "这里应该用〈脏〉。杂指种类多、乱，不用来说手不干净。"}, {"text": "我的成绩很杂。", "explanation": "这里应该用〈糟糕〉。杂说种类多、不纯，不用来评价成绩好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杂", "is_correct": true, "explanation": "杂指东西种类多而乱，“厨房的柜子里东西很杂”符合句意。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描写人或动物的体形，不用来形容东西。"}, {"text": "饿", "is_correct": false, "explanation": "语义：东西不会饿，这里说的是东西种类多而乱。"}, {"text": "懒", "is_correct": false, "explanation": "语义：东西不会懒，这里说的是东西种类多而乱。"}], "explanations": {"杂": "杂指东西种类多而乱，“厨房的柜子里东西很杂”符合句意。", "瘦": "体貌：“瘦”描写人或动物的体形，不用来形容东西。", "饿": "语义：东西不会饿，这里说的是东西种类多而乱。", "懒": "语义：东西不会懒，这里说的是东西种类多而乱。"}, "sentence_index": 6, "correct_answer": "杂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果都是红富士，很杂。", "explanation": "这里把杂误用成“质量参差、不一致”的意思。杂指东西种类多而乱，这箱苹果全是红富士一个品种，不能说杂。"}, {"text": "这盒铅笔都是红色的，很杂。", "explanation": "这里把杂误用成“颜色花样多”的意思。杂要求种类多，这盒铅笔全是红色，只有一种，不能说杂。"}, {"text": "这个杯子很杂。", "explanation": "这里把杂误用成“脏乱、不干净”的意思。杂指种类多而乱，一个杯子谈不上种类多，不能说杂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
