INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91718, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "种类多而不纯的；乱的。", "primary_collocate": null, "pronunciation": "zá", "ipa": "tsa˧˥", "syllable_count": 1, "sentences": [{"text": "这条街上的店很杂。", "target_word": "杂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这篇文章写得太杂，没有重点。", "target_word": "杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友很杂，什么人都有。", "target_word": "杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的内容有点杂。", "target_word": "杂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "市场上的人很杂，别带太多钱。", "target_word": "杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个仓库里的货太杂，要先分类。", "target_word": "杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收音机里的声音很杂。", "target_word": "杂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的想法太杂，说不清楚。", "target_word": "杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个班的同学背景很杂，老师要多注意。", "target_word": "杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里的树杂得很，什么树都有。", "target_word": "杂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "种类多而不纯、杂乱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6e59a67-b373-4e65-8aa0-e2aa10bbe482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91718, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杂", "is_correct": true, "explanation": "杂（第二声）指种类多而不纯，正确答案。"}, {"text": "擦", "is_correct": false, "explanation": "cā 与 zá 声母送气不同、声调不同，意思是擦拭。"}, {"text": "扎", "is_correct": false, "explanation": "zā（第一声）与 zá（第二声）声调不同，意思是捆、束。"}, {"text": "咋", "is_correct": false, "explanation": "zǎ（第三声）与 zá（第二声）声调不同，意思是怎么。"}, {"text": "咱", "is_correct": false, "explanation": "zán 与 zá 韵母不同（多了 n），意思是我们。"}], "explanations": {"杂": "杂（第二声）指种类多而不纯，正确答案。", "擦": "cā 与 zá 声母送气不同、声调不同，意思是擦拭。", "扎": "zā（第一声）与 zá（第二声）声调不同，意思是捆、束。", "咋": "zǎ（第三声）与 zá（第二声）声调不同，意思是怎么。", "咱": "zán 与 zá 韵母不同（多了 n），意思是我们。"}, "sentence_index": null, "correct_answer": "杂"}, "level_3": {"options": [{"text": "杂", "is_correct": true, "explanation": "杂指种类多而乱，“这条街上的店很杂”符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：店不会聪明，这里说的是店的种类多。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描写人或动物的体形，不用来形容店。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：店不会勇敢，这里说的是店的种类多。"}], "explanations": {"杂": "杂指种类多而乱，“这条街上的店很杂”符合句意。", "聪明": "语义：店不会聪明，这里说的是店的种类多。", "胖": "体貌：“胖”描写人或动物的体形，不用来形容店。", "勇敢": "语义：店不会勇敢，这里说的是店的种类多。"}, "sentence_index": 0, "correct_answer": "杂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把尺子很杂。", "explanation": "这里应该用〈长〉。杂指种类多而乱，一把尺子不能用杂来形容。"}, {"text": "这只碗很杂。", "explanation": "这里应该用〈脏〉。杂说种类多、不纯，不用来说碗不干净。"}, {"text": "他的身高很杂。", "explanation": "这里应该用〈高〉。杂指种类多而乱，不用来形容身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杂", "is_correct": true, "explanation": "杂指种类多而乱，“收音机里的声音很杂”符合句意。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描写人或动物的体形，不用来形容声音。"}, {"text": "饿", "is_correct": false, "explanation": "语义：声音不会饿，这里说的是声音混杂。"}, {"text": "懒", "is_correct": false, "explanation": "语义：声音不会懒，这里说的是声音混杂。"}], "explanations": {"杂": "杂指种类多而乱，“收音机里的声音很杂”符合句意。", "瘦": "体貌：“瘦”描写人或动物的体形，不用来形容声音。", "饿": "语义：声音不会饿，这里说的是声音混杂。", "懒": "语义：声音不会懒，这里说的是声音混杂。"}, "sentence_index": 6, "correct_answer": "杂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片田里的玉米都是一个品种，很杂。", "explanation": "这里把杂误用成“庄稼长得不整齐”的意思。杂指种类多而不纯，这片玉米只有一个品种，不能说杂。"}, {"text": "这盒巧克力都是牛奶味的，很杂。", "explanation": "这里把杂误用成“口味不均、杂糅”的意思。杂指种类多，这盒巧克力全是牛奶味，只有一种，不能说杂。"}, {"text": "这把椅子很杂。", "explanation": "这里把杂误用成“脏、不干净”的意思。杂指种类多、不纯，不能用来说一把椅子不干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市里的商品杂很，什么都有。", "corrected_sentence": "这家超市里的商品很杂，什么都有。", "error_description": "错误：“杂很”。程度副词“很”要放在“杂”前面，正确说法是“很杂”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这盒零件的种类被杂得很，要分开放。", "corrected_sentence": "这盒零件的种类杂得很，要分开放。", "error_description": "错误：多了“被”。“被”字句表示被动，“杂”是形容词，不能用被字结构。正确说法是“种类杂得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91719, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平庸", "is_correct": true, "explanation": "正确答案。“平庸”指平常、不突出，与“出色”意思相反。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”表示明白，与“出色”没有反义关系。"}, {"text": "潮湿", "is_correct": false, "explanation": "“潮湿”表示含水分多，与“出色”没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "“陡峭”形容地势，与“出色”没有反义关系。"}], "correct_answer": "平庸", "explanations": {"平庸": "正确答案。“平庸”指平常、不突出，与“出色”意思相反。", "清楚": "“清楚”表示明白，与“出色”没有反义关系。", "潮湿": "“潮湿”表示含水分多，与“出色”没有反义关系。", "陡峭": "“陡峭”形容地势，与“出色”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
