INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91720, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "超出一般的，特别好。", "primary_collocate": null, "pronunciation": "chū sè", "ipa": "ʈʂʰu˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这是一部出色的电影。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有出色的音乐才能。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位出色的运动员。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆做的鱼味道出色。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机的照相功能很出色。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写出了一本出色的小说。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个画家有出色的想法。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司需要出色的人才。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位出色的演员得了大奖。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件作品设计得很出色。", "target_word": "出色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "出色：超出一般水平的、特别好的，常作定语修饰人或作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae461367-2454-4efb-ad9b-fb4db9b634ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91720, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出色", "is_correct": true, "explanation": "正确答案。“出色的电影”指超出一般水平、特别好的电影。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”描述含水状态，不能用来形容电影的水平。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”描述地势，不能用来形容电影。"}, {"text": "寒冷", "is_correct": false, "explanation": "搭配：“寒冷”形容气温，不修饰电影。"}], "explanations": {"出色": "正确答案。“出色的电影”指超出一般水平、特别好的电影。", "潮湿": "语义：“潮湿”描述含水状态，不能用来形容电影的水平。", "陡峭": "语义：“陡峭”描述地势，不能用来形容电影。", "寒冷": "搭配：“寒冷”形容气温，不修饰电影。"}, "sentence_index": 0, "correct_answer": "出色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子的重量很出色。", "explanation": "重量应说“重”或“轻”，“出色”用于人或作品超出一般的水平，不用来描写重量。"}, {"text": "这座城市的空气很出色。", "explanation": "空气应说“清新”，“出色”不用于描写自然环境。"}, {"text": "这个房间的温度很出色。", "explanation": "温度应说“适宜”或“舒适”，“出色”不用于描写温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出色", "is_correct": true, "explanation": "正确答案。“出色的想法”指超出一般水平、特别好的想法。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”形容环境安静，不能用来修饰想法。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”一般不用来修饰“想法”，搭配不当。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，不能用来修饰想法。"}], "explanations": {"出色": "正确答案。“出色的想法”指超出一般水平、特别好的想法。", "寂静": "语义：“寂静”形容环境安静，不能用来修饰想法。", "柔软": "搭配：“柔软”一般不用来修饰“想法”，搭配不当。", "寒冷": "语义：“寒冷”形容温度，不能用来修饰想法。"}, "sentence_index": 6, "correct_answer": "出色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次事故造成的损失很出色。", "explanation": "“出色”是褒义词，表示超出一般的好，不能用来形容损失；损失大应说“严重”或“很大”。"}, {"text": "这段路的距离很出色。", "explanation": "距离是长度，应说“远”或“近”，“出色”不用于评价距离。"}, {"text": "他的年龄很出色。", "explanation": "年龄是人的岁数，应说“大”或“小”，“出色”不用于描写年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
