INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91722, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "参加球类比赛的运动员。", "primary_collocate": null, "pronunciation": "qiú yuán", "ipa": "tɕʰjoʊ̯˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "比赛开始前，球员走进了球场。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队有十一名球员。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位球员代表国家参加比赛。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练让球员们休息一会儿。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中，两名球员被罚下场。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一名职业球员。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷们给球员加油。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛，球员们都踢得很好。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的球员很受欢迎。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位球员拿到了冠军奖杯。", "target_word": "球员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "球員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "参加球类比赛的运动员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05e66eed-24af-4555-9219-89fc197dcac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "球员", "is_correct": true, "explanation": "正确。“比赛开始前，球员走进了球场”中，球员是能走进球场的人。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能走进球场，句子意思不通。"}, {"text": "云", "is_correct": false, "explanation": "配价：“走进”的主语须是能自主移动的人或动物，不说“云走进了球场”。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：身体部位不能独立“走进球场”，不说“眼睛走进了球场”。"}], "explanations": {"球员": "正确。“比赛开始前，球员走进了球场”中，球员是能走进球场的人。", "窗户": "语义：窗户不能走进球场，句子意思不通。", "云": "配价：“走进”的主语须是能自主移动的人或动物，不说“云走进了球场”。", "眼睛": "搭配：身体部位不能独立“走进球场”，不说“眼睛走进了球场”。"}, "sentence_index": 0, "correct_answer": "球员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名长跑球员。", "explanation": "这里应该用〈选手〉。球员只用于球类运动，长跑不属于球类，要说长跑选手。"}, {"text": "他是一名跳水球员。", "explanation": "这里应该用〈运动员〉。跳水不是球类运动，球员专指球类运动员，要说运动员。"}, {"text": "这位球员在医院给病人量体温。", "explanation": "这里应该用〈护士〉。球员指参加球类比赛的运动员，在医院给病人量体温的要说护士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "球员", "is_correct": true, "explanation": "正确。“球迷们给球员加油”中，球员是被加油的比赛参加者。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不参加比赛，球迷不会“给树加油”为它打气，句子不通。"}, {"text": "雨", "is_correct": false, "explanation": "配价：“给……加油”多用于人或队伍，不说“给雨加油”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会比赛，球迷不给桌子加油，句子意思不通。"}], "explanations": {"球员": "正确。“球迷们给球员加油”中，球员是被加油的比赛参加者。", "树": "语义：树不参加比赛，球迷不会“给树加油”为它打气，句子不通。", "雨": "配价：“给……加油”多用于人或队伍，不说“给雨加油”。", "桌子": "语义：桌子不会比赛，球迷不给桌子加油，句子意思不通。"}, "sentence_index": 6, "correct_answer": "球员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位球员在舞台上唱歌。", "explanation": "这里应该用〈歌手〉。球员指参加球类比赛的运动员，在舞台上唱歌的要说歌手。"}, {"text": "这位球员每天给花浇水。", "explanation": "这里应该用〈园丁〉。球员指参加球类比赛的运动员，不是照料花草的人，要说园丁。"}, {"text": "他是一名拳击球员。", "explanation": "这里应该用〈运动员〉。球员指参加球类比赛的运动员，拳击是个人格斗项目，不是球类，要说拳击运动员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只球员在比赛中进了两个球。", "corrected_sentence": "这名球员在比赛中进了两个球。", "error_description": "量词错误：“球员”指人，量词应用“名”或“位”。“只”不能指人，应改为“这名球员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经成为一名职业球员着。", "corrected_sentence": "他已经成为一名职业球员了。", "error_description": "体标错误：表示已经发生的变化用“了”，不能用“着”。“成为……着”不成立，应改为“成为一名职业球员了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
