INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91723, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预约是先说好，到时候再来。", "primary_collocate": null, "pronunciation": "yù yuē", "ipa": "y˥˩ ɥɛ˥", "syllable_count": 2, "sentences": [{"text": "我已经预约了明天上午的门诊。", "target_word": "预约", "complexity_tier": "T3", "furigana": "wǒ yǐ jīng yù yuē le míng tiān shàng wǔ de mén zhěn.", "sentence_source": "generated"}, {"text": "周六去饭店，要先预约。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想预约一个位子。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你预约的是几点钟？", "target_word": "预约", "complexity_tier": "T3", "furigana": "nǐ yù yuē de shì jǐ diǎn zhōng?", "sentence_source": "generated"}, {"text": "他预约过理发，可是忘了去。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店人很多，最好先预约。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给医院打电话预约看病。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈帮我预约了星期三的检查。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有预约，不能进去。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想预约下午三点的时间。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预约了", "label": "体标（了）"}, {"form": "预约过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "先说好，到时候再来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e23a7c-9131-4a56-a854-f3c79c067e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91723, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预约", "is_correct": true, "explanation": "“预约”指事先约定服务时间，与“门诊”搭配，句意通顺。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是房间等场所，不能用来处理门诊。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“门诊”搭配，说“吃门诊”不成话。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复物品，与“门诊”这种就医安排的情境不合。"}], "explanations": {"预约": "“预约”指事先约定服务时间，与“门诊”搭配，句意通顺。", "打扫": "语义：“打扫”的对象是房间等场所，不能用来处理门诊。", "吃": "搭配：“吃”不能与“门诊”搭配，说“吃门诊”不成话。", "修理": "语义：“修理”指修复物品，与“门诊”这种就医安排的情境不合。"}, "sentence_index": 0, "correct_answer": "预约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想预约一瓶矿泉水。", "explanation": "这里应该用〈买〉。预约指事先约定服务时间，买一瓶水直接购买即可，不需要预约。"}, {"text": "我想预约老师一个问题。", "explanation": "这里应该用〈问〉。预约指事先约定服务或时间，向老师提问题要说问。"}, {"text": "我已经预约了一份工作。", "explanation": "这里应该用〈应聘〉。预约指约定服务时间，申请工作要说应聘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91723, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预约", "is_correct": true, "explanation": "“预约”指事先约定，与“打电话……看病”相符，句意通顺。"}, {"text": "问候", "is_correct": false, "explanation": "语义：打电话的目的是约定看病，而“问候”是问好，与看病的事不合。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”后面不能直接接“看病”，二者搭配不当。"}, {"text": "批评", "is_correct": false, "explanation": "语义：打电话去批评别人，与看病这件事的语境不合。"}], "explanations": {"预约": "“预约”指事先约定，与“打电话……看病”相符，句意通顺。", "问候": "语义：打电话的目的是约定看病，而“问候”是问好，与看病的事不合。", "购买": "搭配：“购买”后面不能直接接“看病”，二者搭配不当。", "批评": "语义：打电话去批评别人，与看病这件事的语境不合。"}, "sentence_index": 6, "correct_answer": "预约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想预约一杯咖啡。", "explanation": "这里应该用〈点〉。预约指事先约定服务时间，买一杯咖啡是当场点，不需要预约。"}, {"text": "我想预约这个汉字的意思。", "explanation": "这里应该用〈查〉。预约指事先约定时间，想知道汉字的意思要说查。"}, {"text": "我想预约明天一天的假。", "explanation": "这里应该用〈请假〉。预约指事先约定服务时间，要休假要说请假。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还没预约了明天上午的门诊。", "corrected_sentence": "我还没预约明天上午的门诊。", "error_description": "“没”和“了”不能同用，否定句中“预约”后面不加“了”。正确形式是“还没预约”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想预约了明天下午三点的座位。", "corrected_sentence": "我想预约明天下午三点的座位。", "error_description": "体标错误：“想”表示意愿，不能与表示完成的“了”同用。正确形式是“想预约明天下午三点的座位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
