INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91724, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事先约定。", "primary_collocate": null, "pronunciation": "yù yuē", "ipa": "y˥˩ ɥɛ˥", "syllable_count": 2, "sentences": [{"text": "他们预约好了下周见面。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请提前一天预约房间。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上预约了一间会议室。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去博物馆参观要预约。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她已经预约了周五的牙科检查。", "target_word": "预约", "complexity_tier": "T3", "furigana": "tā yǐ jīng yù yuē le zhōu wǔ de yá kē jiǎn chá.", "sentence_source": "generated"}, {"text": "你预约过这个时间吗？", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师预约了明天下午的谈话。", "target_word": "预约", "complexity_tier": "T3", "furigana": "lǎo shī yù yuē le míng tiān xià wǔ de tán huà.", "sentence_source": "generated"}, {"text": "要是想剪头发，请先打电话预约。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经预约好座位了。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末的位子都预约满了。", "target_word": "预约", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预约了", "label": "体标（了）"}, {"form": "预约过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "事先约定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e23a7c-9131-4a56-a854-f3c79c067e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预约", "is_correct": true, "explanation": "“预约好”指事先约定好，与“下周见面”相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗好”与“见面”搭配不当，说不通。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理物品，与约定见面的情境无关。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆开、拆除，与约定见面的意思不合。"}], "explanations": {"预约": "“预约好”指事先约定好，与“下周见面”相符。", "洗": "搭配：“洗好”与“见面”搭配不当，说不通。", "修": "语义：“修”指修理物品，与约定见面的情境无关。", "拆": "语义：“拆”指拆开、拆除，与约定见面的意思不合。"}, "sentence_index": 0, "correct_answer": "预约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们今天要预约一瓶酱油。", "explanation": "这里应该用〈买〉。预约指事先约定服务时间，买酱油直接购买即可。"}, {"text": "我们下午要去超市预约东西。", "explanation": "这里应该用〈购买〉。预约指事先约定，去超市买东西直接购买即可。"}, {"text": "我们要预约大家明天开会。", "explanation": "这里应该用〈通知〉。预约指事先约定，告诉大家明天开会要用通知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预约", "is_correct": true, "explanation": "“预约”指事先约定，与“老师……明天下午的谈话”搭配，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“谈话”搭配，说“吃谈话”不成话。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”的动作与谈话无关，句子情境不合。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”指把东西放在太阳下，与谈话这件事无关。"}], "explanations": {"预约": "“预约”指事先约定，与“老师……明天下午的谈话”搭配，句意通顺。", "吃": "搭配：“吃”不能与“谈话”搭配，说“吃谈话”不成话。", "踢": "语义：“踢”的动作与谈话无关，句子情境不合。", "晒": "语义：“晒”指把东西放在太阳下，与谈话这件事无关。"}, "sentence_index": 6, "correct_answer": "预约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个周末的街道都预约满了。", "explanation": "这里应该用〈拥挤〉。预约指事先约定服务，街道上人多要说拥挤。"}, {"text": "这个周末的作业都预约完了。", "explanation": "这里应该用〈做〉。预约指事先约定，完成作业要说做完。"}, {"text": "这个周末的太阳都预约满了。", "explanation": "这里应该用〈照射〉。预约的对象必须是可以约定的服务，太阳只能用照射来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我正在电话里预约了下周的理发。", "corrected_sentence": "我正在电话里预约下周的理发。", "error_description": "体标错误：“正在”表示动作正在进行，不能与“了”同用。正确形式是“正在电话里预约下周的理发”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师已经预约了好明天的谈话。", "corrected_sentence": "老师已经预约好了明天的谈话。", "error_description": "补语位置错误：结果补语“好”应紧跟在动词后面，写成“预约好了”，不能放在“了”和宾语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
