INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91725, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "加入一个队伍或团体。", "primary_collocate": null, "pronunciation": "jiā méng", "ipa": "tɕja˥ məŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他去年加盟了这支球队。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位年轻球员想加盟一家大俱乐部。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今年夏天加盟了我们公司的篮球队。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那位外籍球星要加盟我们的足球队。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王以前加盟过一支有名的乐队。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一加盟球队，就进了三个球。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的球队欢迎新球员加盟。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥为了踢球，加盟了学校的足球队。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位歌手决定加盟这个新乐队。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练希望他明年能加盟我们队。", "target_word": "加盟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加盟了", "label": "体标（了）"}, {"form": "加盟过", "label": "体标（过）"}, {"form": "加盟者", "label": "复合"}], "register": "中性", "sense_fingerprint": "加入球队、乐队等队伍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab3b97-f3d7-4c95-a0b9-3d6f706e958c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91725, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加盟", "is_correct": true, "explanation": "正确：“加盟”指加入球队，与句中的“去年”“了”和“这支球队”搭配，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象应是食物，球队不能被吃，这句话荒谬。"}, {"text": "观看", "is_correct": false, "explanation": "搭配：“观看”的对象是比赛、演出，不说观看一支球队。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗，球队不能用来清洗，与句意不符。"}], "explanations": {"加盟": "正确：“加盟”指加入球队，与句中的“去年”“了”和“这支球队”搭配，句意通顺。", "吃": "语义：“吃”的对象应是食物，球队不能被吃，这句话荒谬。", "观看": "搭配：“观看”的对象是比赛、演出，不说观看一支球队。", "洗": "语义：“洗”是清洗，球队不能用来清洗，与句意不符。"}, "sentence_index": 0, "correct_answer": "加盟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他加盟了今年的足球比赛。", "explanation": "这里应该用〈参加〉。加盟指加入某个团队，比赛是活动，不是团队，不能说加盟。"}, {"text": "他加盟了这次会议。", "explanation": "这里应该用〈出席〉。会议是活动，人可以出席，但不能加盟会议。"}, {"text": "他加盟了昨天的生日晚会。", "explanation": "这里应该用〈参加〉。生日晚会是活动，不是队伍或团体，不能说加盟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91725, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加盟", "is_correct": true, "explanation": "正确：句末的“加盟”指新球员加入球队，与“欢迎新球员”的语境相合。"}, {"text": "退役", "is_correct": false, "explanation": "语义：“退役”指运动员退出现役，用在欢迎新球员的句子里不通。"}, {"text": "离开", "is_correct": false, "explanation": "语义：欢迎新球员离开球队与“欢迎”的意思相反，句子不合逻辑。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：“辞退”指解雇、让人离职，与“欢迎新球员”的语境相反，句子不通。"}], "explanations": {"加盟": "正确：句末的“加盟”指新球员加入球队，与“欢迎新球员”的语境相合。", "退役": "语义：“退役”指运动员退出现役，用在欢迎新球员的句子里不通。", "离开": "语义：欢迎新球员离开球队与“欢迎”的意思相反，句子不合逻辑。", "辞退": "语义：“辞退”指解雇、让人离职，与“欢迎新球员”的语境相反，句子不通。"}, "sentence_index": 6, "correct_answer": "加盟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "代表团加盟了这所大学。", "explanation": "这里应该用〈访问〉。代表团来访并不是加入大学，加盟不能用来表示访问。"}, {"text": "学生们加盟了这座博物馆。", "explanation": "这里应该用〈参观〉。学生去参观博物馆，博物馆是场所，不是团体，不能说加盟。"}, {"text": "我们加盟了这座古城。", "explanation": "这里应该用〈游览〉。古城是地方，游览的是风景，不是团体，不能说加盟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没加盟了这家俱乐部。", "corrected_sentence": "他没加盟这家俱乐部。", "error_description": "错误：用“没”否定过去的动作时，动词后不能再加“了”。应去掉“了”，说“没加盟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们想加盟了这家俱乐部。", "corrected_sentence": "我们想加盟这家俱乐部。", "error_description": "错误：“想”表示愿望，事情还没有发生，“加盟”后不能加“了”。应去掉“了”，说“想加盟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
