INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91727, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "监控是用摄像头一直看着，看有没有事。", "primary_collocate": null, "pronunciation": "jiān kòng", "ipa": "tɕjɛn˥ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "商店用摄像头监控着门口。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们昨天用摄像头监控了后门。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区的保安二十四小时监控着大门。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行一直在用摄像头监控客人进出。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察盯着摄像头画面，监控路口。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校用摄像头监控走廊。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板用手机连上摄像头，监控仓库。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把摄像头装好，开始监控停车场。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人睡觉时，摄像头还在监控着工厂。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场请人整天盯着屏幕监控各个出口。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "监控了", "label": "完成体"}, {"form": "监控着", "label": "持续体"}, {"form": "监控过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动词；用摄像头持续地看着某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a326b33e-2943-4e82-b30a-8c790c137e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91727, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "监控", "is_correct": true, "explanation": "正确：监控指用摄像头持续地看着某处，与“着门口”相合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理要接可修的器物，摄像头不能拿来修理门口。"}, {"text": "擦拭", "is_correct": false, "explanation": "语义：擦拭指擦干净表面，与用摄像头看守门口的意思不符。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：搬运指搬移货物，与用摄像头看守门口的意思不符。"}], "explanations": {"监控": "正确：监控指用摄像头持续地看着某处，与“着门口”相合。", "修理": "搭配：修理要接可修的器物，摄像头不能拿来修理门口。", "擦拭": "语义：擦拭指擦干净表面，与用摄像头看守门口的意思不符。", "搬运": "语义：搬运指搬移货物，与用摄像头看守门口的意思不符。"}, "sentence_index": 0, "correct_answer": "监控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们昨晚在电影院监控了一部新电影。", "explanation": "这里应该用〈看〉。监控指为了安全或管理而持续注视，看电影要用看。"}, {"text": "我们在饭店监控了一碗米饭。", "explanation": "这里应该用〈吃〉。监控指用摄像头或仪器持续注视、测量，吃饭要用吃，二者不能互换。"}, {"text": "我用手机监控了路边的花。", "explanation": "这里应该用〈拍〉。监控指为了安全或管理而持续注视，给花拍照要用拍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91727, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "监控", "is_correct": true, "explanation": "正确：监控指用手机连上摄像头持续看着仓库，与本句相合。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫指清扫，用手机连上摄像头不能打扫仓库。"}, {"text": "喷漆", "is_correct": false, "explanation": "语义：喷漆指给物体刷漆，与用手机看着仓库的意思不符。"}, {"text": "焚烧", "is_correct": false, "explanation": "语义：焚烧指烧毁，与用手机看着仓库的意思完全不符。"}], "explanations": {"监控": "正确：监控指用手机连上摄像头持续看着仓库，与本句相合。", "打扫": "语义：打扫指清扫，用手机连上摄像头不能打扫仓库。", "喷漆": "语义：喷漆指给物体刷漆，与用手机看着仓库的意思不符。", "焚烧": "语义：焚烧指烧毁，与用手机看着仓库的意思完全不符。"}, "sentence_index": 6, "correct_answer": "监控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在山顶监控了美丽的日出。", "explanation": "这里应该用〈欣赏〉。监控指为了安全或管理而持续注视，欣赏风景不能用监控。"}, {"text": "我们在饭店监控了他的生日。", "explanation": "这里应该用〈庆祝〉。监控指持续注视以便管理，生日这类喜庆活动要用庆祝。"}, {"text": "我每天早上都监控一杯咖啡。", "explanation": "这里应该用〈喝〉。监控指为了安全或管理而持续注视，喝咖啡要用喝，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门卫用摄像头监控了着后院。", "corrected_sentence": "门卫用摄像头监控着后院。", "error_description": "错误：“了”表示动作完成，“着”表示动作持续，二者不能同时用在“监控”后面。应去掉“了”，正确为“门卫用摄像头监控着后院。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店主没有用摄像头监控了收银台。", "corrected_sentence": "店主没有用摄像头监控收银台。", "error_description": "错误：“没有”表示否定，否定句中的“监控”后不能加“了”。正确为“没有用摄像头监控收银台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
