INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91728, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用仪器或系统监视并控制某种情况。", "primary_collocate": null, "pronunciation": "jiān kòng", "ipa": "tɕjɛn˥ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "工人用机器监控着炉子的温度。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生每天监控他的血糖。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用软件监控网络的速度。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统能自动监控水的质量。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们二十四小时监控机器的运行。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士用仪器监控病人的心跳。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂要严格监控产品的质量。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以监控孩子玩手机的时间。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市用机器监控空气的变化。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用电脑监控大棚里的湿度。", "target_word": "监控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "监控了", "label": "完成体"}, {"form": "监控着", "label": "持续体"}, {"form": "监控过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动词；用仪器或系统监视并控制情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a326b33e-2943-4e82-b30a-8c790c137e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "监控", "is_correct": true, "explanation": "正确：监控指用仪器持续监视并控制炉子的温度，与本句相合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理要接可修的器物，温度不能被修理。"}, {"text": "擦拭", "is_correct": false, "explanation": "语义：擦拭指擦干净表面，与用机器监视温度的意思不符。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：搬运指搬移货物，温度不能被搬运。"}], "explanations": {"监控": "正确：监控指用仪器持续监视并控制炉子的温度，与本句相合。", "修理": "搭配：修理要接可修的器物，温度不能被修理。", "擦拭": "语义：擦拭指擦干净表面，与用机器监视温度的意思不符。", "搬运": "语义：搬运指搬移货物，温度不能被搬运。"}, "sentence_index": 0, "correct_answer": "监控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用尺子监控房间的面积。", "explanation": "这里应该用〈测量〉。监控指持续观察并控制变化，一次性量面积要用测量。"}, {"text": "我提前监控了两张票。", "explanation": "这里应该用〈预订〉。监控指持续观察和控制，不能表示事先订好票。"}, {"text": "保安用扫帚监控着停车场。", "explanation": "这里应该用〈打扫〉。监控指用设备或人持续监视和控制，用扫帚打扫停车场要用打扫，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "监控", "is_correct": true, "explanation": "正确：监控指持续监视并控制产品的质量，与本句相合。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：清洗要接可洗的东西，“清洗质量”不能这样说。"}, {"text": "运输", "is_correct": false, "explanation": "语义：运输指搬运货物，与严格监视产品质量的意思不符。"}, {"text": "打包", "is_correct": false, "explanation": "语义：打包指把东西包装起来，与监视产品质量的意思不符。"}], "explanations": {"监控": "正确：监控指持续监视并控制产品的质量，与本句相合。", "清洗": "搭配：清洗要接可洗的东西，“清洗质量”不能这样说。", "运输": "语义：运输指搬运货物，与严格监视产品质量的意思不符。", "打包": "语义：打包指把东西包装起来，与监视产品质量的意思不符。"}, "sentence_index": 6, "correct_answer": "监控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈监控了一件衣服。", "explanation": "这里应该用〈挑选〉。监控指持续观察或测量某种指标，挑衣服不能用监控。"}, {"text": "我昨天监控了一封信。", "explanation": "这里应该用〈寄〉。监控指持续观察或测量，寄信不能用监控。"}, {"text": "我昨天监控了一张床。", "explanation": "这里应该用〈躺〉。监控指用设备或人持续监视和控制，躺在床上要用躺，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台仪器正在实时监控了汽车的油压。", "corrected_sentence": "这台仪器正在实时监控汽车的油压。", "error_description": "错误：“正在”表示动作正在进行，不能与表示完成的“了”同用。应去掉“了”，正确为“正在实时监控汽车的油压”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "技术员用电脑监控了着温室里的湿度。", "corrected_sentence": "技术员用电脑监控着温室里的湿度。", "error_description": "错误：“了”与“着”不能同时用在同一个动词“监控”后面，“着”表示持续，应去掉“了”。正确为“技术员用电脑监控着温室里的湿度。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
