INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91729, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "风俗是一个地方的人过去传下来的习惯。", "primary_collocate": null, "pronunciation": "fēng sú", "ipa": "fɤŋ˥˥ su˧˥", "syllable_count": 2, "sentences": [{"text": "每个地方的风俗都不一样。", "target_word": "风俗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年吃饺子是北方的风俗。", "target_word": "风俗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想了解中国的风俗。", "target_word": "风俗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子有很多老风俗。", "target_word": "风俗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到别的国家，要先了解当地的风俗。", "target_word": "风俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的风俗是见面先喝茶。", "target_word": "风俗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很喜欢研究各地的风俗。", "target_word": "风俗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种风俗已经有几百年了。", "target_word": "风俗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷给我讲了家乡的风俗。", "target_word": "风俗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在南方，端午节赛龙舟是一种风俗。", "target_word": "风俗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "风俗习惯", "label": "复合"}, {"form": "風俗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个地方的人世代传下来的习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa7062f5-2af6-4f8f-accf-5e5f322266bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91729, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风俗", "is_correct": true, "explanation": "风俗指一个地方世代流传的习惯，与“每个地方”的说法相合。"}, {"text": "星球", "is_correct": false, "explanation": "搭配：“星球”指天体，不说“每个地方的星球”。"}, {"text": "皇帝", "is_correct": false, "explanation": "语义：皇帝在一个国家只有一位，不能说“每个地方的皇帝都不一样”。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳在天上只有一个，与“每个地方”的说法矛盾。"}], "explanations": {"风俗": "风俗指一个地方世代流传的习惯，与“每个地方”的说法相合。", "星球": "搭配：“星球”指天体，不说“每个地方的星球”。", "皇帝": "语义：皇帝在一个国家只有一位，不能说“每个地方的皇帝都不一样”。", "太阳": "语义：太阳在天上只有一个，与“每个地方”的说法矛盾。"}, "sentence_index": 0, "correct_answer": "风俗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他养成了早起的风俗。", "explanation": "这里应该用〈习惯〉。风俗指一地人群共同传下来的习惯，个人的作息只能说习惯。"}, {"text": "这次投资的风俗太大了，我不敢做。", "explanation": "这里应该用〈风险〉。风俗指地方传下来的习惯，投资的危险要用风险。"}, {"text": "他办事的风俗很严谨。", "explanation": "这里应该用〈作风〉。风俗指群体的习惯，个人的办事态度要用作风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91729, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风俗", "is_correct": true, "explanation": "风俗是某地长期流传的习惯，可以被研究。"}, {"text": "哈欠", "is_correct": false, "explanation": "语义：哈欠是身体的生理反应，不是可以研究的社会习惯。"}, {"text": "口水", "is_correct": false, "explanation": "语义：口水是身体的分泌物，不是可以研究的社会习惯。"}, {"text": "嗓子", "is_correct": false, "explanation": "语义：嗓子是人的身体器官，不是可以研究的社会习惯。"}], "explanations": {"风俗": "风俗是某地长期流传的习惯，可以被研究。", "哈欠": "语义：哈欠是身体的生理反应，不是可以研究的社会习惯。", "口水": "语义：口水是身体的分泌物，不是可以研究的社会习惯。", "嗓子": "语义：嗓子是人的身体器官，不是可以研究的社会习惯。"}, "sentence_index": 6, "correct_answer": "风俗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村口的风俗真美，我们拍了很多照片。", "explanation": "这里应该用〈风景〉。风俗指地方传下来的习惯，眼前的景色要用风景。"}, {"text": "他说话很有风俗，大家都很尊敬他。", "explanation": "这里应该用〈风度〉。风俗指地方传下来的习惯，人的举止气派要用风度。"}, {"text": "这道菜的风俗很独特，很多人都爱吃。", "explanation": "这里应该用〈风味〉。风俗指地方传下来的习惯，菜肴的味道特色要用风味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里的这只风俗已经流传了很久。", "corrected_sentence": "村里的这种风俗已经流传了很久。", "error_description": "“风俗”的量词应为“种”，“只”多用于动物等，这里用错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人把这些风俗讲了给孩子们。", "corrected_sentence": "老人把这些风俗讲给了孩子们。", "error_description": "“讲给”是动词加补语，“了”应放在“讲给”之后。这里写成“讲了给”，“了”的位置错误，应说“讲给了孩子们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
