INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91730, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某地长期形成并流传下来的社会习惯。", "primary_collocate": null, "pronunciation": "fēng sú", "ipa": "fɤŋ˥˥ su˧˥", "syllable_count": 2, "sentences": [{"text": "不同民族有不同的风俗。", "target_word": "风俗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个节日的风俗传了上千年。", "target_word": "风俗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们介绍了春节的风俗。", "target_word": "风俗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在有些旧风俗已经没有了。", "target_word": "风俗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写了一本书，说的是各地的风俗。", "target_word": "风俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尊重当地的风俗，是对别人的礼貌。", "target_word": "风俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各地结婚的风俗很不一样。", "target_word": "风俗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座古城保留着很多古老的风俗。", "target_word": "风俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风俗会随着时间慢慢变化。", "target_word": "风俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在节日里学习了传统风俗。", "target_word": "风俗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "风俗习惯", "label": "复合"}, {"form": "風俗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某地长期形成并流传的社会习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa7062f5-2af6-4f8f-accf-5e5f322266bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91730, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风俗", "is_correct": true, "explanation": "风俗是某地或某民族长期形成的习惯，与“不同民族”相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是个人的属性，不指民族之间的差别。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气由地区决定，不是民族之间的差别。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“闹钟”是定时响铃的计时器，不用来说明民族的差别。"}], "explanations": {"风俗": "风俗是某地或某民族长期形成的习惯，与“不同民族”相合。", "年龄": "语义：年龄是个人的属性，不指民族之间的差别。", "天气": "语义：天气由地区决定，不是民族之间的差别。", "闹钟": "搭配：“闹钟”是定时响铃的计时器，不用来说明民族的差别。"}, "sentence_index": 0, "correct_answer": "风俗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我养成了每天跑步的风俗。", "explanation": "这里应该用〈习惯〉。个人每天跑步的习惯只能说习惯，风俗指一地人群共有的习惯。"}, {"text": "这位老师的教学风俗很严谨。", "explanation": "这里应该用〈作风〉。风俗指群体的习惯，个人的教学态度要用作风。"}, {"text": "这位作家的写作风俗很独特。", "explanation": "这里应该用〈风格〉。风俗是群体的习惯，作家的写作特色要用风格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风俗", "is_correct": true, "explanation": "风俗指各地婚礼等习惯，与“各地”和“不一样”相合。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是个人的日子，不是各地不同的习惯。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“方向”不与“结婚的”搭配，句子说不通。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司是企业单位，不能说“各地结婚的公司”。"}], "explanations": {"风俗": "风俗指各地婚礼等习惯，与“各地”和“不一样”相合。", "生日": "语义：生日是个人的日子，不是各地不同的习惯。", "方向": "搭配：“方向”不与“结婚的”搭配，句子说不通。", "公司": "语义：公司是企业单位，不能说“各地结婚的公司”。"}, "sentence_index": 6, "correct_answer": "风俗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一带的风俗很大，船都不敢出海。", "explanation": "这里应该用〈风力〉。风俗指社会习惯，形容风的强弱要用风力。"}, {"text": "这种风俗很好听，大家都会唱。", "explanation": "这里应该用〈民歌〉。风俗指社会习惯，可以唱的曲调要用民歌。"}, {"text": "这部电影的风俗很感人，大家都看哭了。", "explanation": "这里应该用〈剧情〉。风俗指社会习惯，故事的情节要用剧情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里还保留着一座古老的风俗。", "corrected_sentence": "村里还保留着一种古老的风俗。", "error_description": "“风俗”的量词应为“种”，“座”用于山、楼等大型固定物，这里用错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把节日的风俗教了给我。", "corrected_sentence": "妈妈把节日的风俗教给了我。", "error_description": "“教给”是动词加补语，“了”应放在“教给”之后。这里写成“教了给我”，“了”的位置错误，应说“教给了我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
