INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91734, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "社会生产、分配和消费的总体状况。", "primary_collocate": null, "pronunciation": "shè huì jīng jì", "ipa": "ʂɤ˥˩ xweɪ˥˩ tɕiŋ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "国家的社会经济需要生产和消费共同发展。", "target_word": "社会经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年全国的社会经济保持了稳定。", "target_word": "社会经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告分析了社会经济的总体情况。", "target_word": "社会经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产、分配和消费构成社会经济。", "target_word": "社会经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府很关心社会经济的发展。", "target_word": "社会经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会经济发展得快，人们的生活就会变好。", "target_word": "社会经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让这个国家的社会经济受到很大影响。", "target_word": "社会经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上讲了社会经济的基本知识。", "target_word": "社会经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，明年社会经济会继续增长。", "target_word": "社会经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书研究的是古代社会经济。", "target_word": "社会经济", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "社會經濟", "label": "繁体"}], "register": "书面", "sense_fingerprint": "社会经济：全社会生产、分配、消费的总体状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1766c185-9168-436d-834a-7e1714ef858c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社会经济", "is_correct": true, "explanation": "正确：「社会经济」指全社会生产、分配和消费的总体状况，能够「发展」。"}, {"text": "个人", "is_correct": false, "explanation": "语义：个人不是「生产和消费共同发展」的对象，这里应指全社会的总体状况。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「发展」不能用于体重。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不需要靠生产和消费来发展，句中的主语应是经济整体。"}], "explanations": {"社会经济": "正确：「社会经济」指全社会生产、分配和消费的总体状况，能够「发展」。", "个人": "语义：个人不是「生产和消费共同发展」的对象，这里应指全社会的总体状况。", "体重": "搭配：「发展」不能用于体重。", "天气": "语义：天气不需要靠生产和消费来发展，句中的主语应是经济整体。"}, "sentence_index": 0, "correct_answer": "社会经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂去年的社会经济很好。", "explanation": "这里应该用〈经营状况〉。社会经济指全社会的生产、分配和消费状况，说一家工厂的运营情况要用〈经营状况〉。"}, {"text": "这家商店的社会经济很稳定。", "explanation": "这里应该用〈经营状况〉。社会经济不用来说某个商店，商店的运营情况要用〈经营状况〉。"}, {"text": "这所学校的社会经济很稳定。", "explanation": "这里应该用〈办学状况〉。社会经济指全社会的总体情况，说一所学校的运营要用〈办学状况〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社会经济", "is_correct": true, "explanation": "正确：「社会经济」指全社会的总体状况，可以「受到影响」。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：战争不会让年龄「受到很大影响」，句中的主语应是国家的经济整体。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会因战争而受到很大影响，与「这个国家」的整体状况不相符。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：「字数」不能说「受到很大影响」，这种说法只用于状况、情况类的名词。"}], "explanations": {"社会经济": "正确：「社会经济」指全社会的总体状况，可以「受到影响」。", "年龄": "语义：战争不会让年龄「受到很大影响」，句中的主语应是国家的经济整体。", "颜色": "语义：颜色不会因战争而受到很大影响，与「这个国家」的整体状况不相符。", "字数": "搭配：「字数」不能说「受到很大影响」，这种说法只用于状况、情况类的名词。"}, "sentence_index": 6, "correct_answer": "社会经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院的社会经济很好。", "explanation": "这里应该用〈经济状况〉。社会经济指整个社会的生产、分配和消费情况，一家医院的财务情况要用〈经济状况〉。"}, {"text": "这间教室的社会经济很好。", "explanation": "这里应该用〈教学条件〉。社会经济指全社会的总体情况，说一间教室的状况要用〈教学条件〉。"}, {"text": "我家的社会经济这个月不太好。", "explanation": "这里应该用〈经济情况〉。社会经济指全社会的生产、分配和消费状况，说一个家庭的收支要用〈经济情况〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "专家们研究过国家得社会经济。", "corrected_sentence": "专家们研究过国家的社会经济。", "error_description": "结构助词错误：修饰名词「社会经济」要用「的」，这里误用「得」（「得」用于动词或形容词之后的补语）。正确：「国家的社会经济」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年，这个国家的社会经济发展的很快。", "corrected_sentence": "这几年，这个国家的社会经济发展得很快。", "error_description": "结构助词错误：动词“发展”后接程度补语“很快”要用“得”，这里误用“的”。正确：“社会经济发展得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
