INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91737, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "种族是人们按皮肤、头发等分成的大类。", "primary_collocate": null, "pronunciation": "zhǒng zú", "ipa": "tʂʊŋ˨˩ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "人们按皮肤和头发把人分成不同的种族。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同种族的孩子在同一个班里学习。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不在乎别人是什么种族。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家里有很多种族，大家一起生活。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮肤的颜色不能决定一个人的种族。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美国的表格上常常要求填写种族。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的丈夫和她不是同一个种族。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，每个种族都有自己的文化。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能因为种族不同就看不起别人。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上讲了世界上有几个大的种族。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种族歧视", "label": "复合"}, {"form": "种族主义", "label": "复合"}], "register": "中性", "sense_fingerprint": "按皮肤、头发等特征把人分成的大类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c2c863-16c7-4006-ae6b-2673000b2f08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91737, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职业", "is_correct": false, "explanation": "语义：职业不能靠皮肤和头发来划分，与句中的分类标准相矛盾。"}, {"text": "种族", "is_correct": true, "explanation": "种族：按皮肤、头发等划分的人群大类，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是由皮肤和头发决定的，与句中“按皮肤和头发”的标准不符。"}, {"text": "国家", "is_correct": false, "explanation": "语义：国家是按行政区划划分的，不是按皮肤和头发划分的人群，与句中的分类标准不符。"}], "explanations": {"职业": "语义：职业不能靠皮肤和头发来划分，与句中的分类标准相矛盾。", "种族": "种族：按皮肤、头发等划分的人群大类，符合句意。", "年龄": "语义：年龄不是由皮肤和头发决定的，与句中“按皮肤和头发”的标准不符。", "国家": "语义：国家是按行政区划划分的，不是按皮肤和头发划分的人群，与句中的分类标准不符。"}, "sentence_index": 0, "correct_answer": "种族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我国有五十六个种族，大家都很团结。", "explanation": "这里应该用〈民族〉。中国境内的群体称民族，不用“种族”来数我国的少数群体。"}, {"text": "这种狗有很多种族，有大有小。", "explanation": "这里应该用〈品种〉。种族只用于人，动物应说品种。"}, {"text": "他的种族是医生，每天都很忙。", "explanation": "这里应该用〈职业〉。种族指人群的生理分类，不能用来说一个人的职业是医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物种", "is_correct": false, "explanation": "语义：丈夫和她同属人类，不能说他们不是同一个物种。"}, {"text": "季节", "is_correct": false, "explanation": "搭配：“季节”不能用来指人与人的归属，与“同一个”搭配不当。"}, {"text": "种族", "is_correct": true, "explanation": "种族：根据体质特征划分的人群，符合“丈夫和她”的语境。"}, {"text": "树种", "is_correct": false, "explanation": "语义：树种是植物的类别，与人物的关系不符。"}], "explanations": {"物种": "语义：丈夫和她同属人类，不能说他们不是同一个物种。", "季节": "搭配：“季节”不能用来指人与人的归属，与“同一个”搭配不当。", "种族": "种族：根据体质特征划分的人群，符合“丈夫和她”的语境。", "树种": "语义：树种是植物的类别，与人物的关系不符。"}, "sentence_index": 6, "correct_answer": "种族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片海里生活着上千个种族的鱼。", "explanation": "这里应该用〈种类〉。种族只指人类内部的群体，鱼等动物应说种类或物种。"}, {"text": "这家公司的种族卖得很好。", "explanation": "这里应该用〈产品〉。种族是人群的分类，不能用来说商品卖得好。"}, {"text": "这片林子里有很多种族。", "explanation": "这里应该用〈树种〉。植物的类别要说树种，种族只用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些人来自不同只种族。", "corrected_sentence": "这些人来自不同的种族。", "error_description": "量词错误。“只”用于动物等，不能用来数“种族”，应说“不同的种族”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件种族的人都很友好。", "corrected_sentence": "这个种族的人都很友好。", "error_description": "量词错误。“件”不用于人群，“种族”要用量词“个”，应说“这个种族”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
