INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91738, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "根据体质特征划分的人群。", "primary_collocate": null, "pronunciation": "zhǒng zú", "ipa": "tʂʊŋ˨˩ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "科学家研究不同种族的身体特点。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病在某些种族中比较常见。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种族不同，头发和眼睛的样子也不一样。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问我属于哪个种族。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们来自不同的种族，却成了好朋友。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的种族个子高，有的种族个子矮。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的人分成好几个种族。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不允许因种族不同而区别对待。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了世界上主要的种族。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究过非洲几个种族的历史。", "target_word": "种族", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种族歧视", "label": "复合"}, {"form": "种族主义", "label": "复合"}], "register": "中性", "sense_fingerprint": "根据体质特征划分出来的人群", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c2c863-16c7-4006-ae6b-2673000b2f08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文字", "is_correct": false, "explanation": "语义：文字没有身体特点，与“研究身体特点”的语境不符。"}, {"text": "种族", "is_correct": true, "explanation": "种族：根据体质特征划分的人群，符合“身体特点”的研究语境。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“身体特点”的研究对象是人群，“颜色”与“研究身体特点”搭配不当。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言不是人群，不能研究它的身体特点。"}], "explanations": {"文字": "语义：文字没有身体特点，与“研究身体特点”的语境不符。", "种族": "种族：根据体质特征划分的人群，符合“身体特点”的研究语境。", "颜色": "搭配：“身体特点”的研究对象是人群，“颜色”与“研究身体特点”搭配不当。", "语言": "语义：语言不是人群，不能研究它的身体特点。"}, "sentence_index": 0, "correct_answer": "种族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是哪个种族的？他是汉族。", "explanation": "这里应该用〈民族〉。汉族是民族名称，问属于哪个群体应说民族，不说种族。"}, {"text": "这只狗是哪个种族的？", "explanation": "这里应该用〈品种〉。种族只用于人，问狗属于哪一类应说品种。"}, {"text": "我的朋友很喜欢种族，周末常去听演唱会。", "explanation": "这里应该用〈音乐〉。种族指人群的生理分类，不能当作喜欢的对象，应说喜欢音乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物种", "is_correct": false, "explanation": "语义：那里的人同属一个物种，不能说分成好几个物种。"}, {"text": "种族", "is_correct": true, "explanation": "种族：根据体质特征划分的人群，符合“分成好几个”的语境。"}, {"text": "树种", "is_correct": false, "explanation": "语义：树种是植物的类别，与“那里的人”不符。"}, {"text": "星座", "is_correct": false, "explanation": "语义：星座是按出生日期划分的，不是人群的类别，与“那里的人分成好几个”不符。"}], "explanations": {"物种": "语义：那里的人同属一个物种，不能说分成好几个物种。", "种族": "种族：根据体质特征划分的人群，符合“分成好几个”的语境。", "树种": "语义：树种是植物的类别，与“那里的人”不符。", "星座": "语义：星座是按出生日期划分的，不是人群的类别，与“那里的人分成好几个”不符。"}, "sentence_index": 6, "correct_answer": "种族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个种族的首都是北京。", "explanation": "这里应该用〈国家〉。种族是人群的生理分类，没有首都，说首都是北京要用〈国家〉。"}, {"text": "这片湖里有很多种族。", "explanation": "这里应该用〈物种〉。种族只用于人类群体，湖里的鱼、鸟等生物要说物种。"}, {"text": "这家餐厅的种族很好吃，价格也便宜。", "explanation": "这里应该用〈菜〉。种族是人群的分类，不能用来说食物好吃，应说菜好吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只种族的人个子都很高。", "corrected_sentence": "这个种族的人个子都很高。", "error_description": "量词错误。“种族”指人群，要用量词“个”，应说“这个种族”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个古老得种族。", "corrected_sentence": "这是一个古老的种族。", "error_description": "“得”和“的”混用。“古老”修饰名词“种族”要用“的”，“得”用在动词或形容词后作补语，应说“古老的种族”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
