INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91739, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91739, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "首度是第一次。", "primary_collocate": null, "pronunciation": "shǒu dù", "ipa": "ʂoʊ˨˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这位歌手今年首度来到我们的城市。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司首度在海外开了一家店。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他首度当上了班长，心里很高兴。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影首度在中国上映。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明首度一个人坐飞机去北京。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队首度打进了决赛。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年冬天，这座城市首度下了大雪。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她首度参加比赛，有点儿紧张。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院首度用机器人做手术。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校今年首度举办了读书节。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词：第一次做某事，多用于书面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e27c0865-ac13-463b-bae0-85a44d455076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91739, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "首度", "is_correct": true, "explanation": "首度读 shǒu dù，表示第一次，是正确答案。"}, {"text": "首都", "is_correct": false, "explanation": "dū（第一声）与 dù（第四声）只是声调不同，shǒudū 意思是首都，不是第一次。"}, {"text": "首付", "is_correct": false, "explanation": "fù 与 dù 声母不同（f/d），shǒufù 意思是首付（首期付款）。"}, {"text": "手术", "is_correct": false, "explanation": "shù 与 dù 声母不同（sh/d），shǒushù 意思是手术。"}, {"text": "首部", "is_correct": false, "explanation": "bù 与 dù 声母不同（b/d），shǒubù 意思是首部，指作品的第一部。"}], "explanations": {"首度": "首度读 shǒu dù，表示第一次，是正确答案。", "首都": "dū（第一声）与 dù（第四声）只是声调不同，shǒudū 意思是首都，不是第一次。", "首付": "fù 与 dù 声母不同（f/d），shǒufù 意思是首付（首期付款）。", "手术": "shù 与 dù 声母不同（sh/d），shǒushù 意思是手术。", "首部": "bù 与 dù 声母不同（b/d），shǒubù 意思是首部，指作品的第一部。"}, "sentence_index": null, "correct_answer": "首度"}, "level_3": {"options": [{"text": "纷纷", "is_correct": false, "explanation": "语义：“纷纷”表示许多人相继做某事，与“这位歌手”一人不合，句子读来不通。"}, {"text": "首度", "is_correct": true, "explanation": "首度是副词，表示第一次，与“今年”和“来到”搭配，符合句意。"}, {"text": "各自", "is_correct": false, "explanation": "语义：“各自”需要多个主体分别行动，与“这位歌手”一人不合，句子读来不通。"}, {"text": "互相", "is_correct": false, "explanation": "语义：“互相”需要两个以上的主体彼此动作，与“这位歌手”一人不合。"}], "explanations": {"纷纷": "语义：“纷纷”表示许多人相继做某事，与“这位歌手”一人不合，句子读来不通。", "首度": "首度是副词，表示第一次，与“今年”和“来到”搭配，符合句意。", "各自": "语义：“各自”需要多个主体分别行动，与“这位歌手”一人不合，句子读来不通。", "互相": "语义：“互相”需要两个以上的主体彼此动作，与“这位歌手”一人不合。"}, "sentence_index": 0, "correct_answer": "首度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每周都首度检查门窗。", "explanation": "这里表示每周重复发生的检查，应该用〈定期〉。首度只说明某件事第一次发生，不能用于每周都发生的事。"}, {"text": "他连续首度参加了三场比赛。", "explanation": "这里表示多场比赛接连发生，应该用〈多次〉。首度只说明第一次，不能用于连续多场的情况。"}, {"text": "这部电影已经首度上映了两次。", "explanation": "这里表示已经重复发生，应该用〈再次〉。首度只说明第一次，与重复发生的意思相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91739, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "首度", "is_correct": true, "explanation": "首度读 shǒu dù，表示第一次，是正确答案。"}, {"text": "首富", "is_correct": false, "explanation": "fù 与 dù 声母不同（f/d），shǒufù 意思是首富，指最富有的人。"}, {"text": "手部", "is_correct": false, "explanation": "bù 与 dù 声母不同（b/d），shǒubù 意思是手部，指手的部分。"}, {"text": "手误", "is_correct": false, "explanation": "wù 与 dù 声母不同（w/d），shǒuwù 意思是手误，指不小心写错或打错字。"}], "explanations": {"首度": "首度读 shǒu dù，表示第一次，是正确答案。", "首富": "fù 与 dù 声母不同（f/d），shǒufù 意思是首富，指最富有的人。", "手部": "bù 与 dù 声母不同（b/d），shǒubù 意思是手部，指手的部分。", "手误": "wù 与 dù 声母不同（w/d），shǒuwù 意思是手误，指不小心写错或打错字。"}, "sentence_index": null, "correct_answer": "首度"}, "level_3": {"options": [{"text": "年年", "is_correct": false, "explanation": "语义：“年年”表示每年都，与“去年冬天”这一特定时间矛盾。"}, {"text": "首度", "is_correct": true, "explanation": "首度是副词，表示第一次，与“去年冬天”和“下了大雪”搭配，符合句意。"}, {"text": "一起", "is_correct": false, "explanation": "配价：“一起”需要多个施事共同行动，而“下雪”没有共同施事，句子说不通。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”要求紧接前面的事件，句中没有可接续的事，读来不通。"}], "explanations": {"年年": "语义：“年年”表示每年都，与“去年冬天”这一特定时间矛盾。", "首度": "首度是副词，表示第一次，与“去年冬天”和“下了大雪”搭配，符合句意。", "一起": "配价：“一起”需要多个施事共同行动，而“下雪”没有共同施事，句子说不通。", "立刻": "语义：“立刻”要求紧接前面的事件，句中没有可接续的事，读来不通。"}, "sentence_index": 6, "correct_answer": "首度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校今年又首度举办了读书节。", "explanation": "这里表示重复发生，应该用〈再次〉。首度只说明第一次，不能表示重复发生。"}, {"text": "我们学校今年首度举办了三次读书节。", "explanation": "这里表示同一年多次发生，应该用〈多次〉。首度只说明第一次，不能用于多次的情况。"}, {"text": "我们学校今年经常首度举办读书节。", "explanation": "这里表示经常发生，应该用〈屡次〉。首度只说明第一次，与反复发生的意思相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们首度的登上了长城。", "corrected_sentence": "他们首度登上了长城。", "error_description": "“首度”是副词，后面不能加“的”修饰动词“登上”。正确说法是“他们首度登上了长城”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校首度了请来一位作家。", "corrected_sentence": "我们学校首度请来一位作家。", "error_description": "“首度”是副词，后面不能直接加“了”。这里的“了”不应放在副词之后。正确说法是“我们学校首度请来一位作家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
