INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91740, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，第一次。", "primary_collocate": null, "pronunciation": "shǒu dù", "ipa": "ʂoʊ˨˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这位老作家首度谈起自己的童年。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理首度公开了公司的新计划。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国队首度获得了世界冠军。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人首度见面，就聊了三个小时。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目首度请来了外国老师。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥首度对外开放，很多人来看。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师首度带学生去山里上课。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位年轻人首度出国，什么都觉得新鲜。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书首度翻译成了英文。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的城市首度举行了国际马拉松。", "target_word": "首度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词：第一次，用于书面叙述", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e27c0865-ac13-463b-bae0-85a44d455076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91740, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "首度", "is_correct": true, "explanation": "首度读 shǒu dù，表示第一次，是正确答案。"}, {"text": "首都", "is_correct": false, "explanation": "dū（第一声）与 dù（第四声）只是声调不同，shǒudū 意思是首都，不是第一次。"}, {"text": "首付", "is_correct": false, "explanation": "fù 与 dù 声母不同（f/d），shǒufù 意思是首付（首期付款）。"}, {"text": "手术", "is_correct": false, "explanation": "shù 与 dù 声母不同（sh/d），shǒushù 意思是手术。"}, {"text": "首部", "is_correct": false, "explanation": "bù 与 dù 声母不同（b/d），shǒubù 意思是首部，指作品的第一部。"}], "explanations": {"首度": "首度读 shǒu dù，表示第一次，是正确答案。", "首都": "dū（第一声）与 dù（第四声）只是声调不同，shǒudū 意思是首都，不是第一次。", "首付": "fù 与 dù 声母不同（f/d），shǒufù 意思是首付（首期付款）。", "手术": "shù 与 dù 声母不同（sh/d），shǒushù 意思是手术。", "首部": "bù 与 dù 声母不同（b/d），shǒubù 意思是首部，指作品的第一部。"}, "sentence_index": null, "correct_answer": "首度"}, "level_3": {"options": [{"text": "齐声", "is_correct": false, "explanation": "语义：“齐声”指众人同时发声，与“这位老作家”一人不合。"}, {"text": "首度", "is_correct": true, "explanation": "首度是副词，表示第一次，与“这位老作家”和“谈起童年”搭配，符合句意。"}, {"text": "同时", "is_correct": false, "explanation": "配价：“同时”需要另一个同时发生的人或事作参照，句中没有，句子不完整。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”修饰的应是多个对象，与“谈起自己的童年”这一次行为不符。"}], "explanations": {"齐声": "语义：“齐声”指众人同时发声，与“这位老作家”一人不合。", "首度": "首度是副词，表示第一次，与“这位老作家”和“谈起童年”搭配，符合句意。", "同时": "配价：“同时”需要另一个同时发生的人或事作参照，句中没有，句子不完整。", "全部": "语义：“全部”修饰的应是多个对象，与“谈起自己的童年”这一次行为不符。"}, "sentence_index": 0, "correct_answer": "首度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每周都首度整理房间。", "explanation": "这里表示每周重复的整理，应该用〈定期〉。首度只说明某件事第一次发生，不能用于每周都发生的事。"}, {"text": "我们俩每天首度见面。", "explanation": "这里表示每天反复见面，应该用〈经常〉。首度只说明第一次，不能用于每天重复的事。"}, {"text": "他首度讨厌上班，这种感觉已经持续十年了。", "explanation": "这里表示状态持续了很久，应该用〈一直〉。首度只说明第一次，不能用于持续多年的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91740, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "首度", "is_correct": true, "explanation": "首度读 shǒu dù，表示第一次，是正确答案。"}, {"text": "首富", "is_correct": false, "explanation": "fù 与 dù 声母不同（f/d），shǒufù 意思是首富，指最富有的人。"}, {"text": "手部", "is_correct": false, "explanation": "bù 与 dù 声母不同（b/d），shǒubù 意思是手部，指手的部分。"}, {"text": "手误", "is_correct": false, "explanation": "wù 与 dù 声母不同（w/d），shǒuwù 意思是手误，指不小心写错或打错字。"}], "explanations": {"首度": "首度读 shǒu dù，表示第一次，是正确答案。", "首富": "fù 与 dù 声母不同（f/d），shǒufù 意思是首富，指最富有的人。", "手部": "bù 与 dù 声母不同（b/d），shǒubù 意思是手部，指手的部分。", "手误": "wù 与 dù 声母不同（w/d），shǒuwù 意思是手误，指不小心写错或打错字。"}, "sentence_index": null, "correct_answer": "首度"}, "level_3": {"options": [{"text": "纷纷", "is_correct": false, "explanation": "语义：“纷纷”表示许多人相继做某事，与“王老师”一人不合。"}, {"text": "首度", "is_correct": true, "explanation": "首度是副词，表示第一次，与“王老师”和“带学生去山里上课”搭配，符合句意。"}, {"text": "齐声", "is_correct": false, "explanation": "语义：“齐声”指众人同时发声，与“王老师”带学生去上课的动作不合。"}, {"text": "互相", "is_correct": false, "explanation": "语义：“互相”需要两个以上的主体彼此动作，与“王老师”一人不合。"}], "explanations": {"纷纷": "语义：“纷纷”表示许多人相继做某事，与“王老师”一人不合。", "首度": "首度是副词，表示第一次，与“王老师”和“带学生去山里上课”搭配，符合句意。", "齐声": "语义：“齐声”指众人同时发声，与“王老师”带学生去上课的动作不合。", "互相": "语义：“互相”需要两个以上的主体彼此动作，与“王老师”一人不合。"}, "sentence_index": 6, "correct_answer": "首度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中国队今年又首度获得冠军。", "explanation": "这里表示重复获得，应该用〈再次〉。首度只说明第一次，与重复获得的意思相矛盾。"}, {"text": "他们首度见面三次。", "explanation": "这里表示多次见面，应该用〈多次〉。首度只说明第一次，不能用于多次的情况。"}, {"text": "这个节目经常首度请客人。", "explanation": "这里表示经常发生，应该用〈屡次〉。首度只说明第一次，与反复发生的意思相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
