INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91741, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "绿是草和树叶的颜色。", "primary_collocate": null, "pronunciation": "lǜ", "ipa": "ly˥˩", "syllable_count": 1, "sentences": [{"text": "春天来了，草都绿了。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶是绿的。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片草地真绿。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的树又高又绿。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，山上的树叶更绿了。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，那棵树多绿啊！", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢绿的树叶。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的草绿得很好看。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些叶子很绿，也很大。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的山，绿得像一幅画。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "綠", "label": "繁体"}, {"form": "绿绿的", "label": "重叠"}], "register": "中性", "sense_fingerprint": "草、树叶等植物呈现的颜色，形容植物颜色绿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f8102f3-2b9d-4b5e-9770-fb2903a345ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91741, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "绿", "is_correct": true, "explanation": "正确答案：草和树叶的颜色。"}, {"text": "旅", "is_correct": false, "explanation": "lǚ（第三声）与 lǜ（第四声）声调不同，意思是旅行。"}, {"text": "驴", "is_correct": false, "explanation": "lǘ（第二声）与 lǜ（第四声）声调不同，意思是驴子。"}, {"text": "路", "is_correct": false, "explanation": "lù 与 lǜ 韵母不同（u 与 ü），意思是道路。"}, {"text": "力", "is_correct": false, "explanation": "lì 与 lǜ 韵母不同（i 与 ü），意思是力量。"}], "explanations": {"绿": "正确答案：草和树叶的颜色。", "旅": "lǚ（第三声）与 lǜ（第四声）声调不同，意思是旅行。", "驴": "lǘ（第二声）与 lǜ（第四声）声调不同，意思是驴子。", "路": "lù 与 lǜ 韵母不同（u 与 ü），意思是道路。", "力": "lì 与 lǜ 韵母不同（i 与 ü），意思是力量。"}, "sentence_index": null, "correct_answer": "绿"}, "level_3": {"options": [{"text": "绿", "is_correct": true, "explanation": "正确：春天来了，草变成了绿色。"}, {"text": "红", "is_correct": false, "explanation": "语义：春天的草不会变红，红色多指秋天的叶子或花朵。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”说的是温度，不能用来说草的颜色。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”用于人或动物的体型，不能用来形容草。"}], "explanations": {"绿": "正确：春天来了，草变成了绿色。", "红": "语义：春天的草不会变红，红色多指秋天的叶子或花朵。", "冷": "语义：“冷”说的是温度，不能用来说草的颜色。", "胖": "体貌：“胖”用于人或动物的体型，不能用来形容草。"}, "sentence_index": 0, "correct_answer": "绿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个坏消息，他的脸都绿了。", "explanation": "这里“脸绿了”形容人因害怕或生气而脸色难看，不是草和树叶的颜色。"}, {"text": "前面是绿灯，我们可以过马路了。", "explanation": "这里“绿灯”是交通信号，表示可以通行，不是在形容植物的颜色。"}, {"text": "我们一起去绿化这座小山吧。", "explanation": "这里“绿化”是动词，意思是种树种草，不是形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91741, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "绿", "is_correct": true, "explanation": "正确答案：草和树叶的颜色。"}, {"text": "鹿", "is_correct": false, "explanation": "lù 与 lǜ 韵母不同（u 与 ü），意思是鹿。"}, {"text": "立", "is_correct": false, "explanation": "lì 与 lǜ 韵母不同（i 与 ü），意思是站立。"}, {"text": "铝", "is_correct": false, "explanation": "lǚ（第三声）与 lǜ（第四声）声调不同，意思是铝这种金属。"}], "explanations": {"绿": "正确答案：草和树叶的颜色。", "鹿": "lù 与 lǜ 韵母不同（u 与 ü），意思是鹿。", "立": "lì 与 lǜ 韵母不同（i 与 ü），意思是站立。", "铝": "lǚ（第三声）与 lǜ（第四声）声调不同，意思是铝这种金属。"}, "sentence_index": null, "correct_answer": "绿"}, "level_3": {"options": [{"text": "绿", "is_correct": true, "explanation": "正确：“绿”形容树叶的颜色，句中是喜欢绿色的树叶。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”形容速度，不能用来形容树叶。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”说距离，不能用来形容树叶。"}, {"text": "巍峨", "is_correct": false, "explanation": "语域：“巍峨”是高大雄伟的书面语，不用来形容树叶。"}], "explanations": {"绿": "正确：“绿”形容树叶的颜色，句中是喜欢绿色的树叶。", "快": "语义：“快”形容速度，不能用来形容树叶。", "远": "语义：“远”说距离，不能用来形容树叶。", "巍峨": "语域：“巍峨”是高大雄伟的书面语，不用来形容树叶。"}, "sentence_index": 6, "correct_answer": "绿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他气得脸都绿了。", "explanation": "这里“脸绿了”形容人生气时脸色难看，不是草和树叶的颜色。"}, {"text": "等绿灯亮了再走。", "explanation": "这里“绿灯”是交通信号，不是在形容植物的颜色。"}, {"text": "这条街两边都绿化得很好。", "explanation": "这里“绿化”是动词，指种植花草树木，不是形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91741, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片草地绿很好看。", "corrected_sentence": "这片草地绿得很好看。", "error_description": "“绿”后面要用“得”引出程度补语，少了“得”是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91741, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那片叶子是绿。", "corrected_sentence": "那片叶子是绿的。", "error_description": "用“是”说明事物的颜色时，“绿”后面要加“的”；只说“是绿”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
