INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91742, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "蓝和黄混合成的颜色，像草和树叶那样。", "primary_collocate": null, "pronunciation": "lǜ", "ipa": "ly˥˩", "syllable_count": 1, "sentences": [{"text": "蓝和黄放在一起会变成绿。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画画时，我用蓝和黄调出了绿。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个绿不够深，再加一点蓝。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最喜欢的颜色是绿。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红和绿放在一起很好看。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个绿太浅了，我想要深一点的。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄多一点，绿就会浅一点。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么调绿。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个绿是用蓝和黄调的。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调绿的时候，蓝不要放太多。", "target_word": "绿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "綠", "label": "繁体"}], "register": "中性", "sense_fingerprint": "蓝和黄调出来的颜色名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f8102f3-2b9d-4b5e-9770-fb2903a345ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91742, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "绿", "is_correct": true, "explanation": "正确答案：蓝和黄混合得到的颜色。"}, {"text": "旅", "is_correct": false, "explanation": "lǚ（第三声）与 lǜ（第四声）声调不同，意思是旅行。"}, {"text": "驴", "is_correct": false, "explanation": "lǘ（第二声）与 lǜ（第四声）声调不同，意思是驴子。"}, {"text": "路", "is_correct": false, "explanation": "lù 与 lǜ 韵母不同（u 与 ü），意思是道路。"}, {"text": "力", "is_correct": false, "explanation": "lì 与 lǜ 韵母不同（i 与 ü），意思是力量。"}], "explanations": {"绿": "正确答案：蓝和黄混合得到的颜色。", "旅": "lǚ（第三声）与 lǜ（第四声）声调不同，意思是旅行。", "驴": "lǘ（第二声）与 lǜ（第四声）声调不同，意思是驴子。", "路": "lù 与 lǜ 韵母不同（u 与 ü），意思是道路。", "力": "lì 与 lǜ 韵母不同（i 与 ü），意思是力量。"}, "sentence_index": null, "correct_answer": "绿"}, "level_3": {"options": [{"text": "绿", "is_correct": true, "explanation": "正确：蓝和黄混合会得到绿色，这里的“绿”指这种颜色。"}, {"text": "红", "is_correct": false, "explanation": "语义：蓝和黄混合不会得到红色。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“变成”后要接具体的颜色名，不能接“颜色”这个泛称。"}, {"text": "紫", "is_correct": false, "explanation": "语义：紫是红和蓝混合的结果，蓝和黄不会得到紫。"}], "explanations": {"绿": "正确：蓝和黄混合会得到绿色，这里的“绿”指这种颜色。", "红": "语义：蓝和黄混合不会得到红色。", "颜色": "搭配：“变成”后要接具体的颜色名，不能接“颜色”这个泛称。", "紫": "语义：紫是红和蓝混合的结果，蓝和黄不会得到紫。"}, "sentence_index": 0, "correct_answer": "绿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天来了，草都绿了。", "explanation": "这里“绿”是形容词，说草变成了绿色，不是指颜色的名称。"}, {"text": "他气得脸都绿了。", "explanation": "这里“脸绿了”形容人生气时脸色难看，不是指蓝和黄调成的颜色。"}, {"text": "等绿灯亮了再过马路。", "explanation": "这里“绿灯”是交通信号，不是指颜色的名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91742, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "绿", "is_correct": true, "explanation": "正确答案：蓝和黄混合得到的颜色。"}, {"text": "鹿", "is_correct": false, "explanation": "lù 与 lǜ 韵母不同（u 与 ü），意思是鹿。"}, {"text": "立", "is_correct": false, "explanation": "lì 与 lǜ 韵母不同（i 与 ü），意思是站立。"}, {"text": "铝", "is_correct": false, "explanation": "lǚ（第三声）与 lǜ（第四声）声调不同，意思是铝这种金属。"}], "explanations": {"绿": "正确答案：蓝和黄混合得到的颜色。", "鹿": "lù 与 lǜ 韵母不同（u 与 ü），意思是鹿。", "立": "lì 与 lǜ 韵母不同（i 与 ü），意思是站立。", "铝": "lǚ（第三声）与 lǜ（第四声）声调不同，意思是铝这种金属。"}, "sentence_index": null, "correct_answer": "绿"}, "level_3": {"options": [{"text": "绿", "is_correct": true, "explanation": "正确：黄多了，颜色会变浅，这里指的是绿色变浅。"}, {"text": "米饭", "is_correct": false, "explanation": "语义：米饭不是颜色，不会因为黄多而变浅。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是染料的颜色，不会因为黄多而变浅。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的身体特征，与颜色的深浅无关。"}], "explanations": {"绿": "正确：黄多了，颜色会变浅，这里指的是绿色变浅。", "米饭": "语义：米饭不是颜色，不会因为黄多而变浅。", "天空": "语义：天空不是染料的颜色，不会因为黄多而变浅。", "身高": "体貌：身高是人的身体特征，与颜色的深浅无关。"}, "sentence_index": 6, "correct_answer": "绿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在绿天下散步，心情很好。", "explanation": "这里应该用〈蓝〉。“蓝天”是固定说法，晴天的天空是蓝的，不能说“绿天”。"}, {"text": "他打开了一瓶绿酒，倒进杯里。", "explanation": "这里应该用〈红〉。“红酒”是固定说法，指葡萄酿的酒，绿不能这样搭配。"}, {"text": "屋顶上铺满了绿雪。", "explanation": "这里应该用〈白〉。雪是白色的，“白雪”是固定说法，绿不能用来形容雪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要一只更亮的绿。", "corrected_sentence": "我们要一种更亮的绿。", "error_description": "“绿”作颜色名词时，前面的量词应用“种”；用“只”是错的，因为“只”用于动物或单个器物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹最爱的颜色是很绿。", "corrected_sentence": "我妹妹最爱的颜色是绿。", "error_description": "这里“绿”是颜色的名称（名词），前面不能加“很”；加“很”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
