INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91743, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "马路是汽车走的大路。", "primary_collocate": null, "pronunciation": "mǎ lù", "ipa": "ma˨˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "请你走人行道，不要走在马路中间。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆红色的汽车停在马路旁边。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在修这条马路。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条马路又大又直。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑着自行车在马路上走。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上马路上的灯很亮。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车一辆接一辆地开上马路。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路太窄，大车过不去。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新马路修好以后，路上的车少多了。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坐在车里，看着马路两边的房子。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "大马路", "label": "复合"}], "register": "口语", "sense_fingerprint": "汽车行驶的大路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85b2443-ac17-43fe-8739-349acbe3fea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91743, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，人不能走在它的中间。"}, {"text": "马路", "is_correct": true, "explanation": "“马路”是汽车行驶的大路，行人不应走在中间，与“走人行道”的语境相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以行走的地面，不能说“走在天空中间”。"}, {"text": "鼻子", "is_correct": false, "explanation": "语义：鼻子是人的器官，不能说“走在鼻子中间”。"}], "explanations": {"冰箱": "语义：冰箱是家电，人不能走在它的中间。", "马路": "“马路”是汽车行驶的大路，行人不应走在中间，与“走人行道”的语境相符。", "天空": "语义：天空不是可以行走的地面，不能说“走在天空中间”。", "鼻子": "语义：鼻子是人的器官，不能说“走在鼻子中间”。"}, "sentence_index": 0, "correct_answer": "马路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小鱼在马路上游来游去。", "explanation": "这里应该用〈河〉。马路是汽车行驶的道路，鱼生活在水里，不能在马路上游。"}, {"text": "火车在马路上飞快地行驶。", "explanation": "这里应该用〈铁路〉。马路是汽车行驶的道路，火车要在铁路上行驶。"}, {"text": "货船在马路上慢慢地航行。", "explanation": "这里应该用〈河道〉。马路是陆地上汽车行驶的道路，货船在水上航行，不能说马路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91743, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海面", "is_correct": false, "explanation": "语义：汽车不能开上海面，海面不是道路。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，汽车不能开上书包。"}, {"text": "马路", "is_correct": true, "explanation": "“马路”是汽车行驶的道路，“开上马路”与语境相符。"}, {"text": "楼梯", "is_correct": false, "explanation": "搭配：“开上”指车辆驶上路面，不说开上楼梯。"}], "explanations": {"海面": "语义：汽车不能开上海面，海面不是道路。", "书包": "语义：书包是物品，汽车不能开上书包。", "马路": "“马路”是汽车行驶的道路，“开上马路”与语境相符。", "楼梯": "搭配：“开上”指车辆驶上路面，不说开上楼梯。"}, "sentence_index": 6, "correct_answer": "马路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在马路上种了一排西红柿。", "explanation": "这里应该用〈菜地〉。马路是供车辆和行人通行的道路，种菜要在菜地里进行。"}, {"text": "船长把大船停在马路上，等客人上船。", "explanation": "这里应该用〈码头〉。马路是汽车行驶的路，大船要停在码头。"}, {"text": "夏天我们常常在马路里游泳。", "explanation": "这里应该用〈游泳池〉。马路是汽车行驶的道路，游泳要在游泳池里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91743, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一辆马路穿过了小城。", "corrected_sentence": "一条马路穿过了小城。", "error_description": "量词错误：马路是长条形的道路，应说“一条马路”；“辆”用于车辆，不能用于马路。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91743, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在马路里骑着自行车。", "corrected_sentence": "他在马路上骑着自行车。", "error_description": "方位词错误：在马路上要用“上”，不能说“里”，应说“在马路上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
