INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91744, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市中供车辆和行人通行的宽阔道路。", "primary_collocate": null, "pronunciation": "mǎ lù", "ipa": "ma˨˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "过马路的时候要看红绿灯。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路上有很多汽车和行人。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口的马路很宽。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩不能一个人在马路上玩。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家就在马路对面。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在马路边等公共汽车。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路两边种着很多树。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，马路上都是水。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢地走过马路。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条马路下午特别堵。", "target_word": "马路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "大马路", "label": "复合"}], "register": "口语", "sense_fingerprint": "城市里车辆和行人都走的宽阔街道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85b2443-ac17-43fe-8739-349acbe3fea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海", "is_correct": false, "explanation": "语义：海上不设红绿灯，“过海”时不需要看红绿灯。"}, {"text": "马路", "is_correct": true, "explanation": "“马路”是供车辆和行人通行的道路，过马路要看红绿灯，与语境相符。"}, {"text": "楼梯", "is_correct": false, "explanation": "搭配：“过”一般不接“楼梯”，应说“上楼梯”或“下楼梯”。"}, {"text": "河", "is_correct": false, "explanation": "语义：河流不设红绿灯，“过河”与“看红绿灯”不相符。"}], "explanations": {"海": "语义：海上不设红绿灯，“过海”时不需要看红绿灯。", "马路": "“马路”是供车辆和行人通行的道路，过马路要看红绿灯，与语境相符。", "楼梯": "搭配：“过”一般不接“楼梯”，应说“上楼梯”或“下楼梯”。", "河": "语义：河流不设红绿灯，“过河”与“看红绿灯”不相符。"}, "sentence_index": 0, "correct_answer": "马路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地铁在马路上飞驰而过。", "explanation": "这里应该用〈铁路〉。马路供车辆和行人在地面通行，地铁在轨道上运行，不能说马路。"}, {"text": "我们坐船沿着马路去上海。", "explanation": "这里应该用〈河道〉。马路是陆地上供车辆和行人通行的道路，坐船要走水路，不能沿马路行驶。"}, {"text": "农民在马路上插秧。", "explanation": "这里应该用〈田〉。马路是供车辆和行人通行的城市道路，插秧要在田里进行，不能说马路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手", "is_correct": false, "explanation": "语义：手不是道路，手的两边不会种树。"}, {"text": "脸", "is_correct": false, "explanation": "语义：脸是人的面部，不是道路，两边不会种着树。"}, {"text": "马路", "is_correct": true, "explanation": "“马路”是道路，道路两边可以种树，与语境相符。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，不能在它的两边种树。"}], "explanations": {"手": "语义：手不是道路，手的两边不会种树。", "脸": "语义：脸是人的面部，不是道路，两边不会种着树。", "马路": "“马路”是道路，道路两边可以种树，与语境相符。", "书桌": "语义：书桌是家具，不能在它的两边种树。"}, "sentence_index": 6, "correct_answer": "马路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游船在马路上慢慢地行驶。", "explanation": "这里应该用〈河道〉。马路是陆地上供车辆和行人通行的道路，游船在水上航行，不能说马路。"}, {"text": "孩子们在马路上堆沙堡。", "explanation": "这里应该用〈沙滩〉。马路是供车辆和行人通行的城市道路，堆沙堡要在沙滩上进行。"}, {"text": "飞机在马路上滑行，准备起飞。", "explanation": "这里应该用〈跑道〉。马路供车辆和行人通行，飞机起飞要在跑道上滑行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座马路每天早上都很堵。", "corrected_sentence": "这条马路每天早上都很堵。", "error_description": "量词错误：马路是长条形的道路，应说“这条马路”；“座”用于桥、山、楼等大型固定建筑，不能用于马路。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "马路里停着很多车，很不方便。", "corrected_sentence": "马路上停着很多车，很不方便。", "error_description": "方位词错误：在马路这种路面上要用“上”，不能说“里”，应说“马路上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91745, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "松", "is_correct": true, "explanation": "反义词：紧指绑得牢、松不开，松指不紧、能松开，二者相对。"}, {"text": "快", "is_correct": false, "explanation": "与紧没有反义关系，快说的是速度，与绑得牢固无关。"}, {"text": "亮", "is_correct": false, "explanation": "与紧没有反义关系，亮说的是光线明暗，与绑的程度无关。"}, {"text": "甜", "is_correct": false, "explanation": "与紧没有反义关系，甜说的是味道，与绑的程度无关。"}], "correct_answer": "松", "explanations": {"松": "反义词：紧指绑得牢、松不开，松指不紧、能松开，二者相对。", "快": "与紧没有反义关系，快说的是速度，与绑得牢固无关。", "亮": "与紧没有反义关系，亮说的是光线明暗，与绑的程度无关。", "甜": "与紧没有反义关系，甜说的是味道，与绑的程度无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91745, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "松", "is_correct": true, "explanation": "反义词：紧指绑得牢、松不开，松指不紧、能松开，二者相对。"}, {"text": "高", "is_correct": false, "explanation": "与紧没有反义关系，高说的是高度，与绑的程度无关。"}, {"text": "厚", "is_correct": false, "explanation": "与紧没有反义关系，厚说的是厚度，与绑的程度无关。"}, {"text": "冷", "is_correct": false, "explanation": "与紧没有反义关系，冷说的是温度，与绑的程度无关。"}], "correct_answer": "松", "explanations": {"松": "反义词：紧指绑得牢、松不开，松指不紧、能松开，二者相对。", "高": "与紧没有反义关系，高说的是高度，与绑的程度无关。", "厚": "与紧没有反义关系，厚说的是厚度，与绑的程度无关。", "冷": "与紧没有反义关系，冷说的是温度，与绑的程度无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91745, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "紧是绑得很牢，很用力，松不开。", "primary_collocate": null, "pronunciation": "jǐn", "ipa": "tɕin˨˩˦", "syllable_count": 1, "sentences": [{"text": "这根绳子绑得很紧。", "target_word": "紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把鞋带系得太紧了。", "target_word": "紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶盖拧得很紧，我打不开。", "target_word": "紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面很冷，门关得很紧。", "target_word": "紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袋子口扎得紧，东西不会掉出来。", "target_word": "紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把我的围巾围得很紧。", "target_word": "紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个螺丝太紧了，我拧不动。", "target_word": "紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李箱的带子绑得不够紧。", "target_word": "紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绳结打得很紧，解了很久。", "target_word": "紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的绳子拴得太紧，它不舒服。", "target_word": "紧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "紧紧", "label": "重叠"}], "register": "中性", "sense_fingerprint": "绳子、带子、瓶盖等绑得或拧得很牢，松不开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c68a36c9-e59c-427d-8e93-883fc38f78dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91745, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "紧", "is_correct": true, "explanation": "紧：绑得很牢，很用力，松不开。"}, {"text": "金", "is_correct": false, "explanation": "jīn（第一声）与 jǐn（第三声）声调不同，意思是金子。"}, {"text": "近", "is_correct": false, "explanation": "jìn（第四声）与 jǐn（第三声）声调不同，意思是距离短。"}, {"text": "进", "is_correct": false, "explanation": "jìn（第四声）与 jǐn（第三声）声调不同，意思是向里走。"}, {"text": "劲", "is_correct": false, "explanation": "jìn（第四声）与 jǐn（第三声）声调不同，意思是力气。"}], "explanations": {"紧": "紧：绑得很牢，很用力，松不开。", "金": "jīn（第一声）与 jǐn（第三声）声调不同，意思是金子。", "近": "jìn（第四声）与 jǐn（第三声）声调不同，意思是距离短。", "进": "jìn（第四声）与 jǐn（第三声）声调不同，意思是向里走。", "劲": "jìn（第四声）与 jǐn（第三声）声调不同，意思是力气。"}, "sentence_index": null, "correct_answer": "紧"}, "level_3": {"options": [{"text": "紧", "is_correct": true, "explanation": "紧：绑得很牢，松不开，与句意吻合。"}, {"text": "粗", "is_correct": false, "explanation": "语义：粗说的是粗细，不说绑得粗，与“绑得很紧”的意思不合。"}, {"text": "甜", "is_correct": false, "explanation": "语义：甜说的是味道，不能形容绳子绑的程度。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：矮说的是高度，不能描述绑的牢固程度。"}], "explanations": {"紧": "紧：绑得很牢，松不开，与句意吻合。", "粗": "语义：粗说的是粗细，不说绑得粗，与“绑得很紧”的意思不合。", "甜": "语义：甜说的是味道，不能形容绳子绑的程度。", "矮": "体貌：矮说的是高度，不能描述绑的牢固程度。"}, "sentence_index": 0, "correct_answer": "紧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把绳子绑得很紧，轻轻一拉就开了。", "explanation": "这里应该用〈松〉。紧指绑得牢、松不开，与“轻轻一拉就开了”矛盾。"}, {"text": "这个瓶盖拧得很紧，所以我一下就打开了。", "explanation": "这里应该用〈松〉。紧指拧得牢、打不开，与“所以一下就打开了”前后矛盾。"}, {"text": "围巾围得很紧，风一吹就掉了。", "explanation": "这里应该用〈松〉。紧指围得牢，与“风一吹就掉了”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紧", "is_correct": true, "explanation": "紧：绑得很牢，松不开，这里指螺丝拧得很牢、拧不动。"}, {"text": "远", "is_correct": false, "explanation": "语义：远说的是距离，与螺丝能不能拧动无关，句意不通。"}, {"text": "轻", "is_correct": false, "explanation": "搭配：“螺丝”不说轻重，“太轻”不能形容螺丝的松紧。"}, {"text": "黑", "is_correct": false, "explanation": "体貌：黑说的是颜色，与螺丝能不能拧动没有关系。"}], "explanations": {"紧": "紧：绑得很牢，松不开，这里指螺丝拧得很牢、拧不动。", "远": "语义：远说的是距离，与螺丝能不能拧动无关，句意不通。", "轻": "搭配：“螺丝”不说轻重，“太轻”不能形容螺丝的松紧。", "黑": "体貌：黑说的是颜色，与螺丝能不能拧动没有关系。"}, "sentence_index": 6, "correct_answer": "紧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双鞋的鞋带系得很紧，我一抬脚就掉了。", "explanation": "这里应该用〈松〉。紧指系得牢、不松，与“一抬脚就掉了”矛盾，应说“系得很松”。"}, {"text": "这个螺丝拧得很紧，所以我一拧就松了。", "explanation": "这里应该用〈松〉。紧指拧得牢，与“所以一拧就松了”的逻辑矛盾，应说〈松〉。"}, {"text": "我把行李箱的拉链拉得很紧，很快就拉开了。", "explanation": "这里应该用〈松〉。紧指拉得牢、不松，与“很快就拉开了”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把袋子的口扎很紧。", "corrected_sentence": "他把袋子的口扎得很紧。", "error_description": "“扎”后面接表示程度的补语时要用“得”，应说“扎得很紧”，不说“扎很紧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把行李箱的带子绑了紧。", "corrected_sentence": "我把行李箱的带子绑紧了。", "error_description": "结果补语“紧”要紧跟动词，“了”放在句末，应说“绑紧了”，不说“绑了紧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
