INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91747, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "黑历史是一个人不想让人知道的过去的事。", "primary_collocate": null, "pronunciation": "hēi lì shǐ", "ipa": "xei˥ li˥˩ ʂɻ̩˨˩˦", "syllable_count": 3, "sentences": [{"text": "他最怕别人提起自己的黑历史。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张旧照片是我的黑历史，别给人看。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁都有一点不想说的黑历史。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的黑历史都删掉了。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学聚会时，他的黑历史又让大家笑了很久。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候哭着要糖，成了我的黑历史。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别翻我的黑历史了，好不好？", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那段黑历史他从来不跟朋友说。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友知道我所有的黑历史。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个视频是他上学时的黑历史。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}], "register": "口语", "sense_fingerprint": "个人不想让别人知道的过去的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99fe3606-75b6-4d45-9eb3-6ab141772d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91747, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黑历史", "is_correct": true, "explanation": "正确：“黑历史”指不愿被人提起的过去，与“别人提起自己的”语义相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是个人想隐瞒、怕被人提起的往事，句意说不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是物品，不能作为怕被人提起的私人过去。"}, {"text": "饭碗", "is_correct": false, "explanation": "搭配：“提起”多用于话题或往事，不说“提起自己的饭碗”；“饭碗”指谋生的工作，不合句意。"}], "explanations": {"黑历史": "正确：“黑历史”指不愿被人提起的过去，与“别人提起自己的”语义相合。", "天气": "语义：“天气”不是个人想隐瞒、怕被人提起的往事，句意说不通。", "电脑": "语义：“电脑”是物品，不能作为怕被人提起的私人过去。", "饭碗": "搭配：“提起”多用于话题或往事，不说“提起自己的饭碗”；“饭碗”指谋生的工作，不合句意。"}, "sentence_index": 0, "correct_answer": "黑历史"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把黑历史当成一道数学题做了。", "explanation": "这里把“黑历史”当成了可以做的数学题。“黑历史”指个人不愿被人提起的过去，是经历，不是题目。"}, {"text": "他把黑历史当作礼物送给了朋友。", "explanation": "这里把“黑历史”当成了可以送人的东西。“黑历史”指个人不愿被人提起的过去，是经历，不是物品，不能拿来送人。"}, {"text": "我们为他的黑历史感到骄傲。", "explanation": "这里把“黑历史”当成了值得自豪的成就。“黑历史”指不光彩、不愿被人提起的过去，不是值得自豪的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91747, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黑历史", "is_correct": true, "explanation": "正确：“黑历史”是不想让人知道的过去，符合“你别翻我的”所指的私人往事。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“翻”的对象多是本子、抽屉等，不说“翻我的体重”。"}, {"text": "天花板", "is_correct": false, "explanation": "语义：“天花板”是房屋结构，不是可以被“翻”的私人往事。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“饭量”指吃饭的份量，不能用“翻”，句子读来不通。"}], "explanations": {"黑历史": "正确：“黑历史”是不想让人知道的过去，符合“你别翻我的”所指的私人往事。", "体重": "搭配：“翻”的对象多是本子、抽屉等，不说“翻我的体重”。", "天花板": "语义：“天花板”是房屋结构，不是可以被“翻”的私人往事。", "饭量": "搭配：“饭量”指吃饭的份量，不能用“翻”，句子读来不通。"}, "sentence_index": 6, "correct_answer": "黑历史"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次考试拿了一个黑历史的高分。", "explanation": "这里把“黑历史”当成了分数。“黑历史”指不光彩的过去，不是可以用来计分的数字，应用〈成绩〉之类的说法。"}, {"text": "他用黑历史煮了一锅粥。", "explanation": "这里把“黑历史”当成了可以下锅的食材。“黑历史”指不光彩的过去，是经历，不能入菜。"}, {"text": "他被选为班级的黑历史班长。", "explanation": "这里把“黑历史”当成了职务名称。“黑历史”指不光彩的过去，不能用作职务名称，应用〈班级干部〉之类的称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他翻出了一把黑历史，大家都笑了。", "corrected_sentence": "他翻出了一段黑历史，大家都笑了。", "error_description": "量词错误：“黑历史”应配量词“段”，“把”用于有柄的器具。此处应改为“一段黑历史”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "聚会上有人提起他的一把黑历史，大家都不说话。", "corrected_sentence": "聚会上有人提起他的一段黑历史，大家都不说话。", "error_description": "量词错误：“黑历史”应配量词“段”，“把”用于有柄的器具。此处应改为“一段黑历史”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
