INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91748, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指个人过去不光彩、不愿被人提起的经历。", "primary_collocate": null, "pronunciation": "hēi lì shǐ", "ipa": "xei˥ li˥˩ ʂɻ̩˨˩˦", "syllable_count": 3, "sentences": [{"text": "他有一段黑历史，从来不愿再提。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的黑历史让公司很难堪。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有人挖出了明星的黑历史。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考试作弊的事成了黑历史。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说：“那是我的黑历史，别问了。”", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的黑历史都不一样。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想忘记那段黑历史，重新开始。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个歌手的黑历史很多，粉丝越来越少。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有黑历史的人，找工作有时很难。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都不提他的黑历史，免得他难过。", "target_word": "黑历史", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}], "register": "口语", "sense_fingerprint": "个人过去不光彩、不愿提起的经历", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99fe3606-75b6-4d45-9eb3-6ab141772d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91748, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黑历史", "is_correct": true, "explanation": "正确：“黑历史”指个人过去不光彩、不愿再提的经历，与“从来不愿再提”相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是个人不愿再提的过去经历，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“段”不用于“窗户”，且窗户不是可以“不愿再提”的经历。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“段”不用于“饭量”，饭量也不是不愿再提的往事。"}], "explanations": {"黑历史": "正确：“黑历史”指个人过去不光彩、不愿再提的经历，与“从来不愿再提”相合。", "天气": "语义：“天气”不是个人不愿再提的过去经历，句意不通。", "窗户": "搭配：“段”不用于“窗户”，且窗户不是可以“不愿再提”的经历。", "饭量": "搭配：“段”不用于“饭量”，饭量也不是不愿再提的往事。"}, "sentence_index": 0, "correct_answer": "黑历史"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们正在给黑历史盖被子。", "explanation": "这里把“黑历史”当成了有生命的东西，可以盖被子。“黑历史”指不光彩的过去，是经历，不能盖被子。"}, {"text": "他把黑历史拿到市场上去卖，换了一些钱。", "explanation": "这里把“黑历史”当成了可以出售的商品。“黑历史”是不愿被人提起的过去，不是货物，不能拿去卖。"}, {"text": "同学们都夸他的黑历史很光荣。", "explanation": "这里把“黑历史”当成了值得称赞的事。“黑历史”指不光彩的过去，不能用来表示值得称赞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黑历史", "is_correct": true, "explanation": "正确：“黑历史”是要“忘记”的过去经历，与“想忘记那段”相合。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是开锁的工具，不能作为要“忘记”的过去经历。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“课本”不用量词“段”，“那段课本”不通；课本也不是要忘掉以便重新开始的往事。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：“脚印”是路上留下的痕迹，不是需要忘记的过去经历。"}], "explanations": {"黑历史": "正确：“黑历史”是要“忘记”的过去经历，与“想忘记那段”相合。", "钥匙": "语义：“钥匙”是开锁的工具，不能作为要“忘记”的过去经历。", "课本": "搭配：“课本”不用量词“段”，“那段课本”不通；课本也不是要忘掉以便重新开始的往事。", "脚印": "语义：“脚印”是路上留下的痕迹，不是需要忘记的过去经历。"}, "sentence_index": 6, "correct_answer": "黑历史"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的黑历史获得了全校的奖学金。", "explanation": "这里把“黑历史”当成了可以获得的奖项。“黑历史”指不光彩的过去，不能用来获得奖学金。"}, {"text": "他把黑历史当作奖品送给了朋友。", "explanation": "这里把“黑历史”当成了值得送人的礼物。“黑历史”指不光彩的过去，不是可以送人的东西。"}, {"text": "他中午就吃了黑历史当午饭。", "explanation": "这里把“黑历史”当成了食物。“黑历史”指不光彩的过去，不是可以食用的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小时候他偷过邻居的花，那把黑历史他一直藏着。", "corrected_sentence": "小时候他偷过邻居的花，那段黑历史他一直藏着。", "error_description": "量词错误：“黑历史”应配量词“段”，“把”用于有柄的器具。此处应改为“那段黑历史”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老同学见面时，谁也不会提起他那把黑历史。", "corrected_sentence": "老同学见面时，谁也不会提起他那段黑历史。", "error_description": "量词错误：“黑历史”应配量词“段”，“把”用于有柄的器具。此处应改为“那段黑历史”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
