INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91751, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "一则是说一条消息或一个小故事。", "primary_collocate": null, "pronunciation": "yì zé", "ipa": "i˥˩ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "报纸上有一则很短的消息。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了一则小故事。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上看到一则新闻。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在播一则广告。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸讲了一则有意思的笑话。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里有一则关于小猫的故事。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一则寻人启事。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上贴着一则通知。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读到一则关于老人的小故事。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上弹出一则新消息。", "target_word": "一则", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一則", "label": "繁体"}], "register": "书面", "sense_fingerprint": "量词：一条消息或一个小故事，如新闻、笑话、广告", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6fc0c8a-a2f4-4258-9b79-7225f30965f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91751, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一则", "is_correct": true, "explanation": "一则：量词，用于一条消息，与“很短的消息”搭配。"}, {"text": "一首", "is_correct": false, "explanation": "搭配：“首”用于诗词、歌曲，不能说“一首消息”。"}, {"text": "一幅", "is_correct": false, "explanation": "语义：“幅”用于画作、地图等平面图像，与消息不符。"}, {"text": "一座", "is_correct": false, "explanation": "语义：“座”用于山、桥、建筑等大型固定物，不能量消息。"}], "explanations": {"一则": "一则：量词，用于一条消息，与“很短的消息”搭配。", "一首": "搭配：“首”用于诗词、歌曲，不能说“一首消息”。", "一幅": "语义：“幅”用于画作、地图等平面图像，与消息不符。", "一座": "语义：“座”用于山、桥、建筑等大型固定物，不能量消息。"}, "sentence_index": 0, "correct_answer": "一则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她买了一则裙子。", "explanation": "这里应该用〈条〉。则用于消息、通知、故事等文字内容，裙子这类物件要用〈条〉。"}, {"text": "他发表了一则论文。", "explanation": "这里应该用〈篇〉。论文要用“篇”，“则”只用于消息、通知等短文字。"}, {"text": "他吃了一则面包。", "explanation": "这里应该用〈块〉。则用于消息、通知、故事等文字内容，面包要用〈块〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一则", "is_correct": true, "explanation": "一则：量词，用于一条寻人启事，与“寻人启事”搭配。"}, {"text": "一束", "is_correct": false, "explanation": "语义：“束”用于花、草等成把的东西，不能量寻人启事。"}, {"text": "一棵", "is_correct": false, "explanation": "搭配：“棵”用于树、菜等植物，不能说“一棵启事”。"}, {"text": "一台", "is_correct": false, "explanation": "语义：“台”用于机器、电器等，与启事无关。"}], "explanations": {"一则": "一则：量词，用于一条寻人启事，与“寻人启事”搭配。", "一束": "语义：“束”用于花、草等成把的东西，不能量寻人启事。", "一棵": "搭配：“棵”用于树、菜等植物，不能说“一棵启事”。", "一台": "语义：“台”用于机器、电器等，与启事无关。"}, "sentence_index": 6, "correct_answer": "一则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上挂着一则画。", "explanation": "这里应该用〈幅〉。画作要用“幅”，“则”只用于消息、通知等文字内容。"}, {"text": "河上有一则桥。", "explanation": "这里应该用〈座〉。桥梁等大型建筑要用“座”，“则”不能量桥。"}, {"text": "院子里种了一则树。", "explanation": "这里应该用〈棵〉。树要用“棵”，“则”不能量树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在手机上看到一则的新闻。", "corrected_sentence": "我昨天在手机上看到一则新闻。", "error_description": "错误形式：一则的新闻；正确形式：一则新闻。“一则”作数量定语时后面不加“的”，应直接接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的手机突然收到一则朋友写的长信。", "corrected_sentence": "我的手机突然收到一封朋友写的长信。", "error_description": "量词搭配错误：“信”应用量词“封”，不能用“则”。应为“一封朋友写的长信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
