INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91756, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某地点上方的天空。", "primary_collocate": null, "pronunciation": "shàng kōng", "ipa": "ʂɑŋ˥˩ kʰʊŋ˥˥", "syllable_count": 2, "sentences": [{"text": "一架飞机从城市上空飞过。", "target_word": "上空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟在湖的上空飞来飞去。", "target_word": "上空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山的上空有很多云。", "target_word": "上空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校上空出现了一道彩虹。", "target_word": "上空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，烟花在广场上空绽放了。", "target_word": "上空", "complexity_tier": "T3", "furigana": "wǎn shang yān huā zài guǎng chǎng shàng kōng zhàn fàng le", "sentence_source": "generated"}, {"text": "夜里，城市上空看不见星星。", "target_word": "上空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气不好，机场上空全是雾。", "target_word": "上空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的上空飞着几只海鸥。", "target_word": "上空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳升起来了，村子上空很亮。", "target_word": "上空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，小镇上空出现了月亮。", "target_word": "上空", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词“上空”：某个地点上方的天空，常放在地点词后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e595aba8-a327-4dfa-933f-cb10e384922d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91756, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上空", "is_correct": true, "explanation": "“城市上空”指城市上方的天空，与“从……飞过”搭配，符合语境。"}, {"text": "底下", "is_correct": false, "explanation": "语义：“城市底下”指地面以下，飞机不会从地下飞过。"}, {"text": "海底", "is_correct": false, "explanation": "语义：“海底”在水下，飞机不能从海底飞过。"}, {"text": "隧道", "is_correct": false, "explanation": "搭配：“隧道”指穿越山体或地下的通道，不能说“从城市隧道飞过”。"}], "explanations": {"上空": "“城市上空”指城市上方的天空，与“从……飞过”搭配，符合语境。", "底下": "语义：“城市底下”指地面以下，飞机不会从地下飞过。", "海底": "语义：“海底”在水下，飞机不能从海底飞过。", "隧道": "搭配：“隧道”指穿越山体或地下的通道，不能说“从城市隧道飞过”。"}, "sentence_index": 0, "correct_answer": "上空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猫蹲在上空。", "explanation": "这里应该用〈窗台上〉。“上空”指某地点上方的天空，不能用来指窗台这样的平面。"}, {"text": "他住在上空，每天很安静。", "explanation": "这里应该用〈楼上〉。“上空”指天空，不指建筑物的楼层。"}, {"text": "他把书放在上空。", "explanation": "这里应该用〈桌子上〉。“上空”是天空的位置，不能用来放东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上空", "is_correct": true, "explanation": "“机场上空”指机场上方的天空，雾可以笼罩在那里，符合语境。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是室内场所，“机场教室全是雾”与“天气不好”的户外语境不符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房里的雾多是炊烟，与“天气不好”的户外语境不符。"}, {"text": "口袋", "is_correct": false, "explanation": "搭配：“机场口袋”不成立，“口袋”不能用作机场的方位或范围。"}], "explanations": {"上空": "“机场上空”指机场上方的天空，雾可以笼罩在那里，符合语境。", "教室": "语义：教室是室内场所，“机场教室全是雾”与“天气不好”的户外语境不符。", "厨房": "语义：厨房里的雾多是炊烟，与“天气不好”的户外语境不符。", "口袋": "搭配：“机场口袋”不成立，“口袋”不能用作机场的方位或范围。"}, "sentence_index": 6, "correct_answer": "上空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这个问题的上空很深。", "explanation": "这里应该用〈认识〉。“上空”只指具体地点上方的天空，不能用于抽象的看法或理解。"}, {"text": "公司的上空决定了新的政策。", "explanation": "这里应该用〈上层〉。“上空”指天空，不指组织中的管理层。"}, {"text": "他今天穿了一件上空。", "explanation": "这里应该用〈上衣〉。“上空”是天空，不是衣服，两词都以“上”开头，容易混淆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一群大雁村子上空飞过。", "corrected_sentence": "一群大雁从村子上空飞过。", "error_description": "错误形式：“一群大雁村子上空飞过”；正确形式：“一群大雁从村子上空飞过”。缺少介词“从”，表示路线的地点要用介词引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里，小镇里上空飘着一层薄雾。", "corrected_sentence": "夜里，小镇上空飘着一层薄雾。", "error_description": "错误：“小镇里上空”；正确：“小镇上空”。“上空”本身已经表示方位，前面不能再加“里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
