INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91757, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91757, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "着呢是放在句子最后，让话更有劲，说明很多。", "primary_collocate": null, "pronunciation": "zhe ne", "ipa": "ʈʂə nə", "syllable_count": 2, "sentences": [{"text": "离学校还远着呢，走路要一个小时。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别急，时间还多着呢。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖深着呢，小孩不能下去。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的力气大着呢，一个人能搬桌子。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的冬天冷着呢，要多穿衣服。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别看他小，懂的事多着呢。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗汤烫着呢，小心点。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的路长着呢，慢慢走吧。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河宽着呢，船过去要十分钟。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的院子大着呢，能种很多菜。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "接在形容词后，强调程度深、数量多、距离远等实际情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c68a36c9-e59c-427d-8e93-883fc38f78dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91757, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "着呢", "is_correct": true, "explanation": "“着呢”放在句末，强调距离远，符合“离学校还远”的意思。"}, {"text": "了", "is_correct": false, "explanation": "搭配：“还”表示尚未达到，与表示变化或完成的“了”搭配不通。"}, {"text": "吗", "is_correct": false, "explanation": "语义：加“吗”变成疑问句，与后面“走路要一个小时”的陈述不符。"}, {"text": "得", "is_correct": false, "explanation": "语法：句末的「得」不能单独作语气词，「还远得」后需接补语，句子不完整。"}], "explanations": {"着呢": "“着呢”放在句末，强调距离远，符合“离学校还远”的意思。", "了": "搭配：“还”表示尚未达到，与表示变化或完成的“了”搭配不通。", "吗": "语义：加“吗”变成疑问句，与后面“走路要一个小时”的陈述不符。", "得": "语法：句末的「得」不能单独作语气词，「还远得」后需接补语，句子不完整。"}, "sentence_index": 0, "correct_answer": "着呢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个数字是偶数着呢，我一看就知道。", "explanation": "语义：“着呢”表示程度深，与“很”一样修饰可以分程度的形容词；“偶数”没有程度之分，不能用“着呢”来强调。"}, {"text": "他是中国人着呢，我们都知道。", "explanation": "语义：“着呢”表示程度深，不能用在“中国人”这类表示身份、没有程度差别的名词后面。"}, {"text": "他昨天买了三本书着呢，很多人都看见了。", "explanation": "语义：“着呢”表示程度深，不能用在已经完成的动作和具体数量后面；表示数量多应说“买了很多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91757, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着呢", "is_correct": true, "explanation": "“着呢”放在句末，强调程度深，符合“汤烫”的意思。"}, {"text": "得", "is_correct": false, "explanation": "语法：「烫得」后需接补语，「得」不能单独放在句末作语气词，句子不完整。"}, {"text": "很", "is_correct": false, "explanation": "语法：「很」是副词，须放在形容词前，不能跟在「烫」之后作句末成分，句子不成立。"}, {"text": "极", "is_correct": false, "explanation": "语法：「极」须与「了」连用才能作补语，单独放在「烫」之后句子不完整。"}], "explanations": {"着呢": "“着呢”放在句末，强调程度深，符合“汤烫”的意思。", "得": "语法：「烫得」后需接补语，「得」不能单独放在句末作语气词，句子不完整。", "很": "语法：「很」是副词，须放在形容词前，不能跟在「烫」之后作句末成分，句子不成立。", "极": "语法：「极」须与「了」连用才能作补语，单独放在「烫」之后句子不完整。"}, "sentence_index": 6, "correct_answer": "着呢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的人都是老师着呢，不用担心。", "explanation": "语义：“着呢”表示程度深，不能用在“老师”这类表示身份的名词后面；想说明数量多，应说“老师很多”。"}, {"text": "这张桌子是铁的着呢，搬不动。", "explanation": "语义：“着呢”表示程度深，“铁的”表示材料，没有程度之分，不能用“着呢”来强调。"}, {"text": "这封信是昨天写的着呢。", "explanation": "语义：“着呢”表示程度深，不能用在“昨天写的”这种表示时间的短语后面；表示程度应说“写得很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路长了着呢，走起来要一会儿。", "corrected_sentence": "这条路长着呢，走起来要一会儿。", "error_description": "“着呢”前面不能加“了”，形容词后直接说“长着呢”，表示路程远；多加“了”后句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这口井深得着呢，别靠近。", "corrected_sentence": "这口井深着呢，别靠近。", "error_description": "“深”和“着呢”之间不能加“得”，应说“深着呢”，不说“深得着呢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
