INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91758, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91758, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词，用于句末，表示程度深，带有夸张语气。", "primary_collocate": null, "pronunciation": "zhe ne", "ipa": "ʈʂə nə", "syllable_count": 2, "sentences": [{"text": "你别小看他，他厉害着呢！", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜贵着呢，我可不常来。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的脾气大着呢，你别惹她。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的作业难着呢，我做了三个小时。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老师严着呢，上课不能说话。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面的太阳毒着呢，别出去。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的嘴甜着呢，大家都喜欢他。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子淘气着呢，一刻也不停。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的广州热着呢，你要有准备。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌好听着呢，你一定要听听。", "target_word": "着呢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "句末助词，带夸张语气，提醒对方别小看某人或某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c68a36c9-e59c-427d-8e93-883fc38f78dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "着呢", "is_correct": true, "explanation": "“着呢”用在句末，带夸张语气，提醒对方别小看，符合句意。"}, {"text": "而已", "is_correct": false, "explanation": "语义：“而已”表示轻描淡写，与“别小看他”的强调语气相反。"}, {"text": "罢了", "is_correct": false, "explanation": "语域：“罢了”带书面语色彩，与这句口语化的提醒不协调。"}, {"text": "得", "is_correct": false, "explanation": "语法：「厉害得」后需接补语，「得」不能单独作句末语气词，句子不完整。"}], "explanations": {"着呢": "“着呢”用在句末，带夸张语气，提醒对方别小看，符合句意。", "而已": "语义：“而已”表示轻描淡写，与“别小看他”的强调语气相反。", "罢了": "语域：“罢了”带书面语色彩，与这句口语化的提醒不协调。", "得": "语法：「厉害得」后需接补语，「得」不能单独作句末语气词，句子不完整。"}, "sentence_index": 0, "correct_answer": "着呢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子是厨房着呢，我们进去吧。", "explanation": "语义：“着呢”表示程度深，不能用在“厨房”这种表示场所、没有程度差别的名词后面。"}, {"text": "这把椅子是木头的着呢，很结实。", "explanation": "语义：“着呢”表示程度深，不能用在“木头的”这种表示材料的短语后面；说明结实应直接用“很结实”。"}, {"text": "他昨天就来过着呢，我们都见到了。", "explanation": "语义：“着呢”表示程度深，不能用在“来过”这种表示经历的动词后面；表示次数多应说“来过很多次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着呢", "is_correct": true, "explanation": "“着呢”用在句末，强调程度深，符合“他的嘴甜”的说法。"}, {"text": "得", "is_correct": false, "explanation": "语法：「甜得」后需接补语，「得」不能单独作句末语气词，句子不完整。"}, {"text": "很", "is_correct": false, "explanation": "语法：「很」须放在形容词前，不能跟在「甜」之后作句末成分，句子不成立。"}, {"text": "极", "is_correct": false, "explanation": "语法：「极」须与「了」连用才能作补语，单独放在「甜」之后句子不完整。"}], "explanations": {"着呢": "“着呢”用在句末，强调程度深，符合“他的嘴甜”的说法。", "得": "语法：「甜得」后需接补语，「得」不能单独作句末语气词，句子不完整。", "很": "语法：「很」须放在形容词前，不能跟在「甜」之后作句末成分，句子不成立。", "极": "语法：「极」须与「了」连用才能作补语，单独放在「甜」之后句子不完整。"}, "sentence_index": 6, "correct_answer": "着呢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的爸爸是医生着呢，你别担心。", "explanation": "语义：“着呢”表示程度深，不能用在“医生”这种表示职业、没有程度差别的名词后面。"}, {"text": "这首歌的作者是外国人着呢。", "explanation": "语义：“着呢”表示程度深，不能用在“外国人”这种表示国籍的名词后面。"}, {"text": "这个人是小学生着呢。", "explanation": "语义：“着呢”表示程度深，不能用在“小学生”这种表示身份的名词后面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的字写得漂亮着呢吗，你可以学学。", "corrected_sentence": "她的字写得漂亮着呢，你可以学学。", "error_description": "错误在句末。「着呢」本身已是句末成分，句末不能再加「吗」。应去掉「吗」，写成「她的字写得漂亮着呢，你可以学学」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑快着呢吗，你别小看它。", "corrected_sentence": "这台电脑快着呢，你别小看它。", "error_description": "“着呢”与“吗”不能同用，句末只能用一个语气词。应去掉“吗”，写成“快着呢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
