INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91759, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "下游是河水流去的那一头。", "primary_collocate": null, "pronunciation": "xià yóu", "ipa": "ɕja˥˩ jou˧˥", "syllable_count": 2, "sentences": [{"text": "河水从上游流到下游。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的下游很宽。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的船慢慢地漂向下游。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下游的水比上游的脏。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家住在河的下游。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下游的农民需要用河水种地。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，下游的水变多了。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鱼顺着水游到了下游。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的水会流到下游。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河的下游有一座小城。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下游地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "河水流向的那一头，与上游相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85b2443-ac17-43fe-8739-349acbe3fea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91759, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下游", "is_correct": true, "explanation": "正确。“下游”是河水流去的那一头，与“上游”相对，“从上游流到下游”句意成立。"}, {"text": "上游", "is_correct": false, "explanation": "语义：句中“从上游”已作起点，“流到上游”与河水的流动方向矛盾。"}, {"text": "源头", "is_correct": false, "explanation": "语义：源头是河流开始的地方，水不会“流到”源头。"}, {"text": "山", "is_correct": false, "explanation": "语义：河水流向的是河段，不会流到一座山上。"}], "explanations": {"下游": "正确。“下游”是河水流去的那一头，与“上游”相对，“从上游流到下游”句意成立。", "上游": "语义：句中“从上游”已作起点，“流到上游”与河水的流动方向矛盾。", "源头": "语义：源头是河流开始的地方，水不会“流到”源头。", "山": "语义：河水流向的是河段，不会流到一座山上。"}, "sentence_index": 0, "correct_answer": "下游"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨水在大山深处汇成小溪，这里是这条河的下游。", "explanation": "这里应该用〈上游〉。下游是河流流去的末段，雨水汇成小溪的地方属于上游。"}, {"text": "小河的下游在山顶上，水从那里流下来。", "explanation": "这里应该用〈源头〉。下游是河水流去的那一头，水开始流出的地方是源头。"}, {"text": "河水从下游流到上游。", "explanation": "方向错误：河水是从上游流向下游，句中把〈上游〉和〈下游〉说反了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下游", "is_correct": true, "explanation": "正确。“下游”指河流的末段，下雨后这里的水变多。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：“夏天”是时间，不能有“的水”，与河水的语境不合。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不是河段，不能说“太阳的水”。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：有水的地方要说“石头上的水”，“石头的水”不成搭配。"}], "explanations": {"下游": "正确。“下游”指河流的末段，下雨后这里的水变多。", "夏天": "语义：“夏天”是时间，不能有“的水”，与河水的语境不合。", "太阳": "语义：太阳不是河段，不能说“太阳的水”。", "石头": "搭配：有水的地方要说“石头上的水”，“石头的水”不成搭配。"}, "sentence_index": 6, "correct_answer": "下游"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河从一座高山的山谷里流出，那里正是它的下游。", "explanation": "这里应该用〈源头〉。下游是河流的末段，源头才是河流开始的地方，句子把起点说成了末段。"}, {"text": "河水一直不停地流向上游。", "explanation": "这里应该用〈下游〉。河水总是流向下游，不会流向上游。"}, {"text": "我们逆着水流划船，一直划到了下游。", "explanation": "这里应该用〈上游〉。逆着水流走是往上游去，顺着水才到下游。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们逆着水流往上划，一直划到了下游。", "corrected_sentence": "我们逆着水流往上划，一直划到了上游。", "error_description": "词义错误：逆着水流往上划，到的是河水流来的那一头，应说“上游”，不能说“下游”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把污水排了到下游。", "corrected_sentence": "工人把污水排到了下游。", "error_description": "语序错误：结果补语“到”后面要带“了”，应说“排到了下游”，不能说“排了到下游”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
