INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91760, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91760, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "河流接近出口的一段。", "primary_collocate": null, "pronunciation": "xià yóu", "ipa": "ɕja˥˩ jou˧˥", "syllable_count": 2, "sentences": [{"text": "长江下游的城市非常热闹。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河流的下游常常很平。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的下游快要到海边了。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下游的河面比上游宽得多。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄河下游有很多农田。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船去了河的下游看海。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下游一带夏天常常下大雨。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水到了下游，流得慢多了。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥在河的下游，离海不远。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷年轻时在长江下游工作。", "target_word": "下游", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下游地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "河流靠近出海口或出口的一段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85b2443-ac17-43fe-8739-349acbe3fea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下游", "is_correct": true, "explanation": "正确。“下游”指河流接近出口的一段，长江下游有许多大城市。"}, {"text": "源头", "is_correct": false, "explanation": "语义：源头在高处，人烟稀少，与“热闹的城市”不符。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“长江大海”不成修饰关系，长江流入大海，不能作地区定语。"}, {"text": "山村", "is_correct": false, "explanation": "语义：山村不是城市，与“城市非常热闹”冲突。"}], "explanations": {"下游": "正确。“下游”指河流接近出口的一段，长江下游有许多大城市。", "源头": "语义：源头在高处，人烟稀少，与“热闹的城市”不符。", "大海": "搭配：“长江大海”不成修饰关系，长江流入大海，不能作地区定语。", "山村": "语义：山村不是城市，与“城市非常热闹”冲突。"}, "sentence_index": 0, "correct_answer": "下游"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨水在高山的源头汇成小溪，这一带就是这条河的下游。", "explanation": "这里应该用〈上游〉。下游是河流接近出口的一段，高山源头汇水处属于上游。"}, {"text": "长江的下游在高高的雪山上。", "explanation": "这里应该用〈源头〉。下游是河流接近出口的一段，雪山上是河流的源头。"}, {"text": "河流的下游离大海最远。", "explanation": "这里应该用〈上游〉。下游接近出海口，离大海最远的是上游。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下游", "is_correct": true, "explanation": "正确。“下游一带”指河流接近出海口的地区，夏天多雨。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠少雨，与“夏天常常下大雨”冲突。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底不会下雨，与句意矛盾。"}, {"text": "月球", "is_correct": false, "explanation": "语义：月球上没有降水，“月球一带夏天常常下大雨”与句意矛盾。"}], "explanations": {"下游": "正确。“下游一带”指河流接近出海口的地区，夏天多雨。", "沙漠": "语义：沙漠少雨，与“夏天常常下大雨”冲突。", "海底": "语义：海底不会下雨，与句意矛盾。", "月球": "语义：月球上没有降水，“月球一带夏天常常下大雨”与句意矛盾。"}, "sentence_index": 6, "correct_answer": "下游"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河水从下游流向高山。", "explanation": "方向错误：河水从山上的上游流向接近出口的下游，不会从下游流向高山。"}, {"text": "小溪刚从山里流出来，这里就是它的下游。", "explanation": "这里应该用〈上游〉。刚从山里流出的一段是上游，下游接近出口。"}, {"text": "我们从海口坐船逆水而上，到了山里的下游。", "explanation": "这里应该用〈上游〉。离海口越远、越往山里是上游，下游接近出口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长江下游的小村子离大海最远。", "corrected_sentence": "长江上游的小村子离大海最远。", "error_description": "词义错误：下游是河流接近出口的一段，离大海近；离大海最远的是上游。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们长江下游建了一座码头。", "corrected_sentence": "工人们在长江下游建了一座码头。", "error_description": "介词缺失：表示处所时动词前要加“在”，应说“在长江下游建了一座码头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
