INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91762, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走人是辞职或被辞退，离开工作岗位。", "primary_collocate": null, "pronunciation": "zǒu rén", "ipa": "tsou˨˩˦ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他不想干了，决定明天就走人。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做不好这个工作就得走人。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理对他说：“不行就走人！”", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王和老板吵了一架，当场走人。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不要他了，让他月底走人。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作太累，我准备辞职走人。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三次迟到，只好卷铺盖走人。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工资这么低，我干脆走人算了。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "犯了这么大的错，他只能走人。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她受不了老板，打算下个月走人。", "target_word": "走人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "走人：辞职或被要求离开工作岗位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1766c185-9168-436d-834a-7e1714ef858c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走人", "is_correct": true, "explanation": "正确。“他不想干了，决定明天就走人”表示辞职，与语境相符。"}, {"text": "升职", "is_correct": false, "explanation": "语义：“不想干了”之后说“升职”，与辞职的语境相反。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“不想干了”之后说“吃饭”，与辞职的语境无关。"}, {"text": "涨工资", "is_correct": false, "explanation": "语义：“不想干了”之后说“涨工资”，与辞职的语境相反。"}], "explanations": {"走人": "正确。“他不想干了，决定明天就走人”表示辞职，与语境相符。", "升职": "语义：“不想干了”之后说“升职”，与辞职的语境相反。", "吃饭": "语义：“不想干了”之后说“吃饭”，与辞职的语境无关。", "涨工资": "语义：“不想干了”之后说“涨工资”，与辞职的语境相反。"}, "sentence_index": 0, "correct_answer": "走人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫下个月就辞职走人。", "explanation": "“辞职走人”只能指有工作的人，猫不能辞职，这里用错了对象。"}, {"text": "这个软件下个月就走人了。", "explanation": "“走人”指人辞职或离开，软件不能走人，这里用错了对象。"}, {"text": "这份合同当场走人。", "explanation": "“走人”只用于人，不能用于合同，用于物品是用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走人", "is_correct": true, "explanation": "正确。“他三次迟到，只好卷铺盖走人”表示被迫辞职，与语境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“卷铺盖”是离开或被辞退时的动作，与“睡觉”的意思冲突。"}, {"text": "加班", "is_correct": false, "explanation": "搭配：“卷铺盖”不与“加班”搭配，“卷铺盖加班”不成立。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“三次迟到，只好卷铺盖吃饭”与被迫离开的语境冲突，句子不合理。"}], "explanations": {"走人": "正确。“他三次迟到，只好卷铺盖走人”表示被迫辞职，与语境相符。", "睡觉": "语义：“卷铺盖”是离开或被辞退时的动作，与“睡觉”的意思冲突。", "加班": "搭配：“卷铺盖”不与“加班”搭配，“卷铺盖加班”不成立。", "吃饭": "语义：“三次迟到，只好卷铺盖吃饭”与被迫离开的语境冲突，句子不合理。"}, "sentence_index": 6, "correct_answer": "走人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的小狗受不了老板，打算下个月走人。", "explanation": "“走人”只用于人，小狗不能用“走人”，这里用错了对象。"}, {"text": "这台复印机下个月就走人了。", "explanation": "“走人”指人辞职，复印机不能辞职走人，这里用错了对象。"}, {"text": "这座老房子下个月就走人了。", "explanation": "“走人”用于人辞职或离开，房子不能走人，这里用错了对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份工作太累，我下个月就走人过。", "corrected_sentence": "这份工作太累，我下个月就走人了。", "error_description": "错误：“走人”表示辞职或离开，将来或完成的语气要用“了”，这里误用“过”，“走人过”不通。正确：“走人了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他三次迟到，只能卷铺盖走人着。", "corrected_sentence": "他三次迟到，只能卷铺盖走人。", "error_description": "错误：“走人”是一个整体，句末不能加“着”表示持续，应直接说“走人”。正确：“只能卷铺盖走人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91764, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
