INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91764, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "认作儿子而无血缘关系的男孩。", "primary_collocate": null, "pronunciation": "gān ér zi", "ipa": "kan˥ ɚ˧˥ tsɹ̩", "syllable_count": 3, "sentences": [{"text": "他们夫妻没有孩子，就收了一个干儿子。", "target_word": "干儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明拜了王师傅做干爸，成了他的干儿子。", "target_word": "干儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干儿子和干爸之间没有血缘关系。", "target_word": "干儿子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老李把干儿子当成亲生儿子一样养大。", "target_word": "干儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都知道，那个男孩是她的干儿子。", "target_word": "干儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认了一个干儿子，还请大家吃了饭。", "target_word": "干儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干儿子每个月都会给干妈打电话。", "target_word": "干儿子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老板有三个干儿子，没有亲儿子。", "target_word": "干儿子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥是我爸爸朋友的干儿子。", "target_word": "干儿子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑着说：“这是我的干儿子，不是亲生的。”", "target_word": "干儿子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "乾兒子", "label": "繁体"}], "register": "口语", "sense_fingerprint": "被认作儿子、没有血缘关系的男孩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e595aba8-a327-4dfa-933f-cb10e384922d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干儿子", "is_correct": true, "explanation": "“收了一个干儿子”指收养一个男孩作养子，与“没有孩子”的语境相符。"}, {"text": "门", "is_correct": false, "explanation": "语义：“门”是物品，不能被收养。"}, {"text": "砖头", "is_correct": false, "explanation": "语义：“砖头”是建材，不能被当作孩子收养。"}, {"text": "理论", "is_correct": false, "explanation": "搭配：“收”后面不能接“理论”，不能说“收了一个理论”。"}], "explanations": {"干儿子": "“收了一个干儿子”指收养一个男孩作养子，与“没有孩子”的语境相符。", "门": "语义：“门”是物品，不能被收养。", "砖头": "语义：“砖头”是建材，不能被当作孩子收养。", "理论": "搭配：“收”后面不能接“理论”，不能说“收了一个理论”。"}, "sentence_index": 0, "correct_answer": "干儿子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "王师傅是小明的干儿子，小明常来看他。", "explanation": "这里应该用〈干爸〉。王师傅是长辈，是小明的干爸，“干儿子”的关系方向反了。"}, {"text": "他是我的干儿子，是我亲生的。", "explanation": "这里应该用〈亲儿子〉。干儿子没有血缘关系，亲生的孩子不能叫干儿子。"}, {"text": "他是个干儿子，我们今天第一次见面。", "explanation": "这里应该用〈陌生人〉。干儿子是被认作的亲属，不能用于素不相识的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干儿子", "is_correct": true, "explanation": "“干儿子”作主语，指认作的儿子，每个月给干妈打电话，符合语境。"}, {"text": "老虎", "is_correct": false, "explanation": "配价：“打电话”要求人作主语，老虎不能给干妈打电话。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是地方，不能给干妈打电话。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是没有生命的东西，不会打电话。"}], "explanations": {"干儿子": "“干儿子”作主语，指认作的儿子，每个月给干妈打电话，符合语境。", "老虎": "配价：“打电话”要求人作主语，老虎不能给干妈打电话。", "厨房": "语义：“厨房”是地方，不能给干妈打电话。", "石头": "语义：“石头”是没有生命的东西，不会打电话。"}, "sentence_index": 6, "correct_answer": "干儿子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的干儿子，我们是同一个妈妈生的兄弟。", "explanation": "这里应该用〈亲弟弟〉。同一个妈妈生的是亲兄弟，干儿子是认的晚辈，没有血缘关系。"}, {"text": "他是我的干儿子，比我大二十岁。", "explanation": "这里应该用〈叔叔〉。干儿子是晚辈，不能用来指比自己大的长辈。"}, {"text": "这是我的干儿子，她很漂亮。", "explanation": "这里应该用〈干女儿〉。干儿子指男孩，后面的“她”与“男孩”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的一个干儿子们考上了大学。", "corrected_sentence": "我的一个干儿子考上了大学。", "error_description": "错误：“一个干儿子们”；正确：“一个干儿子”。“们”表示复数，不能与“一个”一起用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "俩个干儿子都很孝顺。", "corrected_sentence": "两个干儿子都很孝顺。", "error_description": "错误：“俩个”；正确：“两个”。“俩”不能与量词“个”搭配，应该用“两个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
