INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91765, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进展是一件事或一项工作向前推进。", "primary_collocate": null, "pronunciation": "jìn zhǎn", "ipa": "tɕin˥˩ ʈʂan˨˩˦", "syllable_count": 2, "sentences": [{"text": "工作进展得很顺利。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的计划进展很快。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情进展到了哪一步？", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修路的工作进展得有点慢。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的谈判进展缓慢。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子盖得怎么样，进展顺利吗？", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事进展得比我想的快。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的合作进展一直很好。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新书的写作进展不太顺利。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气好，施工进展很快。", "target_word": "进展", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "進展", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：事情、工作向前推进，常说进展顺利、进展很快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e29bc64e-453d-4bb9-9adb-ad6f4c6b55a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91765, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进展", "is_correct": true, "explanation": "正确：进展（jìn zhǎn），动词，指事情向前推进。"}, {"text": "进站", "is_correct": false, "explanation": "zhàn（第四声）与 zhǎn（第三声）声调不同，意思是进站（进入车站）。"}, {"text": "紧张", "is_correct": false, "explanation": "jǐn（第三声）与 jìn（第四声）声调不同；zhāng 与 zhǎn 韵母不同（-ang 与 -an），声调也不同，意思是紧张。"}, {"text": "进账", "is_correct": false, "explanation": "zhàng（第四声）与 zhǎn 韵母不同（-ang 与 -an），声调也不同，意思是进账（收入的钱）。"}], "explanations": {"进展": "正确：进展（jìn zhǎn），动词，指事情向前推进。", "进站": "zhàn（第四声）与 zhǎn（第三声）声调不同，意思是进站（进入车站）。", "紧张": "jǐn（第三声）与 jìn（第四声）声调不同；zhāng 与 zhǎn 韵母不同（-ang 与 -an），声调也不同，意思是紧张。", "进账": "zhàng（第四声）与 zhǎn 韵母不同（-ang 与 -an），声调也不同，意思是进账（收入的钱）。"}, "sentence_index": null, "correct_answer": "进展"}, "level_3": {"options": [{"text": "进展", "is_correct": true, "explanation": "正确：进展，动词，表示工作向前推进，与“得很顺利”搭配。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：工作不能睡觉，与语境不符。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”需要人作主语，工作不能结婚。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：工作不能唱歌，句子不成立。"}], "explanations": {"进展": "正确：进展，动词，表示工作向前推进，与“得很顺利”搭配。", "睡觉": "语义：工作不能睡觉，与语境不符。", "结婚": "配价：“结婚”需要人作主语，工作不能结婚。", "唱歌": "语义：工作不能唱歌，句子不成立。"}, "sentence_index": 0, "correct_answer": "进展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议进展得很早。", "explanation": "这里应该用〈结束〉。会议的结束用“结束”，“进展”指事情向前推进，不能说会议进展得很早。"}, {"text": "她进展得很好听。", "explanation": "这里应该用〈唱〉。歌声好不好听要用“唱”来说，“进展”指事情向前推进，不能用来描述唱歌。"}, {"text": "活动进展得很晚。", "explanation": "这里应该用〈开始〉。活动的开始用“开始”，“进展”指事情向前推进，不能说活动进展得很晚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2449332-8818-4cdf-b350-9a46151234f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进展", "is_correct": true, "explanation": "正确：进展，动词，表示事情向前推进，与“比我想的快”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：事情不能吃，“吃得快”说的是人吃东西。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”需要人作主语，事情不能哭。"}, {"text": "睡", "is_correct": false, "explanation": "语义：事情不能睡觉，“睡得快”说的是人入睡。"}], "explanations": {"进展": "正确：进展，动词，表示事情向前推进，与“比我想的快”搭配。", "吃": "语义：事情不能吃，“吃得快”说的是人吃东西。", "哭": "配价：“哭”需要人作主语，事情不能哭。", "睡": "语义：事情不能睡觉，“睡得快”说的是人入睡。"}, "sentence_index": 6, "correct_answer": "进展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "衣服进展得很干净。", "explanation": "这里应该用〈洗〉。衣服干净是洗出来的，“进展”不能描述衣服的状态。"}, {"text": "饭进展得很香。", "explanation": "这里应该用〈烧〉。饭的香味用“烧”来描述，“进展”指事情向前推进，不能说饭进展得很香。"}, {"text": "雨进展得很大。", "explanation": "这里应该用〈下〉。雨的大小用“下”来描述，“进展”不能用于雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2449332-8818-4cdf-b350-9a46151234f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新房子的装修进展的很快。", "corrected_sentence": "新房子的装修进展得很快。", "error_description": "结构助词错误：动词后表示程度的补语要用“得”，不用“的”，应说“进展得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2449332-8818-4cdf-b350-9a46151234f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区的建设进展地很慢。", "corrected_sentence": "这个小区的建设进展得很慢。", "error_description": "结构助词错误：“进展”后表示程度的补语要用“得”；“地”用于动词前修饰动词，不能说“进展地很慢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2449332-8818-4cdf-b350-9a46151234f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
