INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91769, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事宜是要办的事。", "primary_collocate": null, "pronunciation": "shì yí", "ipa": "ʂɻ̩˥˩ i˧˥", "syllable_count": 2, "sentences": [{"text": "下周的各项事宜繁多，需要提前安排。", "target_word": "事宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国之前，有很多事宜需要准备。", "target_word": "事宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈列了一张单子，写着过年的各项事宜。", "target_word": "事宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业典礼的事宜，老师已经跟我们说了。", "target_word": "事宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还有几项事宜没有办完。", "target_word": "事宜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会前，先把重要事宜写在本子上。", "target_word": "事宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忙着处理搬家的各种事宜。", "target_word": "事宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些事宜都要在周五以前办好。", "target_word": "事宜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "结婚的事宜，他们打算下个月再谈。", "target_word": "事宜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她认真记下了每一项事宜。", "target_word": "事宜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "要办的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85b2443-ac17-43fe-8739-349acbe3fea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91769, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事宜", "is_correct": true, "explanation": "事宜（shì yí）：有关事务的安排和处理，是本题的正确答案。"}, {"text": "释义", "is_correct": false, "explanation": "释义 shìyì：第二音节 yì（第四声）与 yí（第二声）声调不同，意思是解释词语或句子的含义。"}, {"text": "十一", "is_correct": false, "explanation": "十一 shíyī：两个音节的声调都与 shì yí 不同，意思是数字“十一”。"}, {"text": "失意", "is_correct": false, "explanation": "失意 shīyì：两个音节的声调都与 shì yí 不同，意思是事情不顺利、情绪低落。"}], "explanations": {"事宜": "事宜（shì yí）：有关事务的安排和处理，是本题的正确答案。", "释义": "释义 shìyì：第二音节 yì（第四声）与 yí（第二声）声调不同，意思是解释词语或句子的含义。", "十一": "十一 shíyī：两个音节的声调都与 shì yí 不同，意思是数字“十一”。", "失意": "失意 shīyì：两个音节的声调都与 shì yí 不同，意思是事情不顺利、情绪低落。"}, "sentence_index": null, "correct_answer": "事宜"}, "level_3": {"options": [{"text": "事宜", "is_correct": true, "explanation": "正确：“下周的各项事宜”指下周需要安排和处理的多项事务，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指冷热阴晴，“下周的各项天气繁多，需要提前安排”说不通。"}, {"text": "感情", "is_correct": false, "explanation": "语义：“感情”指情绪和情谊，不能说“各项感情繁多”，与“提前安排”也不搭。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“繁多”多用于事务、任务，不说“体温繁多”。"}], "explanations": {"事宜": "正确：“下周的各项事宜”指下周需要安排和处理的多项事务，符合句意。", "天气": "语义：“天气”指冷热阴晴，“下周的各项天气繁多，需要提前安排”说不通。", "感情": "语义：“感情”指情绪和情谊，不能说“各项感情繁多”，与“提前安排”也不搭。", "体温": "搭配：“繁多”多用于事务、任务，不说“体温繁多”。"}, "sentence_index": 0, "correct_answer": "事宜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈送给我一件生日事宜。", "explanation": "这里应该用〈礼物〉。“事宜”指需要安排、处理的事务，不是可以送人的实物。"}, {"text": "他喝了一杯很浓的事宜。", "explanation": "这里应该用〈咖啡〉。“事宜”指需要安排、处理的事务，不能用“一杯”来计量，也不能指饮品。"}, {"text": "妈妈做的事宜很好吃，全家人都夸她手艺好。", "explanation": "这里应该用〈饭菜〉。“事宜”指需要安排、处理的事务，不能指做出来的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91769, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "事宜", "is_correct": true, "explanation": "事宜（shì yí）：有关事务的安排和处理，是本题的正确答案。"}, {"text": "示意", "is_correct": false, "explanation": "示意 shìyì：第二音节 yì（第四声）与 yí（第二声）声调不同，意思是用动作或表情表示意思。"}, {"text": "十亿", "is_correct": false, "explanation": "十亿 shíyì：两个音节的声调都与 shì yí 不同，意思是数字“十亿”。"}, {"text": "试衣", "is_correct": false, "explanation": "试衣 shìyī：第二音节 yī（第一声）与 yí（第二声）声调不同，意思是试穿衣服。"}], "explanations": {"事宜": "事宜（shì yí）：有关事务的安排和处理，是本题的正确答案。", "示意": "示意 shìyì：第二音节 yì（第四声）与 yí（第二声）声调不同，意思是用动作或表情表示意思。", "十亿": "十亿 shíyì：两个音节的声调都与 shì yí 不同，意思是数字“十亿”。", "试衣": "试衣 shìyī：第二音节 yī（第一声）与 yí（第二声）声调不同，意思是试穿衣服。"}, "sentence_index": null, "correct_answer": "事宜"}, "level_3": {"options": [{"text": "事宜", "is_correct": true, "explanation": "正确：“各种事宜”指搬家过程中需要处理的多项事务，符合句意。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：“乐曲”是音乐作品，与“处理搬家”不搭，句子说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体型，不能被“处理”，与搬家也无关。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：“朋友”是人，不能说“处理搬家的各种朋友”，句子说不通。"}], "explanations": {"事宜": "正确：“各种事宜”指搬家过程中需要处理的多项事务，符合句意。", "乐曲": "语义：“乐曲”是音乐作品，与“处理搬家”不搭，句子说不通。", "身材": "体貌：“身材”指人的体型，不能被“处理”，与搬家也无关。", "朋友": "语义：“朋友”是人，不能说“处理搬家的各种朋友”，句子说不通。"}, "sentence_index": 6, "correct_answer": "事宜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她唱了一首很好听的事宜。", "explanation": "这里应该用〈歌〉。“事宜”指需要安排、处理的事务，不能用来指歌曲。"}, {"text": "他做了一次很精彩的事宜。", "explanation": "这里应该用〈演讲〉。“事宜”指需要安排、处理的事务，不能指演讲这类发言或活动。"}, {"text": "她拍了一张很漂亮的事宜。", "explanation": "这里应该用〈照片〉。“事宜”指需要安排、处理的事务，不能指可以拍摄的照片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还有两本事宜没有办完。", "corrected_sentence": "我还有两项事宜没有办完。", "error_description": "量词错误：“本”用于书籍等，不能修饰“事宜”；“事宜”的量词是“项”，应说“两项事宜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他忙着处理搬家的各只事宜，一直没有休息。", "corrected_sentence": "他忙着处理搬家的各项事宜，一直没有休息。", "error_description": "量词错误：“只”用于动物等，不能修饰“事宜”；应说“各项事宜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
