INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91771, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队里管很多士兵的大官。", "primary_collocate": null, "pronunciation": "sī lìng", "ipa": "sɨ˥ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他爸爸是军队里的司令。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司令管着几万名士兵。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的司令很严肃，不爱笑。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明长大想当司令。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司令坐车来看望士兵。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位司令很关心他的士兵。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们都很尊敬司令。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司令在大会上讲了话。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司令的办公室里挂着一面军旗。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在博物馆看到了老司令的照片。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "司令员", "label": "复合"}, {"form": "司令部", "label": "复合"}], "register": "中性", "sense_fingerprint": "军队里管很多士兵的大官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baee0e88-f68e-4a39-b1f8-d15a57ebea04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91771, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "司令", "is_correct": true, "explanation": "正确：司令是军队里管很多士兵的大官，与“他爸爸”的身份相符。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：爸爸是成年人，不可能是小学生。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：爸爸是成年人，不会是婴儿。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“是”后面要接人的身份，“面包”不能充当爸爸的身份。"}], "explanations": {"司令": "正确：司令是军队里管很多士兵的大官，与“他爸爸”的身份相符。", "小学生": "语义：爸爸是成年人，不可能是小学生。", "婴儿": "语义：爸爸是成年人，不会是婴儿。", "面包": "搭配：“是”后面要接人的身份，“面包”不能充当爸爸的身份。"}, "sentence_index": 0, "correct_answer": "司令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的司令每天早上七点做好早饭等我吃。", "explanation": "这里应该用〈厨师〉。司令指军队里管很多士兵的大官，不指做饭的人。"}, {"text": "我的司令每天早上七点来接我上班。", "explanation": "这里应该用〈司机〉。司令指军队里管很多士兵的大官，不指专门开车接送人的人。"}, {"text": "司令每天给病人换药。", "explanation": "这里应该用〈护士〉。司令是管理士兵的大官，不负责护理病人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91771, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "司令", "is_correct": true, "explanation": "正确：司令是战士尊敬的军队大官，句子意思通顺。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是值得尊敬的对象。"}, {"text": "老鼠", "is_correct": false, "explanation": "搭配：“尊敬”搭配的对象是人或有地位的人，不能说“尊敬老鼠”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有被尊敬的意义，与句子语境不符。"}], "explanations": {"司令": "正确：司令是战士尊敬的军队大官，句子意思通顺。", "垃圾": "语义：垃圾不是值得尊敬的对象。", "老鼠": "搭配：“尊敬”搭配的对象是人或有地位的人，不能说“尊敬老鼠”。", "窗户": "语义：窗户没有被尊敬的意义，与句子语境不符。"}, "sentence_index": 6, "correct_answer": "司令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的司令每天早上亲自开门营业。", "explanation": "这里应该用〈店长〉。司令指军队里管很多士兵的大官，不指店铺的负责人。"}, {"text": "我每天在理发店看司令剪头发。", "explanation": "这里应该用〈理发师〉。司令指管很多士兵的大官，不指给人剪头发的人。"}, {"text": "这所学校的司令每天给学生上课。", "explanation": "这里应该用〈老师〉。司令指军队里管很多士兵的大官，不指给学生上课的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只老司令管理着很大的部队。", "corrected_sentence": "一位老司令管理着很大的部队。", "error_description": "量词错误：指人的“司令”要用量词“位”，不能用“只”（多用于动物）。正确说法：一位老司令管理着很大的部队。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位司令着管几万名士兵。", "corrected_sentence": "那位司令管着几万名士兵。", "error_description": "体标位置错误：“着”须紧跟在“管”后，说“管着”，不能说“着管”。正确说法：那位司令管着几万名士兵。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
