INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91772, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队中某一级的最高指挥官。", "primary_collocate": null, "pronunciation": "sī lìng", "ipa": "sɨ˥ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这位司令指挥全军作战。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司令下令，部队马上出发。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老司令八十岁了，身体还很好。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司令在地图前开了一个会。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们向司令敬礼。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司令的办公室在三楼。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支部队的司令姓王。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小兵做到了司令。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司令把作战计划交给了参谋。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位司令明天要来看我们的部队。", "target_word": "司令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "司令员", "label": "复合"}, {"form": "司令部", "label": "复合"}], "register": "中性", "sense_fingerprint": "军队某一级的最高指挥官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baee0e88-f68e-4a39-b1f8-d15a57ebea04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "司令", "is_correct": true, "explanation": "正确：司令是军队的最高指挥官，与“指挥全军作战”相符。"}, {"text": "士兵", "is_correct": false, "explanation": "语义：士兵只是普通战斗人员，不能指挥全军作战。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师负责做饭，与“指挥全军作战”毫不相关。"}, {"text": "校长", "is_correct": false, "explanation": "语义：校长管理学校，不指挥部队作战。"}], "explanations": {"司令": "正确：司令是军队的最高指挥官，与“指挥全军作战”相符。", "士兵": "语义：士兵只是普通战斗人员，不能指挥全军作战。", "厨师": "语义：厨师负责做饭，与“指挥全军作战”毫不相关。", "校长": "语义：校长管理学校，不指挥部队作战。"}, "sentence_index": 0, "correct_answer": "司令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的司令每天开车接我去上班。", "explanation": "这里应该用〈司机〉。司令指军队里的指挥官，不指专门开车接送人的人。"}, {"text": "这家超市的司令每天站在门口收钱。", "explanation": "这里应该用〈收银员〉。司令指军队某一级的最高指挥官，不指超市里收钱的人。"}, {"text": "我们食堂的司令每天早上做早饭。", "explanation": "这里应该用〈厨师〉。司令指军队里的指挥官，不指做饭的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "司令", "is_correct": true, "explanation": "正确：这里说的是部队指挥官的姓氏，司令是人，可以有姓。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“姓”只用于人，不能说“厨房姓王”。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：飞机是器械，不能有姓氏。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是部队的成员，不能有姓氏。"}], "explanations": {"司令": "正确：这里说的是部队指挥官的姓氏，司令是人，可以有姓。", "厨房": "搭配：“姓”只用于人，不能说“厨房姓王”。", "飞机": "语义：飞机是器械，不能有姓氏。", "石头": "语义：石头不是部队的成员，不能有姓氏。"}, "sentence_index": 6, "correct_answer": "司令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院的司令每天给很多病人看病。", "explanation": "这里应该用〈医生〉。司令指军队里的指挥官，不负责给病人看病。"}, {"text": "这所学校的司令每天早上都去修理电脑。", "explanation": "这里应该用〈技术员〉。司令指军队的指挥官，不指修理电脑的人。"}, {"text": "这家饭店的司令每天做很多菜。", "explanation": "这里应该用〈厨师〉。司令指军队的指挥官，不指做饭的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只司令刚到部队。", "corrected_sentence": "一位司令刚到部队。", "error_description": "量词错误：指人的“司令”要用量词“位”，不能用“只”（多用于动物）。正确说法：一位司令刚到部队。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当了过司令。", "corrected_sentence": "他当过司令。", "error_description": "体标错误：“了”与“过”不能同时用在“当”后，只说“当过”。正确说法：他当过司令。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
