INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91773, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电视剧是在电视里放的、演员演出的故事。", "primary_collocate": null, "pronunciation": "diàn shì jù", "ipa": "tjɛn⁵¹ ʂɻ̩⁵¹ tɕy⁵¹", "syllable_count": 3, "sentences": [{"text": "电视剧里的演员都很年轻。", "target_word": "电视剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电视剧的故事很感人。", "target_word": "电视剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈晚饭后总要看一集电视剧。", "target_word": "电视剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是看电视剧学会这个词的。", "target_word": "电视剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电视剧是在海边拍的。", "target_word": "电视剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱看电视剧，不爱看新闻。", "target_word": "电视剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子看了一集电视剧，就去写作业了。", "target_word": "电视剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视剧的最后一集，我哭了。", "target_word": "电视剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个演员演过很多电视剧。", "target_word": "电视剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我想在家看电视剧。", "target_word": "电视剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "集", "label": "量词"}, {"form": "电视连续剧", "label": "复合"}, {"form": "電視劇", "label": "繁体"}], "register": "通用", "sense_fingerprint": "电视里演员演出的故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1253fbc-9288-40c9-a9b1-e95e77d08214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91773, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电视剧", "is_correct": true, "explanation": "正确：电视剧里有演员表演，符合“演员演出的故事”。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文字作品，里面没有演员在表演。"}, {"text": "新闻", "is_correct": false, "explanation": "语义：新闻由主持人报道事实，里面没有演员在演出。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是教学用书，里面没有演员在表演。"}], "explanations": {"电视剧": "正确：电视剧里有演员表演，符合“演员演出的故事”。", "小说": "语义：小说是文字作品，里面没有演员在表演。", "新闻": "语义：新闻由主持人报道事实，里面没有演员在演出。", "课本": "语义：课本是教学用书，里面没有演员在表演。"}, "sentence_index": 0, "correct_answer": "电视剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电视剧的主持人很风趣。", "explanation": "这里应该用“节目”。电视剧是演员演的故事，没有主持人，主持人是综艺节目里的角色。"}, {"text": "这部电视剧昨天结婚了。", "explanation": "这里的“电视剧”被当成了人。电视剧是播出的故事，不会结婚，结婚的应是演员或角色。"}, {"text": "这部电视剧很好吃。", "explanation": "这里应该用“饭菜”。电视剧是播出的故事，不能说“好吃”，形容味道的应该是饭菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电视剧", "is_correct": true, "explanation": "正确：电视剧可以按“集”计数，孩子看完一集后去写作业，符合语境。"}, {"text": "广播剧", "is_correct": false, "explanation": "语义：广播剧是用来听的，不能说“看了一集”。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：量词“集”不能用于报纸，报纸用“份”计数。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是工具书，不是可以“看一集”的节目。"}], "explanations": {"电视剧": "正确：电视剧可以按“集”计数，孩子看完一集后去写作业，符合语境。", "广播剧": "语义：广播剧是用来听的，不能说“看了一集”。", "报纸": "搭配：量词“集”不能用于报纸，报纸用“份”计数。", "字典": "语义：字典是工具书，不是可以“看一集”的节目。"}, "sentence_index": 6, "correct_answer": "电视剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我想在家喝一部电视剧。", "explanation": "这里应该用“茶”。电视剧是要看的，不能喝，“喝”的应是茶这类饮品。"}, {"text": "周末我想去剧院看电视剧。", "explanation": "这里应该用“话剧”。剧院演出的是话剧，电视剧要在电视上看。"}, {"text": "我想把电视剧挂在墙上。", "explanation": "这里的“电视剧”被当成了海报。电视剧是播出的故事，挂在墙上的应是海报，要说“海报”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每周末都会追一本电视剧。", "corrected_sentence": "我每周末都会追一部电视剧。", "error_description": "量词错误：“电视剧”应该用量词“部”或“集”，“本”用于书籍，不能用于电视剧。正确说法：我每周末都会追一部电视剧。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈每天晚上都看一张电视剧。", "corrected_sentence": "妈妈每天晚上都看一部电视剧。", "error_description": "量词错误：“电视剧”应该用量词“部”或“集”，“张”用于纸张、票等扁平物体，不能用于电视剧。正确说法：妈妈每天晚上都看一部电视剧。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
