INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91776, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "旧时把一夜分为五个时段，五更指天将亮的时候。", "primary_collocate": null, "pronunciation": "wǔ gēng", "ipa": "u˨˩˦ kɤŋ˥", "syllable_count": 2, "sentences": [{"text": "旧时一夜分五更，五更是最后一段。", "target_word": "五更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人说，五更快到了，鸡就叫了。", "target_word": "五更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写着，他从三更读到五更。", "target_word": "五更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打更的人喊了一声，说五更到了。", "target_word": "五更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人回忆，旧时五更就有人挑水了。", "target_word": "五更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗人一夜未睡，直到五更才写完诗。", "target_word": "五更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，五更以后天就渐渐亮了。", "target_word": "五更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到五更的鼓声，学生们起床了。", "target_word": "五更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了四更，就是五更了。", "target_word": "五更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在信里说，五更的风特别冷。", "target_word": "五更", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "五更天", "label": "复合"}], "register": "书面", "sense_fingerprint": "旧时一夜五个时段中的第五段，天将亮的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106b6cc5-ef4e-4494-9883-9314d895a3e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "五更", "is_correct": true, "explanation": "五更：旧时一夜的第五段，是最后一段，与句中的描述相符。"}, {"text": "三更", "is_correct": false, "explanation": "语义：三更是一夜中的第三段，不是最后一段。"}, {"text": "初更", "is_correct": false, "explanation": "语义：初更是一夜的开始，不可能是最后一段。"}, {"text": "午夜", "is_correct": false, "explanation": "语域：“午夜”是现代的计时说法，不是旧时一夜分五更中的一段。"}], "explanations": {"五更": "五更：旧时一夜的第五段，是最后一段，与句中的描述相符。", "三更": "语义：三更是一夜中的第三段，不是最后一段。", "初更": "语义：初更是一夜的开始，不可能是最后一段。", "午夜": "语域：“午夜”是现代的计时说法，不是旧时一夜分五更中的一段。"}, "sentence_index": 0, "correct_answer": "五更"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在五更时放学回家。", "explanation": "这里应该用〈傍晚〉。五更是天将亮的时候，放学回家一般在〈傍晚〉这类时段，不能用五更。"}, {"text": "五更的太阳很亮，我们去公园。", "explanation": "这里应该用〈正午〉。五更时太阳还没出来，不能说太阳很亮；说太阳很亮要用〈正午〉。"}, {"text": "我们五更十二点才睡觉。", "explanation": "“五更”指天快亮的时候，不能和“十二点”这样的钟点连用；十二点是正午或半夜，都不是天快亮的时候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "五更", "is_correct": true, "explanation": "五更：天快亮的时候，“以后天就渐渐亮了”与之相符。"}, {"text": "初更", "is_correct": false, "explanation": "语义：初更是夜晚开始的时候，之后不会是天渐渐亮。"}, {"text": "正午", "is_correct": false, "explanation": "语义：正午天已经亮了，不会说“以后天就渐渐亮”。"}, {"text": "傍晚", "is_correct": false, "explanation": "语义：“傍晚”之后天会渐渐变暗，不会“渐渐亮了”。"}], "explanations": {"五更": "五更：天快亮的时候，“以后天就渐渐亮了”与之相符。", "初更": "语义：初更是夜晚开始的时候，之后不会是天渐渐亮。", "正午": "语义：正午天已经亮了，不会说“以后天就渐渐亮”。", "傍晚": "语义：“傍晚”之后天会渐渐变暗，不会“渐渐亮了”。"}, "sentence_index": 6, "correct_answer": "五更"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "五更的时候，太阳正高高地挂在天上。", "explanation": "这里应该用〈正午〉。五更时天还没亮，太阳尚未升起，不能说太阳高挂在天上；这样的景象要用〈正午〉这类白天时段。"}, {"text": "五更以后，天慢慢黑了。", "explanation": "这里应该用〈日落〉。五更之后天快亮，不会慢慢变黑；天慢慢黑要说〈日落〉之后的情况。"}, {"text": "五更八点，我们开始吃饭。", "explanation": "“五更”指天快亮的时候，是旧时的时段名，不能和“八点”这样的钟点连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只五更，他一直在赶路。", "corrected_sentence": "那个五更，他一直在赶路。", "error_description": "错误：“那只五更”；正确：“那个五更”。五更指一段时间，不是动物，应用通用量词“个”，“只”一般用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古时候，五更天的特别安静。", "corrected_sentence": "古时候，五更天特别安静。", "error_description": "错误：“五更天的特别安静”；正确：“五更天特别安静”。“的”是定语标记，用在名词修饰语之后；“特别安静”是谓语，前面不能加“的”，应去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
