INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91777, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "顾问是懂很多，别人问他事，他给出好主意的人。", "primary_collocate": null, "pronunciation": "gù wèn", "ipa": "ku˥˩ wən˥˩", "syllable_count": 2, "sentences": [{"text": "他懂得多，是我们的顾问。", "target_word": "顾问", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "有事就问他，他是个好顾问。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的爷爷是家里的顾问。", "target_word": "顾问", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买房子以前，我请朋友当顾问。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他懂得很多，遇到难题大家都请他当顾问。", "target_word": "顾问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐懂穿衣，是我的顾问。", "target_word": "顾问", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不知道怎么办，想找个顾问聊聊。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老王见多识广，是我们的顾问。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给我出了很多好主意，像个顾问。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们小组有问题，就去请教那位顾问。", "target_word": "顾问", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "顧問", "label": "繁体"}], "register": "中性", "sense_fingerprint": "顾问：懂得多、别人有事请教时能出好主意的人（日常的、非正式的身份）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33653423-e2ed-4a50-b920-a2c54289c879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91777, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文盲", "is_correct": false, "explanation": "语义：“文盲”指不识字的人，与“他懂得多”正相反。"}, {"text": "顾问", "is_correct": true, "explanation": "“顾问”指懂得多、能给别人出主意的人，与“懂得多”和“我们的”相符。"}, {"text": "婴儿", "is_correct": false, "explanation": "搭配：“懂得多”说的是知识积累，不能用来形容婴儿。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”指偷窃的人，不是大家可以请教、视为“我们的”依靠的人。"}], "explanations": {"文盲": "语义：“文盲”指不识字的人，与“他懂得多”正相反。", "顾问": "“顾问”指懂得多、能给别人出主意的人，与“懂得多”和“我们的”相符。", "婴儿": "搭配：“懂得多”说的是知识积累，不能用来形容婴儿。", "小偷": "语义：“小偷”指偷窃的人，不是大家可以请教、视为“我们的”依靠的人。"}, "sentence_index": 0, "correct_answer": "顾问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的顾问每天帮我整理文件。", "explanation": "这里应该用〈助手〉。顾问提供意见和建议，不负责整理文件这类具体事务。"}, {"text": "这位顾问把合同译成英文。", "explanation": "这里应该用〈翻译〉。顾问只出主意，不负责把合同译成外文。"}, {"text": "这位顾问每天在厨房做三顿饭。", "explanation": "这里应该用〈厨师〉。顾问提供意见，不负责下厨做饭，做饭是厨师的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91777, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "搭配：“聊聊”需要能交谈的对象，“石头”不能和人聊天。"}, {"text": "顾问", "is_correct": true, "explanation": "“顾问”能为人出主意，与“不知道怎么办”、想找人请教的语境相符。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“聊聊”需要能交谈的对象，“椅子”无法与人交谈。"}, {"text": "雕像", "is_correct": false, "explanation": "搭配：“聊聊”需要能说话的对象，“雕像”无法与人交谈。"}], "explanations": {"石头": "搭配：“聊聊”需要能交谈的对象，“石头”不能和人聊天。", "顾问": "“顾问”能为人出主意，与“不知道怎么办”、想找人请教的语境相符。", "椅子": "搭配：“聊聊”需要能交谈的对象，“椅子”无法与人交谈。", "雕像": "搭配：“聊聊”需要能说话的对象，“雕像”无法与人交谈。"}, "sentence_index": 6, "correct_answer": "顾问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位顾问在实验室里做了三年实验。", "explanation": "这里应该用〈研究员〉。顾问的工作是提供意见，不在实验室里亲自做实验，做实验是研究员的工作。"}, {"text": "这位顾问每天带队训练。", "explanation": "这里应该用〈教练〉。顾问不负责带队训练，训练队员是教练的工作。"}, {"text": "那位顾问在舞台上唱了一首歌。", "explanation": "这里应该用〈演员〉。顾问靠专业意见工作，不在舞台上表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我请张叔叔顾问。", "corrected_sentence": "我请张叔叔当顾问。", "error_description": "错误：“张叔叔”后缺少“当”。正确：“我请张叔叔当顾问”。“请+人+当+职务”表示让某人担任某种身份，“当”不能省。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本顾问很懂装修。", "corrected_sentence": "这位顾问很懂装修。", "error_description": "错误：量词用错。“顾问”指人，应用“位”，“本”用于书册、本子一类物品。正确：“这位顾问”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbf0000-696d-4149-8efb-f9d1dc5bb301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
