INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91780, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "影响很大、情况危急、需要认真对待的问题。", "primary_collocate": null, "pronunciation": "yán zhòng wèn tí", "ipa": "jɛn˧˥ ʈʂʊŋ˥˩ wən˥˩ tʰi˧˥", "syllable_count": 4, "sentences": [{"text": "空气不好是影响很多人的严重问题。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说他的病是严重问题，要认真对待。", "target_word": "严重问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司最近出现了严重问题，经理很着急。", "target_word": "严重问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不上学是一个严重问题。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生打架的事越来越多，学校认为这是严重问题。", "target_word": "严重问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全城都停电了，这是严重问题。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的健康成了家里的严重问题。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家开会讨论了这个严重问题。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师认真想过这个严重问题。", "target_word": "严重问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水变少是影响全国的严重问题。", "target_word": "严重问题", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个严重问题", "label": "量词"}, {"form": "嚴重問題", "label": "繁体"}], "register": "中性", "sense_fingerprint": "严重问题：影响大、情况危急、须认真对待的问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4c1239-4184-41d0-a500-af91482a0938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严重问题", "is_correct": true, "explanation": "正确。严重问题指影响大、需要认真对待的问题，与“影响很多人”相符。"}, {"text": "好天气", "is_correct": false, "explanation": "语义：“好天气”是好的情况，与“空气不好”正相反。"}, {"text": "优点", "is_correct": false, "explanation": "语义：“优点”是好的方面，与“影响很多人”的负面语义冲突。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”说外观，与“影响很多人”的健康问题无关。"}], "explanations": {"严重问题": "正确。严重问题指影响大、需要认真对待的问题，与“影响很多人”相符。", "好天气": "语义：“好天气”是好的情况，与“空气不好”正相反。", "优点": "语义：“优点”是好的方面，与“影响很多人”的负面语义冲突。", "颜色": "语义：“颜色”说外观，与“影响很多人”的健康问题无关。"}, "sentence_index": 0, "correct_answer": "严重问题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道奥数题是个严重问题，要想很久。", "explanation": "这里应该用〈难题〉。严重问题指影响大、情况危急的问题；奥数题只是难，并不影响大局。"}, {"text": "他把水洒在地上，这是个严重问题，擦一下就好。", "explanation": "这里应该用〈小事〉。严重问题需要认真对待，水洒在地上擦一下就好，不属于这种情况。"}, {"text": "他对新工作只有一点严重问题，很快就适应了。", "explanation": "这里应该用〈小烦恼〉。严重问题指影响大、需要认真对待的问题；只是一点小烦恼时用“小烦恼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严重问题", "is_correct": true, "explanation": "正确。严重问题指影响大、需要认真对待的问题，与“老人的健康”相符。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”是供玩耍的东西，与“老人的健康”这个严肃问题不符。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指摆设，不能说老人的健康是家里的装饰。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”说外观，与“老人的健康”无关。"}], "explanations": {"严重问题": "正确。严重问题指影响大、需要认真对待的问题，与“老人的健康”相符。", "玩具": "语义：“玩具”是供玩耍的东西，与“老人的健康”这个严肃问题不符。", "装饰": "语义：“装饰”指摆设，不能说老人的健康是家里的装饰。", "颜色": "语义：“颜色”说外观，与“老人的健康”无关。"}, "sentence_index": 6, "correct_answer": "严重问题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书放错了地方，很快就找到了，这是个严重问题。", "explanation": "这里应该用〈小插曲〉。严重问题指影响大、需要认真对待的问题；很快找到的小事不属于这种情况。"}, {"text": "这次聚会很开心，大家聊了很多有趣的话题，这是个严重问题。", "explanation": "这里应该用〈好事〉。严重问题指影响大、需要认真对待的问题；愉快的聚会不属于这种情况。"}, {"text": "这只是一个小误会，已经说清楚了，这是个严重问题。", "explanation": "这里应该用〈小误会〉。严重问题指影响大、需要认真对待的问题；已经说清楚的小误会不属于这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理把这只严重问题交给了小王。", "corrected_sentence": "经理把这个严重问题交给了小王。", "error_description": "错误形式：“这只严重问题”；正确形式：“这个严重问题”。“问题”是抽象名词，指示量词要用“个”，“只”不能用于问题。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师对这只严重问题很重视，马上开了会。", "corrected_sentence": "老师对这个严重问题很重视，马上开了会。", "error_description": "错误形式：“这只严重问题”；正确形式：“这个严重问题”。“问题”是抽象名词，指示量词要用“个”，“只”不能用于问题。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
