INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91781, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "代表性是能让人看出一类东西的特点。", "primary_collocate": null, "pronunciation": "dài biǎo xìng", "ipa": "tai˥˩ pjɑʊ˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这幅画很有代表性。", "target_word": "代表性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个例子没有代表性。", "target_word": "代表性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他点的菜很有代表性。", "target_word": "代表性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些照片有代表性，能看出老北京的样子。", "target_word": "代表性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜代表性很强。", "target_word": "代表性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师挑了一个有代表性的句子。", "target_word": "代表性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件旗袍很有代表性，一看就知道是中国的服装。", "target_word": "代表性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京烤鸭很有代表性。", "target_word": "代表性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你选几张有代表性的照片。", "target_word": "代表性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌是他最有代表性的作品。", "target_word": "代表性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "能体现一类事物特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6e59a67-b373-4e65-8aa0-e2aa10bbe482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91781, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代表性", "is_correct": true, "explanation": "“代表性”指能体现一类事物特点的性质，“很有代表性”符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“很有价格”不通，“价格”不能用“很有”修饰，应说“价格高”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物的重量，画作没有体重。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指一个人受教育的经历，不能用来描述画作。"}], "explanations": {"代表性": "“代表性”指能体现一类事物特点的性质，“很有代表性”符合句意。", "价格": "搭配：“很有价格”不通，“价格”不能用“很有”修饰，应说“价格高”。", "体重": "语义：体重指人或动物的重量，画作没有体重。", "学历": "语义：学历指一个人受教育的经历，不能用来描述画作。"}, "sentence_index": 0, "correct_answer": "代表性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯水的代表性太高了，不能喝。", "explanation": "这里应该用〈温度〉。代表性指能体现一类东西特点的性质，不能用来说水的冷热。"}, {"text": "他最有名的代表性是《红楼梦》。", "explanation": "这里应该用〈代表作〉。代表性是性质，不能指具体的作品。"}, {"text": "这块布的代表性很厚，冬天穿正好。", "explanation": "这里应该用〈厚度〉。代表性指能体现一类东西特点的性质，不能用来说布料的厚薄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91781, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代表性", "is_correct": true, "explanation": "“代表性”与“很有”搭配，后文“一看就知道是中国的服装”正好说明它能体现中国服装的特点。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指身体的温度，旗袍没有体温。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：嗓音指人或动物发出的声音，衣服没有嗓音。"}, {"text": "文献", "is_correct": false, "explanation": "语域：文献是学术或资料用语，描述服饰时不用。"}], "explanations": {"代表性": "“代表性”与“很有”搭配，后文“一看就知道是中国的服装”正好说明它能体现中国服装的特点。", "体温": "语义：体温指身体的温度，旗袍没有体温。", "嗓音": "语义：嗓音指人或动物发出的声音，衣服没有嗓音。", "文献": "语域：文献是学术或资料用语，描述服饰时不用。"}, "sentence_index": 6, "correct_answer": "代表性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌是他的代表性。", "explanation": "这里应该用〈代表作〉。代表性是性质，不能直接指一件作品。"}, {"text": "这座大楼是城市的代表性。", "explanation": "这里应该用〈门面〉。代表性是性质，不能指建筑本身。"}, {"text": "他是大家的代表性。", "explanation": "这里应该用〈代表〉。代表性是性质，不能指代替大家说话的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张地图很代表性，能看出这个城市的样子。", "corrected_sentence": "这张地图很有代表性，能看出这个城市的样子。", "error_description": "错误在于“代表性”前缺少“有”。应说“很有代表性”，直接说“很代表性”不符合汉语习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种茶不有代表性，能说明这个地区的风味。", "corrected_sentence": "这种茶很有代表性，能说明这个地区的风味。", "error_description": "错误在于“很”写成了“不”。“不有代表性”是否定，句意是肯定的，应说“很有代表性”。“不有”不成词，否定“有”要说“没有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
