INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能反映总体或某类群体共同情况的性质，多用于样本、调查和意见。", "primary_collocate": null, "pronunciation": "dài biǎo xìng", "ipa": "tai˥˩ pjɑʊ˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这次调查的人很少，代表性不够。", "target_word": "代表性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "样本要有代表性。", "target_word": "代表性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个班的成绩没有代表性。", "target_word": "代表性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的意见有很强的代表性。", "target_word": "代表性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个数字没有代表性，不能说明问题。", "target_word": "代表性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选来的学生要有代表性。", "target_word": "代表性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人的看法缺少代表性。", "target_word": "代表性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份问卷的结果很有代表性。", "target_word": "代表性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几家公司的数据代表性很强。", "target_word": "代表性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的调查对象有广泛的代表性。", "target_word": "代表性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "能反映总体或群体共同情况（样本、调查、意见）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6e59a67-b373-4e65-8aa0-e2aa10bbe482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代表性", "is_correct": true, "explanation": "“代表性”指样本能反映总体的性质，“代表性不够”符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道指食物或气味的特点，调查没有味道。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指身体的温度，调查不能有体温。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：嗓音指人发出的声音，“调查”本身没有嗓音，与“代表性不够”无关。"}], "explanations": {"代表性": "“代表性”指样本能反映总体的性质，“代表性不够”符合句意。", "味道": "语义：味道指食物或气味的特点，调查没有味道。", "体温": "语义：体温指身体的温度，调查不能有体温。", "嗓音": "语义：嗓音指人发出的声音，“调查”本身没有嗓音，与“代表性不够”无关。"}, "sentence_index": 0, "correct_answer": "代表性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台仪器的代表性很高，测量很准。", "explanation": "这里应该用〈准确性〉。代表性指样本能反映总体的性质，仪器的测量精度要说准确性。"}, {"text": "这次调查的代表性很长，持续了三天。", "explanation": "这里应该用〈时长〉。代表性说的是样本能否反映总体，不是调查持续的时间。"}, {"text": "这碗汤的代表性太咸了，我喝不下。", "explanation": "这里应该用〈味道〉。代表性指样本能反映总体的性质，不能说汤咸不咸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代表性", "is_correct": true, "explanation": "“代表性”指看法能代表一类人的共同观点，“缺少代表性”符合句意。"}, {"text": "食欲", "is_correct": false, "explanation": "语义：食欲指人对食物的欲望，看法不能有食欲。"}, {"text": "颜值", "is_correct": false, "explanation": "语域：颜值是口语和网络用语，不用于书面评价看法。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址指位置信息，看法没有地址。"}], "explanations": {"代表性": "“代表性”指看法能代表一类人的共同观点，“缺少代表性”符合句意。", "食欲": "语义：食欲指人对食物的欲望，看法不能有食欲。", "颜值": "语域：颜值是口语和网络用语，不用于书面评价看法。", "地址": "语义：地址指位置信息，看法没有地址。"}, "sentence_index": 6, "correct_answer": "代表性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双鞋的代表性很好，穿了三年也没坏。", "explanation": "这里应该用〈耐用性〉。代表性指样本或对象能反映总体的性质，不指物品的耐用程度。"}, {"text": "这辆车的代表性很快，一分钟能跑两百公里。", "explanation": "这里应该用〈速度〉。代表性不用来说事物运行的快慢。"}, {"text": "这节电池的代表性很大，能用一整天。", "explanation": "这里应该用〈电量〉。代表性不指电池储存的能量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次调查的样本不有代表性。", "corrected_sentence": "这次调查的样本很有代表性。", "error_description": "错误在于“很”写成了“不”。“不有代表性”是否定，句意是肯定的，应说“很有代表性”。“不有”不成词，否定“有”要说“没有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这组样本很代表性，可以反映全市的情况。", "corrected_sentence": "这组样本很有代表性，可以反映全市的情况。", "error_description": "错误在于漏掉了“有”。应说“很有代表性”，直接说“很代表性”不符合汉语习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
