INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91785, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回到原来的地方。", "primary_collocate": null, "pronunciation": "huí huán", "ipa": "xweɪ³⁵ xwan³⁵", "syllable_count": 2, "sentences": [{"text": "他离开家乡三年，今天终于回还。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "燕子秋天南去，春天又回还。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船出海三天，平安回还了。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那支远征队出发后，就再也没有回还。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雁每年春天都会回还北方。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水向东流，不会回还。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游子思念故乡，总盼着回还故里。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅人回还家中，已是深夜。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离家多年的老人，终于回还故土。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们完成任务，全部回还营地。", "target_word": "回还", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "回还：回到原来所在的地方，多指故乡、原处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33259699-dfd2-43c8-bf62-e169fa2186e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91785, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回还", "is_correct": true, "explanation": "回还：回到家乡，与“离开家乡三年”前后呼应。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“出发”指动身前往，与“离开家乡三年”之后又“今天终于”的情境相矛盾。"}, {"text": "返航", "is_correct": false, "explanation": "搭配：“返航”多用于飞机、船只，一般不说人“返航”回家。"}, {"text": "成长", "is_correct": false, "explanation": "语义：“成长”指生长发育，与“离开家乡三年”后回到故乡的语境无关。"}], "explanations": {"回还": "回还：回到家乡，与“离开家乡三年”前后呼应。", "出发": "语义：“出发”指动身前往，与“离开家乡三年”之后又“今天终于”的情境相矛盾。", "返航": "搭配：“返航”多用于飞机、船只，一般不说人“返航”回家。", "成长": "语义：“成长”指生长发育，与“离开家乡三年”后回到故乡的语境无关。"}, "sentence_index": 0, "correct_answer": "回还"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我借的那本书已经回还给图书馆了。", "explanation": "这里应该用〈归还〉。回还是不及物动词，表示回到原处，不能带“书”作宾语，也不能带“给”；归还用于把借来的东西交还原主。"}, {"text": "他一直没有回还我的消息。", "explanation": "这里应该用〈回复〉。回还不能以“消息”为宾语；回复用于答复信息或问题。"}, {"text": "他决心用优异的成绩回还父母的养育之恩。", "explanation": "这里应该用〈回报〉。回还不能带“养育之恩”作宾语；回报用于以行动感谢、报答别人的恩情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91785, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回还", "is_correct": true, "explanation": "回还：回到故里，与“思念故乡”“总盼着”的思乡语境相合。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“盼着离开故里”与思念故里的语境相悖，句意不通。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：“逃离”指摆脱、躲开，与“总盼着……故里”的思乡之情相反。"}, {"text": "迁徙", "is_correct": false, "explanation": "搭配：“迁徙”多指人群或动物大规模移居，不说“迁徙故里”。"}], "explanations": {"回还": "回还：回到故里，与“思念故乡”“总盼着”的思乡语境相合。", "离开": "语义：“盼着离开故里”与思念故里的语境相悖，句意不通。", "逃离": "语义：“逃离”指摆脱、躲开，与“总盼着……故里”的思乡之情相反。", "迁徙": "搭配：“迁徙”多指人群或动物大规模移居，不说“迁徙故里”。"}, "sentence_index": 6, "correct_answer": "回还"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把孩子回还了家。", "explanation": "这里应该用〈送回〉。回还是不及物动词，不能带“把”字宾语；使人回到某处要说“送回”。"}, {"text": "他常常回还那段难忘的往事。", "explanation": "这里应该用〈回味〉。回还只表示回到原处，不能以“往事”为宾语；回味指回想过去的事情。"}, {"text": "工人认真地回还这台机器。", "explanation": "这里应该用〈修理〉。回还不能以“机器”为宾语；修理指使器物恢复正常。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于把回还故乡。", "corrected_sentence": "他终于回还故乡。", "error_description": "误加“把”：“把”字句要求处置某个对象，“回还”表示人自身回到原处，不能用“把”；应删去“把”，说“他终于回还故乡”，处所直接放在“回还”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位学者从海外回还着，还带回许多资料。", "corrected_sentence": "那位学者从海外回还了，还带回许多资料。", "error_description": "错误在“回还”后用了“着”。回还表示一次性完成的动作，应用“了”表示完成；“着”表示持续状态，与此处不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
