INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91787, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不无是说，有一点，不是一点都没有。", "primary_collocate": null, "pronunciation": "bù wú", "ipa": "pu˥˩ u˧˥", "syllable_count": 2, "sentences": [{"text": "你说的话不无道理。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这次考试不无担心。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事和他不无关系。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息，她不无得意。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做对身体不无好处。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开家乡，他心里不无遗憾。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不无骄傲地说出了自己的成绩。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的意见对我不无帮助。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着孩子长大，她不无感慨。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法不无风险，你要想好。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "不无：不是没有，多少有一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c68a36c9-e59c-427d-8e93-883fc38f78dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不无", "is_correct": true, "explanation": "正确：「不无道理」表示“不是没有道理，有一定道理”，符合句意。"}, {"text": "很", "is_correct": false, "explanation": "搭配：「道理」前要有「有」，「很」不能直接修饰「道理」，应说「很有道理」。"}, {"text": "也", "is_correct": false, "explanation": "语法：「也」是副词，后面缺少动词「有」，「也道理」不成立，应说「也有道理」。"}, {"text": "太", "is_correct": false, "explanation": "搭配：「太」后不能直接接名词「道理」，应说「太有道理」。"}], "explanations": {"不无": "正确：「不无道理」表示“不是没有道理，有一定道理”，符合句意。", "很": "搭配：「道理」前要有「有」，「很」不能直接修饰「道理」，应说「很有道理」。", "也": "语法：「也」是副词，后面缺少动词「有」，「也道理」不成立，应说「也有道理」。", "太": "搭配：「太」后不能直接接名词「道理」，应说「太有道理」。"}, "sentence_index": 0, "correct_answer": "不无"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对结果不无满意，所以一句好话都没说。", "explanation": "语义：〈不无〉表示“有一点满意”，与“一句好话都没说”的结果矛盾；这里应该用〈毫不〉或改变后半句。"}, {"text": "这个想法不无可取之处，可我一点价值都看不出来，应该放弃。", "explanation": "这里应该用〈毫无〉。〈不无〉表示“有一点可取之处”，与后半句“一点价值都看不出来”的意思直接矛盾。"}, {"text": "这件事和他不无关系，他完全是局外人。", "explanation": "这里应该用〈毫无〉。〈不无关系〉表示“有一定关系”，与“完全是局外人”的意思直接矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不无", "is_correct": true, "explanation": "正确：「不无骄傲」表示“不是没有骄傲，带着一些骄傲”，符合句意。"}, {"text": "不断", "is_correct": false, "explanation": "体貌：「不断」表示反复或持续，与「说出了」这一次完成的动作不合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示次数少，与只说了一次成绩的语境冲突。"}, {"text": "反复", "is_correct": false, "explanation": "体貌：「反复」表示多次重复，句中「说出了」是单次完成，不合。"}], "explanations": {"不无": "正确：「不无骄傲」表示“不是没有骄傲，带着一些骄傲”，符合句意。", "不断": "体貌：「不断」表示反复或持续，与「说出了」这一次完成的动作不合。", "偶尔": "语义：「偶尔」表示次数少，与只说了一次成绩的语境冲突。", "反复": "体貌：「反复」表示多次重复，句中「说出了」是单次完成，不合。"}, "sentence_index": 6, "correct_answer": "不无"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个办法不无风险，所以绝对安全，你放心用吧。", "explanation": "这里应该用〈毫无〉。〈不无风险〉表示“有一些风险”，与“绝对安全”的意思直接矛盾。"}, {"text": "这件事不无疑问是他的错。", "explanation": "这里应该用〈毫无〉（毫无疑问）。「是他的错」语气确定，〈不无〉表示“有一点疑问”，两者冲突。"}, {"text": "这个决定他不无后悔，可心里一点懊悔都没有。", "explanation": "这里应该用〈毫无〉。〈不无〉表示“有一点后悔”，与后半句“一点懊悔都没有”的意思直接矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个建议很不无参考价值。", "corrected_sentence": "这个建议不无参考价值。", "error_description": "错误在「很」。「不无」本身已含“不是没有、有一点”的意思，不能再被「很」修饰。应去掉「很」，说「这个建议不无参考价值」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次讨论不无有收获。", "corrected_sentence": "这次讨论不无收获。", "error_description": "错误在「有」。「不无」本身已含“有一点”的意思，后面不能再加「有」。应去掉「有」，写成「这次讨论不无收获」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
