INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91788, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示不是没有，多少有一点。", "primary_collocate": null, "pronunciation": "bù wú", "ipa": "pu˥˩ u˧˥", "syllable_count": 2, "sentences": [{"text": "这个想法不无可取之处。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对朋友的话不无怀疑。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对未来不无担忧。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败和他的粗心不无关系。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不无自豪地介绍了家乡。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多喝水对治疗感冒不无帮助。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老朋友，他不无激动。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜不无特色。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的批评对我不无影响。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，大家心里不无失望。", "target_word": "不无", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "不无：副词，不是没有，多少有一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c68a36c9-e59c-427d-8e93-883fc38f78dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不无", "is_correct": true, "explanation": "正确：「不无可取之处」表示“不是没有可取之处，有一些优点”，符合句意。"}, {"text": "很", "is_correct": false, "explanation": "搭配：「可取之处」是名词短语，「很」不能直接修饰它，句子不成立。"}, {"text": "也", "is_correct": false, "explanation": "语法：「也」是副词，后面缺少动词「有」，「也可取之处」不成立。"}, {"text": "最", "is_correct": false, "explanation": "搭配：「最」不能修饰名词性的「可取之处」，句子不成立。"}], "explanations": {"不无": "正确：「不无可取之处」表示“不是没有可取之处，有一些优点”，符合句意。", "很": "搭配：「可取之处」是名词短语，「很」不能直接修饰它，句子不成立。", "也": "语法：「也」是副词，后面缺少动词「有」，「也可取之处」不成立。", "最": "搭配：「最」不能修饰名词性的「可取之处」，句子不成立。"}, "sentence_index": 0, "correct_answer": "不无"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对他的诚意不无怀疑，可是一点都不怀疑。", "explanation": "这里应该用〈毫无〉。〈不无〉表示“有一点怀疑”，与后半句“一点都不怀疑”的意思直接矛盾。"}, {"text": "他对这个计划不无兴趣，却一点兴趣都没有。", "explanation": "这里应该用〈毫无〉。〈不无〉表示“有一点兴趣”，与后半句“一点兴趣都没有”的意思直接矛盾。"}, {"text": "这次失败跟他的粗心不无关联，但两者完全没有联系。", "explanation": "这里应该用〈毫无〉。〈不无〉表示“有一点关联”，与后半句“完全没有联系”的意思直接矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不无", "is_correct": true, "explanation": "正确：「不无激动」表示“不是没有激动，有一些激动”，符合句意。"}, {"text": "被", "is_correct": false, "explanation": "语法：「被」表示被动，后面需接施事和动词，「他被激动」不成立。"}, {"text": "得", "is_correct": false, "explanation": "语法：「激动得」后需接补语，「得」不能单独作句末成分，句子不完整。"}, {"text": "的", "is_correct": false, "explanation": "语法：「的」是结构助词，「他的激动」只是名词短语，句中缺少谓语，句子不成立。"}], "explanations": {"不无": "正确：「不无激动」表示“不是没有激动，有一些激动”，符合句意。", "被": "语法：「被」表示被动，后面需接施事和动词，「他被激动」不成立。", "得": "语法：「激动得」后需接补语，「得」不能单独作句末成分，句子不完整。", "的": "语法：「的」是结构助词，「他的激动」只是名词短语，句中缺少谓语，句子不成立。"}, "sentence_index": 6, "correct_answer": "不无"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个结果我不无意外，可我一点也不觉得惊讶。", "explanation": "这里应该用〈毫不〉。〈不无〉表示“有一点意外”，与后半句“一点也不觉得惊讶”的意思直接矛盾。"}, {"text": "这次失败和他的粗心不无关系，全怪天气不好。", "explanation": "这里应该用〈毫无〉。〈不无关系〉表示“有一定关系”，与“全怪天气不好”的意思直接矛盾。"}, {"text": "这家店的菜不无特色，和别家完全一样。", "explanation": "这里应该用〈毫无〉。〈不无特色〉表示“有一些特色”，与“和别家完全一样”的意思直接矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方案很不无优点。", "corrected_sentence": "这个方案不无优点。", "error_description": "错误在「很」。「不无」本身已含“不是没有、有一点”的意思，不能再被「很」修饰。应去掉「很」，说「这个方案不无优点」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行不无了遗憾。", "corrected_sentence": "这次旅行不无遗憾。", "error_description": "“了”不能插在“不无”和“遗憾”之间；“不无”是副词，应直接修饰名词“遗憾”。应说“这次旅行不无遗憾”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
