INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91789, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以看的书，有很多本。", "primary_collocate": null, "pronunciation": "tú shū", "ipa": "tʰu˧˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "书架上放满了图书。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有很多图书。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的图书可以免费看。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢看各种图书。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的图书太多了。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在教室里看图书。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些图书我都看完了。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她带了很多图书去旅行。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要弄坏图书。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我在家看图书。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批", "label": "量词"}, {"form": "图书馆", "label": "复合"}, {"form": "图书室", "label": "复合"}, {"form": "圖書", "label": "繁体"}], "register": "书面", "sense_fingerprint": "可以看的很多本书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baee0e88-f68e-4a39-b1f8-d15a57ebea04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91789, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图书", "is_correct": true, "explanation": "正确：书架上放的是可以看的书，“放满”与图书搭配。"}, {"text": "面条", "is_correct": false, "explanation": "语义：面条是食物，不是可以放在书架上的东西，与语境不符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“放满”不能接“空气”，空气无法装在书架上。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“放满”接物件，“水”应说“装满”，不能说“放满水”。"}], "explanations": {"图书": "正确：书架上放的是可以看的书，“放满”与图书搭配。", "面条": "语义：面条是食物，不是可以放在书架上的东西，与语境不符。", "空气": "搭配：“放满”不能接“空气”，空气无法装在书架上。", "水": "搭配：“放满”接物件，“水”应说“装满”，不能说“放满水”。"}, "sentence_index": 0, "correct_answer": "图书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都去图书借书。", "explanation": "这里应该用〈图书馆〉。图书指可看的书，不指借书的地方。"}, {"text": "孩子们在草地上踢图书。", "explanation": "这里应该用〈足球〉。图书是可以看的书，不能用来踢。"}, {"text": "孩子们在吃图书。", "explanation": "这里应该用〈饼干〉。图书是可以看的书，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图书", "is_correct": true, "explanation": "正确：“看完”与可看的书搭配，句子通顺。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“看完”不搭配“饭”，应说“吃完”。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“看”不搭配“歌”，应说“听”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能用来“看”。"}], "explanations": {"图书": "正确：“看完”与可看的书搭配，句子通顺。", "饭": "搭配：“看完”不搭配“饭”，应说“吃完”。", "歌": "搭配：“看”不搭配“歌”，应说“听”。", "蛋糕": "语义：蛋糕是食物，不能用来“看”。"}, "sentence_index": 6, "correct_answer": "图书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天浇图书。", "explanation": "这里应该用〈花〉。图书是可以看的书，不能用来浇灌。"}, {"text": "每天早上都有人把图书送到家门口，上面有昨天的新闻。", "explanation": "这里应该用〈报纸〉。图书指书籍，不指每天送来的报纸。"}, {"text": "我们晚上去电影院看图书。", "explanation": "这里应该用〈电影〉。图书指可以看的书，不指电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家里有一座图书。", "corrected_sentence": "他家里有一批图书。", "error_description": "量词错误：“图书”指可看的书，量词应用“批”或“本”，“座”用于山、楼等大型物体，不能用于图书。正确说法：他家里有一批图书。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些图书们都很旧了。", "corrected_sentence": "这些图书都很旧了。", "error_description": "“这些”已表示复数，“图书”后不能再加“们”。正确说法：这些图书都很旧了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
