INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书籍的总称。", "primary_collocate": null, "pronunciation": "tú shū", "ipa": "tʰu˧˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "学校买了很多新图书。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书是知识的来源。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门卖儿童图书。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书的价格不太高。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们按类别整理图书。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些图书都是捐来的。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的图书每年都会增加。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把图书分给同学们。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书出版需要很多时间。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上买了一批图书。", "target_word": "图书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批", "label": "量词"}, {"form": "图书馆", "label": "复合"}, {"form": "图书室", "label": "复合"}, {"form": "圖書", "label": "繁体"}], "register": "书面", "sense_fingerprint": "书籍的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baee0e88-f68e-4a39-b1f8-d15a57ebea04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图书", "is_correct": true, "explanation": "正确：图书是书籍的总称，“买了很多新图书”说法自然。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“买”不能和“空气”搭配，学校不能买空气。"}, {"text": "理想", "is_correct": false, "explanation": "语义：理想是抽象的想法，不是可以买的东西。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“买”不能接“阳光”，阳光不能被购买。"}], "explanations": {"图书": "正确：图书是书籍的总称，“买了很多新图书”说法自然。", "空气": "搭配：“买”不能和“空气”搭配，学校不能买空气。", "理想": "语义：理想是抽象的想法，不是可以买的东西。", "阳光": "搭配：“买”不能接“阳光”，阳光不能被购买。"}, "sentence_index": 0, "correct_answer": "图书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天下午都去图书看书。", "explanation": "这里应该用〈图书馆〉。图书指书籍的总称，不指借书、看书的地方。"}, {"text": "老师把图书贴在墙上，让大家看每天的安排。", "explanation": "这里应该用〈课表〉。图书指书籍，不指写着安排的表格。"}, {"text": "我每天早上都给花园里的图书浇水。", "explanation": "这里应该用〈花〉。图书指书籍，不指可以浇水的植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图书", "is_correct": true, "explanation": "正确：“学校的图书”指学校的书籍，“每年都会增加”符合语义。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳的数量不会随学校而增加。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不属于学校，数量不会因学校而增加。"}, {"text": "体重", "is_correct": false, "explanation": "语义：学校没有“体重”，“学校的体重”说不通。"}], "explanations": {"图书": "正确：“学校的图书”指学校的书籍，“每年都会增加”符合语义。", "太阳": "语义：太阳的数量不会随学校而增加。", "月亮": "语义：月亮不属于学校，数量不会因学校而增加。", "体重": "语义：学校没有“体重”，“学校的体重”说不通。"}, "sentence_index": 6, "correct_answer": "图书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我常去图书买书。", "explanation": "这里应该用〈书店〉。图书指书籍，不指卖书的地方。"}, {"text": "我每天早上用图书来刷牙。", "explanation": "这里应该用〈牙刷〉。图书指书籍，不指刷牙的工具。"}, {"text": "孩子们每天中午去图书吃饭。", "explanation": "这里应该用〈食堂〉。图书指书籍，不指吃饭的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条图书已经整理好了。", "corrected_sentence": "这批图书已经整理好了。", "error_description": "量词错误：“图书”多用“批”或“本”，“条”多用于细长物体，不能用于图书。正确说法：这批图书已经整理好了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多图书们都是新的。", "corrected_sentence": "很多图书都是新的。", "error_description": "“很多”已表示复数，“图书”后不能再加“们”。正确说法：很多图书都是新的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
