INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91794, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "放在心上；介意。", "primary_collocate": null, "pronunciation": "zài yì", "ipa": "tsaɪ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "别人怎么说，我一点也不在意。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迟到了，可是我不在意。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不在意的话，我就坐这儿了。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不在意别人的眼光。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小事不用太在意。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话直，你别在意。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不在意吃什么，你决定吧。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟弄坏了我的杯子，我没在意。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批评了他，他好像不太在意。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱多钱少我都不在意。", "target_word": "在意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在心上，介意（多用于否定）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa83287-1e2b-4500-b69a-3fd58334cdca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在意", "is_correct": true, "explanation": "“在意”指放在心上、介意，这里说“一点也不在意”，即完全不介意别人的说法。"}, {"text": "学习", "is_correct": false, "explanation": "语义：“学习”指获取知识或技能，不能用来表示对别人说法的态度。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复坏了的东西，与“别人怎么说”没有关系。"}, {"text": "观察", "is_correct": false, "explanation": "搭配：“观察”的对象是人、现象或事物，“别人怎么说”这样的言论不能作为观察的对象。"}], "explanations": {"在意": "“在意”指放在心上、介意，这里说“一点也不在意”，即完全不介意别人的说法。", "学习": "语义：“学习”指获取知识或技能，不能用来表示对别人说法的态度。", "修理": "语义：“修理”指修复坏了的东西，与“别人怎么说”没有关系。", "观察": "搭配：“观察”的对象是人、现象或事物，“别人怎么说”这样的言论不能作为观察的对象。"}, "sentence_index": 0, "correct_answer": "在意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在意到门铃响了。", "explanation": "这里应该用〈注意到〉。“注意到”表示察觉到某事，“在意”表示把事情放在心上、介意，不能用来表示察觉。"}, {"text": "请在意前方的路况。", "explanation": "这里应该用〈注意〉。提醒对方留神路况要说“注意”，“在意”表示把事情放在心上、介意，不用于这种提醒。"}, {"text": "请在意脚下的台阶。", "explanation": "这里应该用〈小心〉。提醒别人留神脚下要说“小心”，“在意”不用于这种提醒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在意", "is_correct": true, "explanation": "“在意”指介意，这里“不在意吃什么”是说对吃什么无所谓，由对方决定。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”要求具体的物品作宾语，不能接“吃什么”这样的疑问短语。"}, {"text": "咨询", "is_correct": false, "explanation": "语域：“咨询”偏正式，多用于向专业人员请教，与这句日常口语的语境不协调。"}, {"text": "提醒", "is_correct": false, "explanation": "配价：“提醒”要有提醒的对象和内容，“我不提醒吃什么”缺少提醒的对象。"}], "explanations": {"在意": "“在意”指介意，这里“不在意吃什么”是说对吃什么无所谓，由对方决定。", "购买": "配价：“购买”要求具体的物品作宾语，不能接“吃什么”这样的疑问短语。", "咨询": "语域：“咨询”偏正式，多用于向专业人员请教，与这句日常口语的语境不协调。", "提醒": "配价：“提醒”要有提醒的对象和内容，“我不提醒吃什么”缺少提醒的对象。"}, "sentence_index": 6, "correct_answer": "在意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出门要在意小偷。", "explanation": "这里应该用〈提防〉。“提防”表示防备坏人，“在意”只表示放在心上，不能表示防范。"}, {"text": "下雨路滑，要在意摔倒。", "explanation": "这里应该用〈当心〉。“当心”用于提醒对方留神，“在意”表示放在心上、介意，不能这样提醒。"}, {"text": "晚上要在意陌生人敲门。", "explanation": "这里应该用〈警惕〉。“警惕”表示防范、提高戒备，“在意”只表示放在心上，不能表示防范。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从不在意了别人的评价。", "corrected_sentence": "他从不在意别人的评价。", "error_description": "“在意”后面不能加“了”。错误形式是“从不在意了”，正确形式是“从不在意”。否定句中的“在意”表示一种态度，不表示已经完成的动作，所以不用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件小事，我一点也不在意着。", "corrected_sentence": "这件小事，我一点也不在意。", "error_description": "“在意”后面不能加“着”。错误形式是“一点也不在意着”，正确形式是“一点也不在意”。否定句中的“在意”表示态度，不用“着”表示动作的持续。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
