INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "主要的目的和意图。", "primary_collocate": null, "pronunciation": "zōng zhǐ", "ipa": "tsʊŋ˥ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司的宗旨是为客人服务。", "target_word": "宗旨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会的宗旨很清楚。", "target_word": "宗旨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校以教好学生为宗旨。", "target_word": "宗旨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要记住活动的宗旨。", "target_word": "宗旨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的宗旨是质量第一。", "target_word": "宗旨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话没有偏离会议的宗旨。", "target_word": "宗旨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸的宗旨是说真话。", "target_word": "宗旨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务的宗旨是让客人高兴。", "target_word": "宗旨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先说说你们的宗旨。", "target_word": "宗旨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组织的宗旨是帮助穷人。", "target_word": "宗旨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "办学宗旨", "label": "复合"}], "register": "书面", "sense_fingerprint": "组织或活动的主要目的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baee0e88-f68e-4a39-b1f8-d15a57ebea04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宗旨", "is_correct": true, "explanation": "正确。“宗旨”指主要的目的和意图，“公司的宗旨”与“为客人服务”相符。"}, {"text": "本领", "is_correct": false, "explanation": "搭配：“本领”指个人的能力，不能说“公司的本领”，句子不通。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是联系用的工具，不是公司要达到的目的，与“为客人服务”不合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是商品的金额，不能作为公司的主要目的。"}], "explanations": {"宗旨": "正确。“宗旨”指主要的目的和意图，“公司的宗旨”与“为客人服务”相符。", "本领": "搭配：“本领”指个人的能力，不能说“公司的本领”，句子不通。", "电话": "语义：电话是联系用的工具，不是公司要达到的目的，与“为客人服务”不合。", "价格": "语义：价格是商品的金额，不能作为公司的主要目的。"}, "sentence_index": 0, "correct_answer": "宗旨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司有一只宗旨，大家都要记住。", "explanation": "这里应该用〈个〉。“宗旨”是抽象的概念，量词用“个”；“只”多用于动物或成对物品中的一个，不能用于宗旨。"}, {"text": "这家店有一把宗旨，大家都知道。", "explanation": "这里应该用〈个〉。“把”用于有柄的器具，不能用于抽象的宗旨。"}, {"text": "我们班有一颗宗旨，大家都记得。", "explanation": "这里应该用〈个〉。“颗”用于粒状的小东西，不用于抽象的宗旨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宗旨", "is_correct": true, "explanation": "正确。“宗旨”指主要的目的和意图，“报纸的宗旨”与“说真话”相符。"}, {"text": "版面", "is_correct": false, "explanation": "语义：版面指报纸的版式安排，不是报纸要达到的目的，与“说真话”不合。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的身体特征，“报纸的身高”不通，也不能是“说真话”的内容。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体指字的形状，“说真话”不能是字体的内容。"}], "explanations": {"宗旨": "正确。“宗旨”指主要的目的和意图，“报纸的宗旨”与“说真话”相符。", "版面": "语义：版面指报纸的版式安排，不是报纸要达到的目的，与“说真话”不合。", "身高": "语义：身高是人的身体特征，“报纸的身高”不通，也不能是“说真话”的内容。", "字体": "语义：字体指字的形状，“说真话”不能是字体的内容。"}, "sentence_index": 6, "correct_answer": "宗旨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的宗旨每天早早来上班。", "explanation": "这里把“宗旨”当成了人来用。“宗旨”是抽象的目的和意图，不能去上班，“上班”的主语应是员工这样的人。"}, {"text": "他的宗旨很饿，总想吃饭。", "explanation": "这里把“饿”用于宗旨。“饿”形容人想吃东西的感觉，“宗旨”不会饿。"}, {"text": "他的宗旨很急，总是催大家。", "explanation": "这里应该用〈脾气〉。“宗旨”是目的和意图，不能用“急”来形容；“急”形容的是脾气和性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校有一只宗旨，就是培养人才。", "corrected_sentence": "学校有一个宗旨，就是培养人才。", "error_description": "“宗旨”前的量词应用“个”，不能用“只”（“只”多用于动物或成对物品中的一个）。正确说法：学校有一个宗旨，就是培养人才。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我宗旨是诚信经营。", "corrected_sentence": "我的宗旨是诚信经营。", "error_description": "“宗旨”前的人称代词需要结构助词“的”，应说“我的宗旨”；漏掉“的”不符合习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
