INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91799, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "他国是别的国家。", "primary_collocate": null, "pronunciation": "tā guó", "ipa": "tʰa˥ kwo˧˥", "syllable_count": 2, "sentences": [{"text": "他从小在他国长大。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人喜欢到他国旅行。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他国的天气和这里不同。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家常常帮助他国的孩子。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他国的学生也来参加比赛。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道他国的人怎么过年。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在他国工作，很少回家。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王有一位住在他国的朋友。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家应该了解他国的历史。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的画卖给了他国的商人。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "他国：别的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c68a36c9-e59c-427d-8e93-883fc38f78dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91799, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "他国", "is_correct": true, "explanation": "“他国”指别的国家，可以作“在……长大”的处所，符合句意。"}, {"text": "同学", "is_correct": false, "explanation": "搭配：“长大”需要处所词，不能用人物名词“同学”。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“历史”不能作“在……长大”的场所。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”不是处所，不能用于“在……长大”之后。"}], "explanations": {"他国": "“他国”指别的国家，可以作“在……长大”的处所，符合句意。", "同学": "搭配：“长大”需要处所词，不能用人物名词“同学”。", "历史": "语义：“历史”不能作“在……长大”的场所。", "语言": "语义：“语言”不是处所，不能用于“在……长大”之后。"}, "sentence_index": 0, "correct_answer": "他国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的书包被他国拿走了，我很着急。", "explanation": "语义：“他国”指国家，不能作为拿走东西的人，这里应该说“别人”。"}, {"text": "我把他国借给同学用了一天。", "explanation": "语义：“他国”指别的国家，不是可以借给别人用的东西。"}, {"text": "他国的超市就在我家楼下。", "explanation": "语义：“他国”指国外，不能用来指家门口这样近的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91799, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他国", "is_correct": true, "explanation": "“他国”指别的国家，可以作“在……工作”的处所，符合句意。"}, {"text": "时代", "is_correct": false, "explanation": "语义：“时代”不是处所，不能用于“在……工作”之后。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”是抽象属性，不能作“工作”的场所。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“在……工作”需要处所词，不能用“感情”。"}], "explanations": {"他国": "“他国”指别的国家，可以作“在……工作”的处所，符合句意。", "时代": "语义：“时代”不是处所，不能用于“在……工作”之后。", "性格": "语义：“性格”是抽象属性，不能作“工作”的场所。", "感情": "搭配：“在……工作”需要处所词，不能用“感情”。"}, "sentence_index": 6, "correct_answer": "他国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支笔不是我的，请你还给他国。", "explanation": "语义：“他国”指国家，不能作为归还东西的对象，这里应该说“他”。"}, {"text": "我的作业本不见了，可能被他国放进了书包。", "explanation": "语义：“他国”指国家，不能作为放东西的人，这里应该说“别人”。"}, {"text": "妈妈让我去他国买一瓶酱油，五分钟就回来。", "explanation": "语义：“他国”指别的国家，不是五分钟就能来回买酱油的地方，这里应该说“楼下的商店”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的朋友在他国们工作很多年了。", "corrected_sentence": "我的朋友在他国工作很多年了。", "error_description": "“他国”后面不能加“们”，“们”只用于指人的名词或代词。应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师是从他国的。", "corrected_sentence": "这位老师是从他国来的。", "error_description": "“从他国”是介词短语，后面缺少动词“来”。应写成“是从他国来的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
