INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91800, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "别的国家；外国。", "primary_collocate": null, "pronunciation": "tā guó", "ipa": "tʰa˥ kwo˧˥", "syllable_count": 2, "sentences": [{"text": "他在他国生活了五年。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家的书在他国也很有名。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能干涉他国的内政。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议有很多他国的代表参加。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他国的游客来这里看风景。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打算去他国读大学。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司把产品卖到了他国。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他国的文化和我们的不一样。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在他国学会了做饭。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该尊重他国的文化和习惯。", "target_word": "他国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "他国：别的国家，外国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c68a36c9-e59c-427d-8e93-883fc38f78dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_ba