INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "他国", "is_correct": true, "explanation": "“他国”指别的国家，可以作“在……生活”的处所，符合句意。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”不是处所，不能用在“在……生活”中表示地点。"}, {"text": "同学", "is_correct": false, "explanation": "搭配：“在……生活”需要处所词，不能用人物名词“同学”。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“历史”是抽象概念，不能作“生活”的场所。"}], "explanations": {"他国": "“他国”指别的国家，可以作“在……生活”的处所，符合句意。", "语言": "语义：“语言”不是处所，不能用在“在……生活”中表示地点。", "同学": "搭配：“在……生活”需要处所词，不能用人物名词“同学”。", "历史": "语义：“历史”是抽象概念，不能作“生活”的场所。"}, "sentence_index": 0, "correct_answer": "他国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的作业还没写完，他国急得不行。", "explanation": "语义：“他国”指国家，不能作为着急的人，这里应该用“我”。"}, {"text": "妈妈在他国做饭，饭马上就好了。", "explanation": "语义：“他国”指别的国家，不能指家里的厨房，这里应该说“厨房里”。"}, {"text": "我想去他国的超市买东西，就在楼下。", "explanation": "语义：“他国”指国外，不能用来指楼下的超市这样近的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他国", "is_correct": true, "explanation": "“他国”指别的国家，可以作“卖到”的目的地，符合句意。"}, {"text": "时代", "is_correct": false, "explanation": "语义：“时代”不是地点，不能作“卖到”的目的地。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：产品可以卖到地方，不能卖到“感情”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”是抽象属性，不能作“卖到”的目的地。"}], "explanations": {"他国": "“他国”指别的国家，可以作“卖到”的目的地，符合句意。", "时代": "语义：“时代”不是地点，不能作“卖到”的目的地。", "感情": "搭配：产品可以卖到地方，不能卖到“感情”。", "性格": "语义：“性格”是抽象属性，不能作“卖到”的目的地。"}, "sentence_index": 6, "correct_answer": "他国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把伞不是我的，是他国的，请还给他。", "explanation": "语义：“他国”指别的国家，不能指个人的东西，这里应该说“别人的”。"}, {"text": "我的钥匙不在桌上，可能在他国。", "explanation": "语义：“他国”指国外，不能指家里的其他地方，这里应该说“别的地方”。"}, {"text": "我的书包被他国拿走了。", "explanation": "语义：“他国”指国家，不能作为拿走东西的人，这里应该说“别人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
