INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91801, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大声对大家说自己的想法。", "primary_collocate": null, "pronunciation": "xuān chēng", "ipa": "ɕɥɛn˥ ʈʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "小明大声宣称他不怕黑。", "target_word": "宣称", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他站起来宣称：“我一定会赢。”", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板在会上宣称要给大家加钱。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对全班宣称自己明天会带蛋糕来。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥宣称他能一口吃十个饺子。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在门口宣称谁也不能进去。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们宣称自己是这里的小主人。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当着大家的面宣称要去旅行。", "target_word": "宣称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王宣称他今年一定要学会游泳。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她高兴地宣称明天不上课。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "宣稱", "label": "繁体"}, {"form": "宣称了", "label": "体标"}, {"form": "宣称过", "label": "体标"}], "register": "通用", "sense_fingerprint": "大声对众人说出自己的想法或打算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea62575-be54-46e7-9a6e-46e7d7867e98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91801, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宣称", "is_correct": true, "explanation": "宣称指大声对众人说出自己的想法，与“大声”相符。"}, {"text": "默念", "is_correct": false, "explanation": "语义：默念是不出声地念，与“大声”矛盾。"}, {"text": "低语", "is_correct": false, "explanation": "语义：低语是小声说话，与“大声”矛盾。"}, {"text": "吞下", "is_correct": false, "explanation": "搭配：吞下的对象是食物或药物，不能与“他不怕黑”搭配。"}], "explanations": {"宣称": "宣称指大声对众人说出自己的想法，与“大声”相符。", "默念": "语义：默念是不出声地念，与“大声”矛盾。", "低语": "语义：低语是小声说话，与“大声”矛盾。", "吞下": "搭配：吞下的对象是食物或药物，不能与“他不怕黑”搭配。"}, "sentence_index": 0, "correct_answer": "宣称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她悄悄地宣称自己明天会带蛋糕来。", "explanation": "这里应该用〈说〉。宣称指大声对众人公开说出自己的想法，与私下、小声说的意思不符。"}, {"text": "妈妈宣称我快点起床。", "explanation": "这里应该用〈催促〉。宣称用于说出自己的想法或打算，不能用来对别人发出命令。"}, {"text": "她向朋友宣称明天会不会下雨。", "explanation": "这里应该用〈打听〉。宣称是说出自己的看法，不能用来询问信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宣称", "is_correct": true, "explanation": "宣称指公开说出自己的看法或打算，与“孩子们”和“自己是小主人”相符。"}, {"text": "推辞", "is_correct": false, "explanation": "语义：推辞是婉言拒绝，与“宣称自己是小主人”的主动说法相反。"}, {"text": "追问", "is_correct": false, "explanation": "搭配：追问后接问题，不能接“自己是这里的小主人”这类陈述。"}, {"text": "拆穿", "is_correct": false, "explanation": "搭配：拆穿用于揭露谎言或骗局，句中没有这样的语境。"}], "explanations": {"宣称": "宣称指公开说出自己的看法或打算，与“孩子们”和“自己是小主人”相符。", "推辞": "语义：推辞是婉言拒绝，与“宣称自己是小主人”的主动说法相反。", "追问": "搭配：追问后接问题，不能接“自己是这里的小主人”这类陈述。", "拆穿": "搭配：拆穿用于揭露谎言或骗局，句中没有这样的语境。"}, "sentence_index": 6, "correct_answer": "宣称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师当众宣称了他。", "explanation": "这里应该用〈表扬〉。宣称只能带说出的看法或打算，不能直接带人作宾语。"}, {"text": "老师向我们宣称了这道题。", "explanation": "这里应该用〈讲解〉。宣称用于公开表明看法或打算，不能用来讲解题目。"}, {"text": "他在晚会上宣称了一首曲子。", "explanation": "这里应该用〈演奏〉。宣称表示说出看法，不能用于演奏乐曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班长当众了宣称自己这次一定能赢。", "corrected_sentence": "班长当众宣称自己这次一定能赢。", "error_description": "错误形式为“了宣称”，正确形式为“宣称”。“了”不能放在动词前，正确句子中“宣称”前不加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "裁判当场宣称得这次比赛无效。", "corrected_sentence": "裁判当场宣称这次比赛无效。", "error_description": "错误形式为“宣称得”，正确形式为“宣称”。“得”是补语标记，不能直接加在“宣称”后面，应说“当场宣称这次比赛无效”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
