INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91802, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公开地声明、表示。", "primary_collocate": null, "pronunciation": "xuān chēng", "ipa": "ɕɥɛn˥ ʈʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "政府宣称不会提高价格。", "target_word": "宣称", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "中国队宣称要拿第一名。", "target_word": "宣称", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司宣称新手机明年上市。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店宣称所有菜都很新鲜。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们宣称这个药对身体很好。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广告宣称这种茶可以帮助睡觉。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校方宣称从下个月开始放假。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸上宣称这个城市是最安全的。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位歌手宣称自己不再唱歌了。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店宣称今天所有东西都打八折。", "target_word": "宣称", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "宣稱", "label": "繁体"}, {"form": "宣称了", "label": "体标"}, {"form": "宣称过", "label": "体标"}], "register": "书面", "sense_fingerprint": "公司、机构或个人公开声明、表示某种说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea62575-be54-46e7-9a6e-46e7d7867e98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91802, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宣称", "is_correct": true, "explanation": "宣称指公开声明，与“政府”和“不会提高价格”的表态相符。"}, {"text": "咨询", "is_correct": false, "explanation": "搭配：咨询的对象是信息或意见，不能与“不会提高价格”这类陈述搭配。"}, {"text": "乞求", "is_correct": false, "explanation": "语义：乞求是恳切请求，政府公开表态时不会用乞求的语气。"}, {"text": "批评", "is_correct": false, "explanation": "配价：批评需要带受批评的人或行为，不能直接带“不会提高价格”。"}], "explanations": {"宣称": "宣称指公开声明，与“政府”和“不会提高价格”的表态相符。", "咨询": "搭配：咨询的对象是信息或意见，不能与“不会提高价格”这类陈述搭配。", "乞求": "语义：乞求是恳切请求，政府公开表态时不会用乞求的语气。", "批评": "配价：批评需要带受批评的人或行为，不能直接带“不会提高价格”。"}, "sentence_index": 0, "correct_answer": "宣称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店主悄悄宣称今天打折。", "explanation": "这里应该用〈说〉。宣称指公开地声明，与私下、小声说话的意思不符。"}, {"text": "校长宣称同学们快回家。", "explanation": "这里应该用〈催促〉。宣称用于公开表明看法或打算，不能用来对别人发出催促。"}, {"text": "店员向客人宣称了价格。", "explanation": "这里应该用〈介绍〉。宣称用于公开表明看法或打算，不能用来介绍具体价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宣称", "is_correct": true, "explanation": "宣称指公开表明，与“校方”和“从下个月开始放假”的通知相符。"}, {"text": "询问", "is_correct": false, "explanation": "搭配：询问后接问题，不能接“从下个月开始放假”这类陈述。"}, {"text": "抗议", "is_correct": false, "explanation": "语义：抗议是表示反对，与学校宣布放假的陈述不相符。"}, {"text": "祈祷", "is_correct": false, "explanation": "语义：祈祷是向神灵祷告，与学校的公开通知不相符。"}], "explanations": {"宣称": "宣称指公开表明，与“校方”和“从下个月开始放假”的通知相符。", "询问": "搭配：询问后接问题，不能接“从下个月开始放假”这类陈述。", "抗议": "语义：抗议是表示反对，与学校宣布放假的陈述不相符。", "祈祷": "语义：祈祷是向神灵祷告，与学校的公开通知不相符。"}, "sentence_index": 6, "correct_answer": "宣称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "记者宣称：今天放假吗？", "explanation": "这里应该用〈询问〉。宣称是对外陈述看法或打算，不能用来提问。"}, {"text": "班长在班会上宣称了一个笑话。", "explanation": "这里应该用〈讲〉。宣称用于公开表明看法或打算，不能用来讲笑话。"}, {"text": "他宣称地跑了一圈。", "explanation": "这里不能用〈宣称〉修饰身体动作。宣称指公开表明看法，不能用来形容身体动作，应改用〈慢慢〉这类动作副词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司宣称地产品质量很好。", "corrected_sentence": "这家公司宣称产品质量很好。", "error_description": "错误形式为在“宣称”后多加“地”，正确形式为“宣称”后直接接所声明的内容。“地”用于修饰动词的状语，“宣称”后接的是陈述内容，不需要加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校宣称宣称下周一起开始收费。", "corrected_sentence": "学校宣称下周一起开始收费。", "error_description": "错误形式为“宣称宣称”，正确形式为只用一个“宣称”。同一个动词不能重复出现。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
