INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91805, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书最外面的那一页。", "primary_collocate": null, "pronunciation": "fēng miàn", "ipa": "fəŋ˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这本书的封面是蓝色的。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的封面太薄了，很容易破。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "封面上画着一只可爱的小猫。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这本书的封面，所以买了它。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手摸了摸旧书的封面。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的封面破了，需要用胶带贴一下。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典的封面很硬，不容易坏。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在笔记本的封面上写了自己的名字。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻开封面，里面有一张照片。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们给课本的封面包上了漂亮的纸。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封面设计", "label": "复合"}, {"form": "封面人物", "label": "复合"}], "register": "中性", "sense_fingerprint": "书本最外层的那一页，即书皮正面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea62575-be54-46e7-9a6e-46e7d7867e98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91805, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "封面", "is_correct": true, "explanation": "封面：书最外面的那一页，即书皮正面。"}, {"text": "方面", "is_correct": false, "explanation": "fāng（第一声）与 fēng（第一声）韵母不同（ang 与 eng），意思是方向、方面。"}, {"text": "粉面", "is_correct": false, "explanation": "fěn（第三声）与 fēng（第一声）声调和韵母（en 与 eng）都不同，意思是米粉做的面条。"}, {"text": "发面", "is_correct": false, "explanation": "fā（第一声）与 fēng（第一声）声母相同，韵母不同，意思是发酵面团。"}], "explanations": {"封面": "封面：书最外面的那一页，即书皮正面。", "方面": "fāng（第一声）与 fēng（第一声）韵母不同（ang 与 eng），意思是方向、方面。", "粉面": "fěn（第三声）与 fēng（第一声）声调和韵母（en 与 eng）都不同，意思是米粉做的面条。", "发面": "fā（第一声）与 fēng（第一声）声母相同，韵母不同，意思是发酵面团。"}, "sentence_index": null, "correct_answer": "封面"}, "level_3": {"options": [{"text": "封面", "is_correct": true, "explanation": "封面：书的外皮，可以是蓝色的，与句意相符。"}, {"text": "作者", "is_correct": false, "explanation": "搭配：“是蓝色的”说的是事物的颜色，作者是人，不能用来描述颜色。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架不是书的组成部分，“这本书的书架”说不通。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不属于一本书，“这本书的教室”说不通。"}], "explanations": {"封面": "封面：书的外皮，可以是蓝色的，与句意相符。", "作者": "搭配：“是蓝色的”说的是事物的颜色，作者是人，不能用来描述颜色。", "书架": "语义：书架不是书的组成部分，“这本书的书架”说不通。", "教室": "语义：教室不属于一本书，“这本书的教室”说不通。"}, "sentence_index": 0, "correct_answer": "封面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的封面一共有十章。", "explanation": "这里应该用〈章节〉。封面只是书外面的第一页，不会分成十章；分章是书的内容。"}, {"text": "翻到封面，就能看到每章的标题。", "explanation": "这里应该用〈目录〉。目录列出各章标题；封面只印书名、作者等，翻到封面看不到每章的标题。"}, {"text": "封面很长，我花了三天才读完。", "explanation": "这里应该用〈正文〉。需要花时间读完的是正文，封面只有一页，不能读三天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91805, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "封面", "is_correct": true, "explanation": "封面：书的外皮，可以很硬、不容易坏，与句意相符。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水是液体，不能说“很硬”，“墨水很硬，不容易坏”说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是气体，谈不上“很硬”，也不能说“坏”。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“很硬，不容易坏”描述物件，不能用于人，老师不能这样形容。"}], "explanations": {"封面": "封面：书的外皮，可以很硬、不容易坏，与句意相符。", "墨水": "语义：墨水是液体，不能说“很硬”，“墨水很硬，不容易坏”说不通。", "空气": "语义：空气是气体，谈不上“很硬”，也不能说“坏”。", "老师": "搭配：“很硬，不容易坏”描述物件，不能用于人，老师不能这样形容。"}, "sentence_index": 6, "correct_answer": "封面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们认真读课本的封面，一页一页地做了笔记。", "explanation": "这里应该用〈内容〉。封面只有一页，不能一页一页地读；需要逐页阅读、做笔记的是内容。"}, {"text": "课本的封面每页都有图，孩子们很喜欢。", "explanation": "这里应该用〈插图〉。封面只有一页，不会每页都有图；每页都有图的是课本内页里的插图。"}, {"text": "孩子们给课本夹上了漂亮的封面。", "explanation": "这里应该用〈书签〉。书签是夹在书页里的，封面包在书的外面，不能把封面夹进书里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我给书换了一只新的封面。", "corrected_sentence": "我给书换了一张新的封面。", "error_description": "量词错误：“封面”前应用量词“张”，不能用“只”。“只”用于动物或成对的东西，封面是平面的纸，应说“一张新的封面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出版社请画家为这套新书设计一条封面。", "corrected_sentence": "出版社请画家为这套新书设计一个封面。", "error_description": "量词错误：“封面”应用量词“个”，不能用“条”。“条”用于细长的东西，封面不是长条形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
