INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91806, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书籍、杂志等外面的第一页，印有书名等。", "primary_collocate": null, "pronunciation": "fēng miàn", "ipa": "fəŋ˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "杂志封面上印着大大的书名。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这期杂志的封面很漂亮，印着一位歌手。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书名和作者的名字都印在封面上。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说的封面设计得很有特色。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "封面上的书名是用金色的字印的。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的照片登上了那本杂志的封面。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出版社请画家为新书设计封面。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看封面就知道这是一本儿童故事书。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本画册的封面印着一幅山水画。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这本书的封面要印上书名和出版社。", "target_word": "封面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封面设计", "label": "复合"}, {"form": "封面人物", "label": "复合"}], "register": "中性", "sense_fingerprint": "书籍、杂志外面印有书名、图画等内容的第一页", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea62575-be54-46e7-9a6e-46e7d7867e98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91806, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "封面", "is_correct": true, "explanation": "封面：书籍、杂志外面印有书名等内容的第一页。"}, {"text": "方面", "is_correct": false, "explanation": "fāng（第一声）与 fēng（第一声）韵母不同（ang 与 eng），意思是方向、方面。"}, {"text": "粉面", "is_correct": false, "explanation": "fěn（第三声）与 fēng（第一声）声调和韵母（en 与 eng）都不同，意思是米粉做的面条。"}, {"text": "发面", "is_correct": false, "explanation": "fā（第一声）与 fēng（第一声）声母相同，韵母不同，意思是发酵面团。"}], "explanations": {"封面": "封面：书籍、杂志外面印有书名等内容的第一页。", "方面": "fāng（第一声）与 fēng（第一声）韵母不同（ang 与 eng），意思是方向、方面。", "粉面": "fěn（第三声）与 fēng（第一声）声调和韵母（en 与 eng）都不同，意思是米粉做的面条。", "发面": "fā（第一声）与 fēng（第一声）声母相同，韵母不同，意思是发酵面团。"}, "sentence_index": null, "correct_answer": "封面"}, "level_3": {"options": [{"text": "封面", "is_correct": true, "explanation": "封面：杂志外面的第一页，印着书名，与句意相符。"}, {"text": "作家", "is_correct": false, "explanation": "搭配：“上印着大大的书名”说的是印刷品的表面，作家是人，不能在身上印书名。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是杂志的一部分，“杂志花园上印着书名”说不通。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间单位，没有表面可以印字，句子说不通。"}], "explanations": {"封面": "封面：杂志外面的第一页，印着书名，与句意相符。", "作家": "搭配：“上印着大大的书名”说的是印刷品的表面，作家是人，不能在身上印书名。", "花园": "语义：花园不是杂志的一部分，“杂志花园上印着书名”说不通。", "星期": "语义：星期是时间单位，没有表面可以印字，句子说不通。"}, "sentence_index": 0, "correct_answer": "封面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本小说的封面一共有三百页，很厚。", "explanation": "这里应该用〈正文〉。封面只是书外面的第一页，不会有三百页；三百页的是正文。"}, {"text": "这本小说的封面写满了作者的成长经历。", "explanation": "这里应该用〈序言〉。作者的成长经历通常写在序言或作者简介里，封面只印书名、作者名等。"}, {"text": "这本杂志的封面很长，我花了一晚上才读完。", "explanation": "这里应该用〈文章〉。读完要花时间的是文章，封面只有一页，不能读一晚上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "封面", "is_correct": true, "explanation": "封面：书或杂志外面的第一页，可以设计，与句意相符。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是书的外部部分，“为新书设计电脑”的对象不成立。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不属于书，不能成为出版社设计的对象。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体型，不是书的外观，不能用“设计”来说。"}], "explanations": {"封面": "封面：书或杂志外面的第一页，可以设计，与句意相符。", "电脑": "语义：电脑不是书的外部部分，“为新书设计电脑”的对象不成立。", "厨房": "语义：厨房不属于书，不能成为出版社设计的对象。", "身材": "体貌：身材指人的体型，不是书的外观，不能用“设计”来说。"}, "sentence_index": 6, "correct_answer": "封面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师说这本书的封面要印上章节号和页码。", "explanation": "这里应该用〈目录〉。章节号和页码列在目录里，封面只印书名、作者和出版社等。"}, {"text": "老师说这本书的封面要印上练习题。", "explanation": "这里应该用〈内页〉。练习题印在内页，封面只放书名、作者、出版社等内容。"}, {"text": "老师说这本书的封面要印上每一课的生词。", "explanation": "这里应该用〈附录〉。生词通常列在附录里，封面只印书名、作者、出版社等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本杂志有一只漂亮的封面。", "corrected_sentence": "这本杂志有一张漂亮的封面。", "error_description": "量词错误：“封面”应用量词“张”，不能用“只”。“只”用于动物或成对的东西，封面是平面的纸，应说“一张漂亮的封面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出版社为新杂志设计了一座封面。", "corrected_sentence": "出版社为新杂志设计了一张封面。", "error_description": "量词错误：“封面”应用量词“张”，不能用“座”。“座”用于建筑、山等大型固定的东西，封面不能用“座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91807, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91807, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91807, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "全都是一个也不少，所有的都是。", "primary_collocate": null, "pronunciation": "quán dōu", "ipa": "tɕʰɥɛn˧˥ tou˥", "syllable_count": 2, "sentences": [{"text": "我买的水果全都在桌子上。", "target_word": "全都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里的学生全都到了。", "target_word": "全都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的书全都放在这个箱子里。", "target_word": "全都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的作业我全都做完了。", "target_word": "全都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做的菜，我们全都吃完了。", "target_word": "全都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些东西全都带上。", "target_word": "全都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子里的饺子全都是肉馅儿的。", "target_word": "全都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们的名字我全都记住了。", "target_word": "全都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些照片全都是去年拍的。", "target_word": "全都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱包里的钱全都在，一分也不少。", "target_word": "全都", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指数量上一个也不少，所有的都在或都是", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e0a565-ff65-4751-a7de-98805f80eb54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91807, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全都", "is_correct": true, "explanation": "“全都”表示所有的水果都在桌子上，与“我买的”的范围相合，填入正确。"}, {"text": "突然", "is_correct": false, "explanation": "体貌：“突然”表示事情出乎意料地发生，这里说的是水果摆放的状态，不能说“突然在桌子上”。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从过去到现在一直如此，一般要配否定，与“在桌子上”的现时状态不通。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多与否定词连用，这里是肯定句，说“根本在桌子上”不通。"}], "explanations": {"全都": "“全都”表示所有的水果都在桌子上，与“我买的”的范围相合，填入正确。", "突然": "体貌：“突然”表示事情出乎意料地发生，这里说的是水果摆放的状态，不能说“突然在桌子上”。", "从来": "语义：“从来”表示从过去到现在一直如此，一般要配否定，与“在桌子上”的现时状态不通。", "根本": "搭配：“根本”多与否定词连用，这里是肯定句，说“根本在桌子上”不通。"}, "sentence_index": 0, "correct_answer": "全都"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子全都很结实。", "explanation": "这里应该用〈非常〉修饰“结实”。“全都”表示无一例外，要求多个对象；这里只说一把椅子，不能用来表示程度。"}, {"text": "我全都累了。", "explanation": "这里应该用〈已经〉。“全都”要求多个对象，这里只有“我”一个人，不能用来说一个人的状态。"}, {"text": "这个教室里全都有一个学生。", "explanation": "这里应该用〈只〉。“全都”表示全部，要求多个对象；“这个教室里”只有一个学生，表示范围很小，应说“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91807, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全都", "is_correct": true, "explanation": "“全都”表示所有的饺子都是肉馅儿的，符合“全”的范围，填入正确。"}, {"text": "突然", "is_correct": false, "explanation": "体貌：“突然”表示事情出乎意料地发生，不能用来描写“是肉馅儿的”这种属性。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指时间很快就要到，与表示属性的“是肉馅儿的”不搭，句子不通。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同做某事，不能修饰“是……的”这种判断，语义不通。"}], "explanations": {"全都": "“全都”表示所有的饺子都是肉馅儿的，符合“全”的范围，填入正确。", "突然": "体貌：“突然”表示事情出乎意料地发生，不能用来描写“是肉馅儿的”这种属性。", "马上": "语义：“马上”指时间很快就要到，与表示属性的“是肉馅儿的”不搭，句子不通。", "一起": "语义：“一起”表示共同做某事，不能修饰“是……的”这种判断，语义不通。"}, "sentence_index": 6, "correct_answer": "全都"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车全都很新。", "explanation": "这里应该用〈非常〉修饰“新”。“全都”要求多个对象，这里只说一辆车，不能用来表示程度。"}, {"text": "这个小孩全都三岁了。", "explanation": "这里应该用〈已经〉。“全都”表示无一例外，要求多个对象，不能用来说一个人的年龄。"}, {"text": "这本书全都很有意思。", "explanation": "这里应该用〈非常〉修饰“有意思”。“全都”表示无一例外，要求多个对象；这里只说一本书，不能用来表示程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他全都回家了。", "corrected_sentence": "他们全都回家了。", "error_description": "错误：“全都”要求多个对象，此处主语“他”为单数，与之不合。正确：他们全都回家了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91807, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家全都都同意了。", "corrected_sentence": "大家全都同意了。", "error_description": "错误：“全都”已经含有“都”的意思，后面不能再加“都”，应删去多余的“都”。正确：大家全都同意了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91809, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "汹涌", "is_correct": true, "explanation": "正确：「汹涌」形容波浪猛烈翻腾，与「平静」相对。"}, {"text": "整齐", "is_correct": false, "explanation": "与「平静」没有反义关系，指排列有序。"}, {"text": "清楚", "is_correct": false, "explanation": "与「平静」没有反义关系，指明白、不模糊。"}, {"text": "明亮", "is_correct": false, "explanation": "与「平静」没有反义关系，指光线充足。"}], "correct_answer": "汹涌", "explanations": {"汹涌": "正确：「汹涌」形容波浪猛烈翻腾，与「平静」相对。", "整齐": "与「平静」没有反义关系，指排列有序。", "清楚": "与「平静」没有反义关系，指明白、不模糊。", "明亮": "与「平静」没有反义关系，指光线充足。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
