INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91809, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有风浪，也没有吵闹，很安静。", "primary_collocate": null, "pronunciation": "píng jìng", "ipa": "pʰiŋ³⁵ tɕiŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "今天没有风，湖面很平静。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，小村子非常平静。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海面平静得像一面镜子。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴风雨过去了，海上又平静了。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很平静，几乎听不到声音。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的校园很平静，没有什么人。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船在平静的湖上慢慢走着。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们睡了，房子里一下子平静了。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小岛上的夜晚平静而美丽。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风停以后，池塘里的水面平静极了。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平静地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "水面、环境没有风浪，也没有吵闹声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a496a96-4d56-43eb-bcc0-f82a7320254a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91809, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "平静", "is_correct": true, "explanation": "正确：平静（píng jìng），指没有风浪，也没有吵闹，很安静。"}, {"text": "瓶颈", "is_correct": false, "explanation": "jǐng（第三声）与 jìng（第四声）声调不同，瓶颈指瓶子的细颈，比喻发展中的障碍。"}, {"text": "明镜", "is_correct": false, "explanation": "míng 与 píng 声母不同（m/p），明镜指明亮的镜子。"}, {"text": "评定", "is_correct": false, "explanation": "dìng 与 jìng 声母不同（d/j），评定指评价并确定等级。"}], "explanations": {"平静": "正确：平静（píng jìng），指没有风浪，也没有吵闹，很安静。", "瓶颈": "jǐng（第三声）与 jìng（第四声）声调不同，瓶颈指瓶子的细颈，比喻发展中的障碍。", "明镜": "míng 与 píng 声母不同（m/p），明镜指明亮的镜子。", "评定": "dìng 与 jìng 声母不同（d/j），评定指评价并确定等级。"}, "sentence_index": null, "correct_answer": "平静"}, "level_3": {"options": [{"text": "平静", "is_correct": true, "explanation": "正确：「平静」描述湖面没有风浪，符合「今天没有风」的句意。"}, {"text": "狂暴", "is_correct": false, "explanation": "语义：「狂暴」指猛烈，与「今天没有风」矛盾。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：「嘈杂」形容声音杂乱，不用来形容湖面。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容身材或建筑，不能用来形容湖面。"}], "explanations": {"平静": "正确：「平静」描述湖面没有风浪，符合「今天没有风」的句意。", "狂暴": "语义：「狂暴」指猛烈，与「今天没有风」矛盾。", "嘈杂": "搭配：「嘈杂」形容声音杂乱，不用来形容湖面。", "高大": "体貌：「高大」形容身材或建筑，不能用来形容湖面。"}, "sentence_index": 0, "correct_answer": "平静"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块木板很平静。", "explanation": "这里应该用〈平整〉。平静形容水面、心情、环境等没有波动，不用来形容木板等物体的表面。"}, {"text": "这首歌的节奏很平静。", "explanation": "这里应该用〈平缓〉。平静形容状态，节奏的快慢起伏要用平缓。"}, {"text": "这台机器运转得很平静。", "explanation": "这里应该用〈平稳〉。平静不用来形容机器运转，运转的稳定要用平稳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平静", "is_correct": true, "explanation": "正确：「平静的湖」指湖面没有风浪，符合句意。"}, {"text": "喧闹", "is_correct": false, "explanation": "语义：「喧闹」指人声杂乱，与湖面没有风浪的状态相反。"}, {"text": "干涸", "is_correct": false, "explanation": "语义：「干涸」指水已经干了，小船无法在湖上行驶。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：「陡峭」形容山坡或崖壁，不用来形容湖。"}], "explanations": {"平静": "正确：「平静的湖」指湖面没有风浪，符合句意。", "喧闹": "语义：「喧闹」指人声杂乱，与湖面没有风浪的状态相反。", "干涸": "语义：「干涸」指水已经干了，小船无法在湖上行驶。", "陡峭": "搭配：「陡峭」形容山坡或崖壁，不用来形容湖。"}, "sentence_index": 6, "correct_answer": "平静"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的味道很平静。", "explanation": "这里应该用〈平淡〉。平静指没有波动，味道清淡、不浓烈要用平淡。"}, {"text": "这条马路修得很平静。", "explanation": "这里应该用〈平坦〉。平静形容水面、环境没有风浪或吵闹，路面没有高低起伏要用平坦。"}, {"text": "这件衣服熨得很平静。", "explanation": "这里应该用〈平整〉。平静不用来形容衣服等物体表面没有褶皱，要用平整。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖面平静的映着月亮。", "corrected_sentence": "湖面平静地映着月亮。", "error_description": "「平静」作状语修饰动词「映」时应用「地」，不能用「的」。错误形式是「平静的映」，正确形式是「平静地映」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
