INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91810, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有波动或动荡，安稳宁静。", "primary_collocate": null, "pronunciation": "píng jìng", "ipa": "pʰiŋ³⁵ tɕiŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "她说话的声音很平静。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休以后，他每天过得很平静。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对考试结果，他的心情非常平静。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的晚年过得很平静。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了那件事以后，小城再也没有平静过。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她表面很平静，心里却很紧张。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了妈妈的话，我的心慢慢平静了。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他平静地告诉大家这个坏消息。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找一个地方，过平静的日子。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的脸上很平静，看不出生气的样子。", "target_word": "平静", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平静地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "心情、生活、神情安稳，没有波动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a496a96-4d56-43eb-bcc0-f82a7320254a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91810, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "平静", "is_correct": true, "explanation": "正确：平静（píng jìng），指没有波动、安稳宁静。"}, {"text": "瓶颈", "is_correct": false, "explanation": "jǐng（第三声）与 jìng（第四声）声调不同，瓶颈指瓶子的细颈，比喻发展中的障碍。"}, {"text": "明镜", "is_correct": false, "explanation": "míng 与 píng 声母不同（m/p），明镜指明亮的镜子。"}, {"text": "评定", "is_correct": false, "explanation": "dìng 与 jìng 声母不同（d/j），评定指评价并确定等级。"}], "explanations": {"平静": "正确：平静（píng jìng），指没有波动、安稳宁静。", "瓶颈": "jǐng（第三声）与 jìng（第四声）声调不同，瓶颈指瓶子的细颈，比喻发展中的障碍。", "明镜": "míng 与 píng 声母不同（m/p），明镜指明亮的镜子。", "评定": "dìng 与 jìng 声母不同（d/j），评定指评价并确定等级。"}, "sentence_index": null, "correct_answer": "平静"}, "level_3": {"options": [{"text": "平静", "is_correct": true, "explanation": "正确：「平静」形容声音没有起伏，符合句意。"}, {"text": "谦虚", "is_correct": false, "explanation": "语义：「谦虚」形容人的态度，不能用来形容声音。"}, {"text": "大方", "is_correct": false, "explanation": "搭配：「大方」形容言谈举止，不用来形容声音。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容身材或体格，不能用来形容声音。"}], "explanations": {"平静": "正确：「平静」形容声音没有起伏，符合句意。", "谦虚": "语义：「谦虚」形容人的态度，不能用来形容声音。", "大方": "搭配：「大方」形容言谈举止，不用来形容声音。", "高大": "体貌：「高大」形容身材或体格，不能用来形容声音。"}, "sentence_index": 0, "correct_answer": "平静"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心跳很平静。", "explanation": "这里应该用〈平稳〉。平静指心情、环境没有波动，心跳、脉搏的节律要用平稳。"}, {"text": "他的学习成绩一直很平静。", "explanation": "这里应该用〈平稳〉。平静指心情、生活没有波动，成绩没有大起大落要用平稳。"}, {"text": "他说话的语速很平静。", "explanation": "这里应该用〈平缓〉。平静形容状态，语速、节奏的快慢起伏要用平缓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平静", "is_correct": true, "explanation": "正确：「平静」指心情由激动转为安定，符合句意。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：「瘦弱」形容身体，不能用来说心变得瘦弱。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：「粗糙」指表面不光滑，不能用来形容心的状态。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：「干燥」形容空气、皮肤等，心不能用干燥来形容。"}], "explanations": {"平静": "正确：「平静」指心情由激动转为安定，符合句意。", "瘦弱": "体貌：「瘦弱」形容身体，不能用来说心变得瘦弱。", "粗糙": "语义：「粗糙」指表面不光滑，不能用来形容心的状态。", "干燥": "搭配：「干燥」形容空气、皮肤等，心不能用干燥来形容。"}, "sentence_index": 6, "correct_answer": "平静"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块桌面很平静。", "explanation": "这里应该用〈平整〉。平静形容心情、环境、水面等没有波动，不用来形容桌面等物体的表面。"}, {"text": "这种饮料的味道很平静。", "explanation": "这里应该用〈平淡〉。平静指没有波动，味道清淡、不起伏要用平淡。"}, {"text": "这条路很平静。", "explanation": "这里应该用〈平坦〉。平静不用来形容道路的平整。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他平静的接受了这个结果。", "corrected_sentence": "他平静地接受了这个结果。", "error_description": "「平静」作状语修饰动词「接受」时应用「地」，不能用「的」。错误形式是「平静的接受」，正确形式是「平静地接受」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听完这个消息，她平静的走出了房间。", "corrected_sentence": "听完这个消息，她平静地走出了房间。", "error_description": "「平静」作状语修饰动词「走出」时应用「地」，不能用「的」。错误形式是「平静的走出」，正确形式是「平静地走出」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
